fn bump(m: Map<Str, Int>, w: Str) -> Map<Str, Int> {
  let n = m.get(w).unwrap_or(0);
  let mut m2 = m;
  m2.insert(w, n + 1);
  m2
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let bytes = input.read("text.txt")?;
  let mut counts: Map<Str, Int> = Map::new();
  let mut start = 0 - 1;
  let mut i = 0;
  for b in bytes {
    let letter = (b >= 65 && b <= 90) || (b >= 97 && b <= 122);
    if letter {
      if start < 0 { start = i; }
    } else {
      if start >= 0 {
        let w = bytes.slice(start, i).to_str().to_lowercase();
        counts = bump(counts, w);
        start = 0 - 1;
      }
    }
    i += 1;
  }
  if start >= 0 {
    let w = bytes.slice(start, i).to_str().to_lowercase();
    counts = bump(counts, w);
  }
  let mut keys = counts.keys();
  let c = counts;
  keys.sort_by_key(|k| 0 - c.get(k).unwrap_or(0));
  let mut out = "";
  let n = keys.len().min(5);
  for j in 0..n {
    let k = keys[j];
    out = out + k + " " + c.get(k).unwrap_or(0).to_str() + "\n";
  }
  Ok(out)
}

struct W { w: Str, n: Int }

fn bump(m: Map<Str, Int>, w: Str) -> Map<Str, Int> {
  let mut out = m;
  let n = out.get(w).unwrap_or(0);
  out.insert(w, n + 1);
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("text.txt")?.to_str();
  let mut counts: Map<Str, Int> = Map::new();
  let mut cur = "";
  for c in text.chars() {
    let letter = c.len() == 1 && ((c >= "a" && c <= "z") || (c >= "A" && c <= "Z"));
    if letter {
      cur = cur + c.to_lowercase();
    } else {
      if cur.len() > 0 {
        counts = bump(counts, cur);
        cur = "";
      }
    }
  }
  if cur.len() > 0 {
    counts = bump(counts, cur);
  }
  let mut words: List<W> = [];
  for k in counts.keys() {
    words.push(W { w: k, n: counts.get(k).unwrap_or(0) });
  }
  words.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.w < b.w));
  let mut lines: List<Str> = [];
  let mut i = 0;
  while i < 5 && i < words.len() {
    lines.push(words[i].w + " " + words[i].n.to_str());
    i += 1;
  }
  Ok(lines.join("\n"))
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let mut data = input.read("text.txt")?;
  data.push(32);
  let mut m: Map<Str, Int> = Map::new();
  let mut cur: Bytes = "".to_bytes();
  for b in data {
    let mut c = b;
    if c >= 65 && c <= 90 { c = c + 32; }
    if c >= 97 && c <= 122 {
      cur.push(c);
    } else {
      if cur.len() > 0 {
        let w = cur.to_str();
        let n = m.get(w).unwrap_or(0);
        m.insert(w, n + 1);
        cur = "".to_bytes();
      }
    }
  }
  let mut keys = m.keys();
  let counts = m;
  keys.sort_by(|a, b| counts.get(a).unwrap_or(0) > counts.get(b).unwrap_or(0));
  let n = keys.len().min(5);
  let mut lines: List<Str> = [];
  for i in 0..n {
    let w = keys[i];
    lines.push(w + " " + counts.get(w).unwrap_or(0).to_str());
  }
  Ok(lines.join("\n"))
}

struct Agg { name: Str, qty: Int, cents: Int }

fn money(c: Int) -> Str {
  let neg = c < 0;
  let a = if neg { -c } else { c };
  let r = a % 100;
  let rs = if r < 10 { "0" + r.to_str() } else { r.to_str() };
  let s = (a / 100).to_str() + "." + rs;
  if neg { "-" + s } else { s }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let mut m: Map<Str, Agg> = Map::new();
  let mut skipped = 0;
  let mut first = true;
  for line in text.lines() {
    if first {
      first = false;
      continue;
    }
    let t = line.trim();
    if t == "" {
      continue;
    }
    let parts = t.split(",");
    if parts.len() != 5 {
      skipped += 1;
      continue;
    }
    let region = parts[1].trim();
    let Some(q) = parts[3].trim().parse_int() else {
      skipped += 1;
      continue;
    };
    let Some(u) = parts[4].trim().parse_int() else {
      skipped += 1;
      continue;
    };
    let cur = match m.get(region) {
      Some(a) => a,
      None => Agg { name: region, qty: 0, cents: 0 },
    };
    m.insert(region, Agg { name: region, qty: cur.qty + q, cents: cur.cents + q * u });
  }
  let mut rows: List<Agg> = [];
  for k in m.keys() {
    if let Some(a) = m.get(k) {
      rows.push(a);
    }
  }
  rows.sort_by(|a, b| a.cents > b.cents || (a.cents == b.cents && a.name < b.name));
  let mut lines: List<Str> = [];
  for r in rows {
    lines.push(r.name + " " + r.qty.to_str() + " " + money(r.cents));
  }
  lines.push("skipped " + skipped.to_str());
  Ok(lines.join("\n"))
}

