struct Stat { region: Str, qty: Int, cents: Int }

fn money(c: Int) -> Str {
  let neg = c < 0;
  let a = if neg { -c } else { c };
  let r = a % 100;
  let rs = if r < 10 { "0" + r.to_str() } else { r.to_str() };
  let s = (a / 100).to_str() + "." + rs;
  if neg { "-" + s } else { s }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let lines = text.lines();
  let mut totals: Map<Str, Stat> = Map::new();
  let mut skipped = 0;
  for i in 1..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let parts = line.split(",");
    if parts.len() != 5 { skipped += 1; continue; }
    let region = parts[1].trim();
    let Some(q) = parts[3].trim().parse_int() else { skipped += 1; continue; };
    let Some(u) = parts[4].trim().parse_int() else { skipped += 1; continue; };
    let mut st = match totals.get(region) {
      Some(s) => s,
      None => Stat { region: region, qty: 0, cents: 0 },
    };
    st.qty += q;
    st.cents += q * u;
    totals.insert(region, st);
  }
  let mut stats: List<Stat> = [];
  for k in totals.keys() {
    if let Some(s) = totals.get(k) { stats.push(s); }
  }
  stats.sort_by(|a, b| a.cents > b.cents || (a.cents == b.cents && a.region < b.region));
  let mut out: List<Str> = [];
  for s in stats {
    out.push(s.region + " " + s.qty.to_str() + " " + money(s.cents));
  }
  out.push("skipped " + skipped.to_str());
  Ok(out.join("\n"))
}

struct Agg { region: Str, qty: Int, cents: Int }

fn money(c: Int) -> Str {
  if c < 0 { return "-" + money(0 - c); }
  let d = c / 100;
  let r = c % 100;
  let rs = r.to_str();
  let p = if r < 10 { "0" + rs } else { rs };
  d.to_str() + "." + p
}

fn main(input: Dir) -> Result<Str, IoErr> {
