struct Entry { ip: Str, path: Str, status: Int, size: Int }
struct ErrCount { ip: Str, n: Int }

fn parse(line: Str) -> Option<Entry> {
  let parts = line.split("\"");
  if parts.len() != 3 { return None; }
  let head = parts[0];
  if !head.contains("[") { return None; }
  let ip = head.split(" ")[0];
  if ip.len() == 0 { return None; }
  let words = parts[1].split(" ");
  if words.len() < 2 { return None; }
  let mut path = words[1];
  if let Some(i) = path.find("?") { path = path.slice(0, i); }
  let rest = parts[2].trim().split(" ");
  if rest.len() != 2 { return None; }
  let status = rest[0].parse_int()?;
  let size = if rest[1] == "-" { 0 } else { rest[1].parse_int()? };
  Some(Entry { ip: ip, path: path, status: status, size: size })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total = 0;
  for line in text.lines() {
    let Some(e) = parse(line) else { continue; };
    let c = statuses.get(e.status).unwrap_or(0);
    statuses.insert(e.status, c + 1);
    total = total + e.size;
    let pc = paths.get(e.path).unwrap_or(0);
    paths.insert(e.path, pc + 1);
    if e.status >= 500 && e.status < 600 {
      let ec = errs.get(e.ip).unwrap_or(0);
      errs.insert(e.ip, ec + 1);
    }
  }
  let mut out = "";
  for s in statuses.keys() {
    out = out + s.to_str() + " " + statuses.get(s).unwrap_or(0).to_str() + "\n";
  }
  out = out + "bytes " + total.to_str() + "\n";
  let mut best = "";
  let mut bn = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > bn { bn = c; best = p; }
  }
  if bn > 0 {
    out = out + "top " + best + " " + bn.to_str() + "\n";
  }
  let mut list: List<ErrCount> = [];
  for ip in errs.keys() {
    list.push(ErrCount { ip: ip, n: errs.get(ip).unwrap_or(0) });
  }
  list.sort_by(|a, b| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for x in list {
    out = out + "errors " + x.ip + " " + x.n.to_str() + "\n";
  }
  Ok(out)
}

