    let ip = parts[0].split(" ")[0];
    if ip == "" { continue; }
    let words = parts[1].split(" ");
    if words.len() != 3 { continue; }
    let fields = parts[2].trim().split(" ");
    if fields.len() != 2 { continue; }
    let Some(status) = fields[0].parse_int() else { continue; };
    let size = if fields[1] == "-" {
      0
    } else {
      match fields[1].parse_int() {
        Some(v) => v,
        None => -1,
      }
    };
    if size < 0 { continue; }
    let mut path = words[1];
    if let Some(i) = path.find("?") {
      path = path.slice(0, i);
    }
    statuses.insert(status, statuses.get(status).unwrap_or(0) + 1);
