    out = out + s.to_str() + " " + statuses.get(s).unwrap_or(0).to_str() + "\n";
  }
  out = out + "bytes " + total.to_str() + "\n";
  let mut best = "";
  let mut bc = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > bc {
      best = p;
      bc = c;
    }
  }
  if bc > 0 {
    out = out + "top " + best + " " + bc.to_str() + "\n";
  }
