    if status == "paid" {
      counts.insert(cust, counts.get(cust).unwrap_or(0) + 1);
      totals.insert(cust, totals.get(cust).unwrap_or(0) + t);
    } else if status == "refunded" {
      ref_n = ref_n + 1;
      ref_t = ref_t + t;
    } else if status == "pending" {
