fn to_roman(n: Int) -> Str {
  let vals: List<Int> = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  let syms: List<Str> = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let mut r = "";
  let mut m = n;
  for i in 0..13 {
    while m >= vals[i] {
      r = r + syms[i];
      m -= vals[i];
    }
  }
  r
}

fn from_roman(s: Str) -> Option<Int> {
  let chars = s.chars();
  let mut total = 0;
  for i in 0..chars.len() {
    let v = val(chars[i]);
    if v == 0 { return None; }
    let mut nv = 0;
    if i + 1 < chars.len() { nv = val(chars[i + 1]); }
    if nv > v { total -= v; } else { total += v; }
  }
  if total >= 1 && total <= 3999 && to_roman(total) == s {
    Some(total)
  } else {
    None
  }
}

