fn check(line: Str) -> Str {
  let mut stack: List<Str> = [];
  let chars = line.chars();
  let mut i = 0;
  while i < chars.len() {
    let c = chars[i];
    match c {
      "(" => stack.push(")"),
      "[" => stack.push("]"),
      "{" => stack.push("}"),
      ")" | "]" | "}" => {
        let n = stack.len();
        if n == 0 {
          return "col " + (i + 1).to_str() + ": unexpected " + c;
        }
        let top = stack[n - 1];
        if top != c {
          return "col " + (i + 1).to_str() + ": expected " + top + ", found " + c;
        }
        stack = stack.slice(0, n - 1);
      }
      _ => {}
    }
    i += 1;
  }
  let n = stack.len();
  if n > 0 {
    return "unclosed " + stack[n - 1];
  }
  "ok"
}

