struct Edge { a: Str, b: Str, c: Int }
struct Trip { a: Str, b: Str }

fn dist_to(edges: List<Edge>, t: Str) -> Map<Str, Int> {
  let mut dist: Map<Str, Int> = Map::new();
  dist.insert(t, 0);
  let mut changed = true;
  while changed {
    changed = false;
    for e in edges {
      if let Some(dv) = dist.get(e.b) {
        let cand = dv + e.c;
        match dist.get(e.a) {
          None => { dist.insert(e.a, cand); changed = true; }
          Some(old) => { if cand < old { dist.insert(e.a, cand); changed = true; } }
        }
      }
    }
  }
  dist
}

fn route(edges: List<Edge>, a: Str, b: Str) -> Str {
  if a == b { return a + " 0"; }
  let dist = dist_to(edges, b);
  let Some(total) = dist.get(a) else { return a + " " + b + " unreachable"; };
  let mut cur = a;
  let mut out = a;
  while cur != b {
    let dc = dist.get(cur).unwrap_or(0);
    let mut best = "";
    let mut found = false;
    for e in edges {
      if e.a == cur {
        if let Some(dn) = dist.get(e.b) {
          if e.c + dn == dc && (!found || e.b < best) {
            best = e.b;
            found = true;
          }
        }
      }
    }
    if !found { break; }
    out = out + " -> " + best;
    cur = best;
  }
  out + " " + total.to_str()
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut edges: List<Edge> = [];
  let mut trips: List<Trip> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 || line.starts_with("#") { continue; }
    let parts = line.split(" ").filter(|p| p.len() > 0);
    if parts.len() == 4 && parts[0] == "road" {
      let Some(c) = parts[3].parse_int() else { continue; };
      edges.push(Edge { a: parts[1], b: parts[2], c: c });
      edges.push(Edge { a: parts[2], b: parts[1], c: c });
    } else if parts.len() == 3 && parts[0] == "trip" {
      trips.push(Trip { a: parts[1], b: parts[2] });
    }
  }
  let mut lines: List<Str> = [];
  for t in trips {
    lines.push(route(edges, t.a, t.b));
  }
  Ok(lines.join("\n"))
}

struct Edge { to: Str, w: Int }
struct Trip { a: Str, b: Str }

fn dijkstra(adj: Map<Str, List<Edge>>, src: Str) -> Map<Str, Int> {
  let mut dist: Map<Str, Int> = Map::new();
  let mut done: Map<Str, Bool> = Map::new();
  dist.insert(src, 0);
  loop {
    let mut best: Option<Str> = None;
    let mut bd = 0;
    for k in dist.keys() {
      if done.get(k).is_some() { continue; }
      let d = dist.get(k).unwrap_or(0);
      if best.is_none() || d < bd {
        best = Some(k);
        bd = d;
      }
    }
    let Some(u) = best else { break; };
    done.insert(u, true);
    let edges: List<Edge> = adj.get(u).unwrap_or([]);
    for e in edges {
      let nd = bd + e.w;
      let better = match dist.get(e.to) {
        None => true,
        Some(c) => nd < c,
      };
      if better { dist.insert(e.to, nd); }
    }
  }
  dist
}

fn add_edge(adj: Map<Str, List<Edge>>, a: Str, b: Str, w: Int) -> Map<Str, List<Edge>> {
  let mut m = adj;
  let mut l: List<Edge> = m.get(a).unwrap_or([]);
  l.push(Edge { to: b, w: w });
  m.insert(a, l);
  m
}

fn plan(adj: Map<Str, List<Edge>>, a: Str, b: Str) -> Str {
  if a == b { return a + " 0"; }
  let dist = dijkstra(adj, b);
  let Some(total) = dist.get(a) else { return a + " " + b + " unreachable"; };
  let mut path = a;
  let mut cur = a;
  while cur != b {
    let dcur = dist.get(cur).unwrap_or(0);
    let mut found = false;
    let mut next = "";
    let edges: List<Edge> = adj.get(cur).unwrap_or([]);
    for e in edges {
      if let Some(d) = dist.get(e.to) {
        if e.w + d == dcur {
          if !found || e.to < next {
            found = true;
            next = e.to;
          }
        }
      }
    }
    if !found { return a + " " + b + " unreachable"; }
    path = path + " -> " + next;
    cur = next;
  }
  path + " " + total.to_str()
}

