    if line.len() == 0 || line.starts_with("#") { continue; }
    let parts = line.split(" ").filter(|p| p.len() > 0);
    if parts.len() == 4 && parts[0] == "road" {
      let Some(w) = parts[3].parse_int() else { continue; };
      adj = add_edge(adj, parts[1], parts[2], w);
      adj = add_edge(adj, parts[2], parts[1], w);
    } else if parts.len() == 3 && parts[0] == "trip" {
      trips.push(Trip { a: parts[1], b: parts[2] });
    }
  }
  let mut lines: List<Str> = [];
  for t in trips {
    lines.push(plan(adj, t.a, t.b));
  }
  Ok(lines.join("\n"))
}

struct Edge { to: Int, w: Int }
struct Trip { a: Str, b: Str }

fn words(line: Str) -> List<Str> {
  let mut out: List<Str> = [];
  for p in line.replace("\t", " ").split(" ") {
    if p.len() > 0 { out.push(p); }
  }
  out
}

fn dijkstra(adj: List<List<Edge>>, src: Int, n: Int) -> List<Int> {
  let mut dist: List<Int> = [];
  let mut done: List<Bool> = [];
  for i in 0..n {
    dist.push(-1);
    done.push(false);
  }
  dist[src] = 0;
  loop {
    let mut u = -1;
    for i in 0..n {
      if !done[i] && dist[i] >= 0 {
        if u < 0 || dist[i] < dist[u] { u = i; }
      }
    }
    if u < 0 { break; }
    done[u] = true;
    for e in adj[u] {
      let nd = dist[u] + e.w;
      if dist[e.to] < 0 || nd < dist[e.to] {
        dist[e.to] = nd;
      }
    }
  }
  dist
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("routes.txt")?.to_str();
  let mut ids: Map<Str, Int> = Map::new();
  let mut names: List<Str> = [];
  let mut adj: List<List<Edge>> = [];
  let mut trips: List<Trip> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 || line.starts_with("#") { continue; }
    let w = words(line);
    if w.len() == 4 && w[0] == "road" {
      let Some(c) = w[3].parse_int() else { continue; };
      for t in [w[1], w[2]] {
        if ids.get(t).is_none() {
          ids.insert(t, names.len());
          names.push(t);
          let e: List<Edge> = [];
          adj.push(e);
        }
      }
      let ia = ids.get(w[1]).unwrap_or(0);
      let ib = ids.get(w[2]).unwrap_or(0);
      adj[ia].push(Edge { to: ib, w: c });
      adj[ib].push(Edge { to: ia, w: c });
    } else if w.len() == 3 && w[0] == "trip" {
      for t in [w[1], w[2]] {
        if ids.get(t).is_none() {
          ids.insert(t, names.len());
          names.push(t);
          let e: List<Edge> = [];
          adj.push(e);
        }
      }
      trips.push(Trip { a: w[1], b: w[2] });
    }
  }
  let n = names.len();
  let mut lines: List<Str> = [];
  for t in trips {
    let ia = ids.get(t.a).unwrap_or(0);
    let ib = ids.get(t.b).unwrap_or(0);
    if ia == ib {
      lines.push(t.a + " 0");
      continue;
    }
    let dist = dijkstra(adj, ib, n);
    if dist[ia] < 0 {
      lines.push(t.a + " " + t.b + " unreachable");
      continue;
    }
    let mut cur = ia;
    let mut path = names[ia];
    while cur != ib {
      let mut best = -1;
      for e in adj[cur] {
        if dist[e.to] >= 0 && e.w + dist[e.to] == dist[cur] {
          if best < 0 || names[e.to] < names[best] { best = e.to; }
        }
      }
      cur = best;
      path = path + " -> " + names[best];
    }
    lines.push(path + " " + dist[ia].to_str());
  }
  Ok(lines.join("\n"))
}

fn merge(base: Json, over: Json) -> Json {
  let Some(om) = over.as_map() else { return over; };
  let empty: Map<Str, Json> = Map::new();
  let mut res = base.as_map().unwrap_or(empty);
  for k in om.keys() {
    let Some(v) = om.get(k) else { continue; };
    match v {
      Json::Null => { res.remove(k); }
      Json::Obj(_) => {
        let b = res.get(k).unwrap_or(Json::Null);
        res.insert(k, merge(b, v));
      }
      _ => { res.insert(k, v); }
    }
  }
  Json::Obj(res)
}

fn flatten(prefix: Str, j: Json) -> List<Str> {
  let mut out: List<Str> = [];
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        out.push(prefix + "={}");
      } else {
        for k in m.keys() {
          let Some(v) = m.get(k) else { continue; };
          let p = if prefix == "" { k } else { prefix + "." + k };
          for line in flatten(p, v) { out.push(line); }
        }
      }
    }
    Json::Arr(l) => {
      if l.len() == 0 {
        out.push(prefix + "=[]");
      } else {
        for i in 0..l.len() {
          let p = if prefix == "" { i.to_str() } else { prefix + "." + i.to_str() };
          for line in flatten(p, l[i]) { out.push(line); }
        }
      }
    }
    _ => { out.push(prefix + "=" + j.to_json()); }
  }
  out
}

