struct Leaf { path: Str, val: Str }

fn merge(b: Json, o: Json) -> Json {
  match o {
    Json::Obj(om) => {
      let e: Map<Str, Json> = Map::new();
      let mut r = b.as_map().unwrap_or(e);
      for k in om.keys() {
        let v = om.get(k).unwrap_or(Json::Null);
        match v {
          Json::Null => { r.remove(k); }
          _ => {
            let base = r.get(k).unwrap_or(Json::Null);
            r.insert(k, merge(base, v));
          }
        }
      }
      Json::Obj(r)
    }
    _ => o,
  }
}

fn join(path: Str, k: Str) -> Str {
  if path == "" { k } else { path + "." + k }
}

fn flatten(path: Str, j: Json) -> List<Leaf> {
  let mut out: List<Leaf> = [];
  match j {
    Json::Obj(m) => {
      if m.len() == 0 {
        out.push(Leaf { path: path, val: "{}" });
      } else {
        for k in m.keys() {
          let v = m.get(k).unwrap_or(Json::Null);
          for l in flatten(join(path, k), v) { out.push(l); }
        }
      }
    }
    Json::Arr(a) => {
      if a.len() == 0 {
        out.push(Leaf { path: path, val: "[]" });
      } else {
        let mut i = 0;
        for v in a {
          for l in flatten(join(path, i.to_str()), v) { out.push(l); }
          i += 1;
        }
      }
    }
    _ => { out.push(Leaf { path: path, val: j.to_json() }); }
  }
  out
}

