struct Row { path: Str, bytes: Int, lines: Int }

fn walk(d: Dir, dir: Str, rows: List<Row>) -> Result<List<Row>, IoErr> {
  let mut out = rows;
  let names = d.list(dir)?;
  let prefix = if dir == "" { "" } else { dir + "/" };
  for name in names {
    if let Some(sub) = name.strip_suffix("/") {
      out = walk(d, prefix + sub, out)?;
    } else {
      let path = prefix + name;
      let data = d.read(path)?;
      let mut nl = 0;
      for b in data {
        if b == 10 { nl += 1; }
      }
      let n = data.len();
      if n > 0 && data[n - 1] != 10 { nl += 1; }
      out.push(Row { path: path, bytes: n, lines: nl });
    }
  }
  Ok(out)
}

