  let cs = line.chars();
  let n = cs.len();
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut inq = false;
  let mut i = 0;
  while i < n {
    let c = cs[i];
    if inq {
      if c == "\"" {
        if i + 1 < n && cs[i + 1] == "\"" {
          cur = cur + "\"";
          i = i + 2;
          continue;
        } else {
          inq = false;
        }
      } else {
        cur = cur + c;
      }
    } else {
      if c == "\"" {
        inq = true;
      } else if c == "," {
        fields.push(cur);
        cur = "";
      } else {
        cur = cur + c;
      }
    }
    i = i + 1;
  }
  fields.push(cur);
  fields
}

