fn normalize(name: Str) -> Str {
  let mut res = "";
  let mut last_dash = false;
  for c in name.to_lowercase().chars() {
    let ok = (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == ".";
    if ok {
      res = res + c;
      last_dash = false;
    } else if !last_dash {
      res = res + "-";
      last_dash = true;
    }
  }
  let mut r = res;
  loop {
    if let Some(x) = r.strip_prefix("-") { r = x; } else { break; }
  }
  loop {
    if let Some(x) = r.strip_suffix("-") { r = x; } else { break; }
  }
  r
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let mut names = input.list("")?;
  names.sort();
  let mut taken: Map<Str, Bool> = Map::new();
  let mut lines: List<Str> = [];
  for name in names {
    let new_name = normalize(name);
    let dup = taken.get(new_name).is_some();
    if new_name.len() == 0 || dup {
      lines.push(name + " skipped");
    } else {
      let data = input.read(name)?;
      out.create(new_name, data)?;
      taken.insert(new_name, true);
      lines.push(name + " -> " + new_name);
    }
  }
  Ok(lines.join("\n"))
}

fn is_part(name: Str) -> Bool {
  if name.len() != 13 { return false; }
  if name.chars().len() != 13 { return false; }
  if !name.starts_with("part-") || !name.ends_with(".txt") { return false; }
  for c in name.slice(5, 9).chars() {
    if !"0123456789".contains(c) { return false; }
  }
  true
}

fn parse_part(text: Str) -> Option<List<Int>> {
  let mut vals: List<Int> = [];
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    let n = t.parse_int()?;
    vals.push(n);
  }
  Some(vals)
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let names = input.list("")?;
  let mut all: List<Int> = [];
  let mut parts = 0;
  let mut corrupt = 0;
  for name in names {
    if !is_part(name) { continue; }
    parts += 1;
    let text = input.read(name)?.to_str();
    match parse_part(text) {
      Some(vals) => {
        for v in vals { all.push(v); }
      }
      None => corrupt += 1,
    }
  }
  all.sort();
  let mut body = "";
  let mut count = 0;
  let mut has_last = false;
  let mut last = 0;
  for v in all {
    if has_last && v == last { continue; }
    has_last = true;
    last = v;
    body = body + v.to_str() + "\n";
    count += 1;
  }
  out.write("merged.txt", body.to_bytes())?;
  Ok("parts " + parts.to_str() + " corrupt " + corrupt.to_str() + " values " + count.to_str())
}

fn main(src: Dir, dst: Dir) -> Result<Str, IoErr> {
  let s = src.list("")?;
  let d = dst.list("")?;
  let mut names = s;
  names.sort();
  let mut out = "";
  for name in names {
    let data = src.read(name)?;
    if d.contains(name) {
      let prev = dst.read(name)?;
      if prev == data {
        out = out + "same " + name + "\n";
      } else {
        dst.write(name, data)?;
        out = out + "updated " + name + "\n";
      }
    } else {
      dst.write(name, data)?;
      out = out + "added " + name + "\n";
    }
  }
  let mut kept = 0;
  for n in d {
    if !s.contains(n) {
      kept = kept + 1;
    }
  }
  out = out + "kept " + kept.to_str() + "\n";
  Ok(out)
}

