  let mut local: Map<Str, Int> = Map::new();
  for line in bytes.to_str().lines() {
    let p = line.trim();
    if p.len() == 0 { continue; }
    let k = "p:" + p;
    let c = local.get(k).unwrap_or(0);
    local.insert(k, c + 1);
  }
  for k in local.keys() {
    let n = local.get(k).unwrap_or(0);
    match counts.add(k, n) {
      Ok(_) => {},
      Err(_) => return Err("kv add failed"),
    }
  }
  let mut rows: List<Row> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = match counts.scan("p:", after, 1000) {
      Ok(p) => p,
      Err(_) => return Err("kv scan failed"),
    };
    for e in page {
      rows.push(Row {
        page: e.key.slice(2, e.key.len()),
        total: e.value.to_str().parse_int().unwrap_or(0),
      });
      after = Some(e.key);
    }
    if page.len() < 1000 { break; }
  }
  rows.sort_by(|a, b| a.total > b.total || (a.total == b.total && a.page < b.page));
  let mut lines: List<Str> = [];
  for r in rows {
    lines.push(r.page + " " + r.total.to_str());
  }
  Ok(lines.join("\n"))
}

