fn key(id: Str) -> Str {
  "user:" + id
}

fn words(line: Str) -> List<Str> {
  let mut parts: List<Str> = [];
  for p in line.split(" ") {
    if p.len() > 0 { parts.push(p); }
  }
  parts
}

fn run_cmd(users: Kv, line: Str) -> Result<Str, KvErr> {
  let parts = words(line);
  let n = parts.len();
  if n == 0 { return Ok("bad " + line); }
  let cmd = parts[0];
  if cmd == "put" && n == 4 {
    let id = parts[1];
    users.set(key(id), (parts[2] + " " + parts[3]).to_bytes())?;
    return Ok("ok " + id);
  }
  if cmd == "rename" && n == 3 {
    let id = parts[1];
    return match users.get(key(id))? {
      Some(b) => {
        let p = words(b.to_str());
        users.set(key(id), (parts[2] + " " + p[1]).to_bytes())?;
        Ok("ok " + id)
      }
      None => Ok("missing " + id),
    };
  }
  if cmd == "get" && n == 2 {
    let id = parts[1];
    return match users.get(key(id))? {
      Some(b) => {
        let p = words(b.to_str());
        Ok("{\"id\":" + Json::Str(id).to_json() + ",\"name\":" + Json::Str(p[0]).to_json() + ",\"email\":" + Json::Str(p[1]).to_json() + "}")
      }
      None => Ok("missing " + id),
    };
  }
  if cmd == "del" && n == 2 {
    let id = parts[1];
    return match users.get(key(id))? {
      Some(_) => {
        users.delete(key(id))?;
        Ok("ok " + id)
      }
      None => Ok("missing " + id),
    };
  }
  if cmd == "count" && n == 1 {
    let ks = users.keys("user:")?;
    return Ok("count " + ks.len().to_str());
  }
  Ok("bad " + line)
}

fn main(input: Dir, users: Kv) -> Result<Str, Str> {
  let bytes = match input.read("commands.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read commands.txt"),
  };
  let text = bytes.to_str();
  let mut out: List<Str> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    match run_cmd(users, line) {
      Ok(s) => out.push(s),
      Err(_) => return Err("kv error"),
    }
  }
  Ok(out.join("\n"))
}

struct Ev { id: Str, account: Str, cents: Int }

fn parse_ev(line: Str) -> Option<Ev> {
  let Ok(j) = line.parse_json() else { return None; };
  let Some(_m) = j.as_map() else { return None; };
  let id = j.get("id").and_then(|x| x.as_str())?;
  let account = j.get("account").and_then(|x| x.as_str())?;
  let cents = j.get("cents").and_then(|x| x.as_int())?;
  if id.len() > 1000 || account.len() > 1000 { return None; }
  Some(Ev { id: id, account: account, cents: cents })
}

fn apply(state: Kv, line: Str) -> Result<Int, KvErr> {
  let Some(ev) = parse_ev(line) else { return Ok(2); };
  let claimed = state.swap("seen/" + ev.id, None, Some("1".to_bytes()))?;
  if !claimed { return Ok(1); }
  state.add("bal/" + ev.account, ev.cents)?;
  Ok(0)
}

fn report(state: Kv, text: Str) -> Result<Str, KvErr> {
  let mut applied = 0;
  let mut dup = 0;
  let mut rej = 0;
  for raw in text.lines() {
    let line = raw.trim();
    if line.len() == 0 { continue; }
    let r = apply(state, line)?;
    if r == 0 { applied += 1; } else if r == 1 { dup += 1; } else { rej += 1; }
  }
  let mut out = "applied " + applied.to_str() + " duplicate " + dup.to_str() + " rejected " + rej.to_str();
  let keys = state.keys("bal/")?;
  for k in keys {
    let name = k.strip_prefix("bal/").unwrap_or(k);
    let v = match state.get(k)? {
      Some(b) => b.to_str().parse_int().unwrap_or(0),
      None => 0,
    };
    out = out + "\n" + name + " " + v.to_str();
  }
  Ok(out)
}

fn main(input: Dir, state: Kv) -> Result<Str, Str> {
  let bytes = match input.read("events.jsonl") {
    Ok(b) => b,
    Err(_) => return Err("cannot read events.jsonl"),
  };
  report(state, bytes.to_str()).map_err(|e| "kv error")
}

fn process(limits: Kv, line: Str) -> Result<Option<Str>, KvErr> {
  let parts = line.trim().split(" ").filter(|p| p.len() > 0);
  if parts.len() != 2 { return Ok(None); }
  let Some(ts) = parts[0].parse_int() else { return Ok(None); };
  let client = parts[1];
  let key = "w:" + client + ":" + (ts / 60).to_str();
  let count = match limits.get(key)? {
    Some(b) => b.to_str().parse_int().unwrap_or(0),
    None => 0,
  };
  let prefix = parts[0] + " " + client;
  if count >= 3 {
    return Ok(Some(prefix + " deny"));
  }
  limits.set(key, (count + 1).to_str().to_bytes())?;
  Ok(Some(prefix + " allow"))
}

fn main(input: Dir, limits: Kv) -> Result<Str, Str> {
  let bytes = match input.read("requests.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read requests.txt"),
  };
  let text = bytes.to_str();
  let mut out: List<Str> = [];
  for line in text.lines() {
    match process(limits, line) {
      Ok(Some(s)) => out.push(s),
      Ok(None) => {},
      Err(_) => return Err("kv error"),
    }
  }
  if out.len() == 0 { return Ok(""); }
  Ok(out.join("\n") + "\n")
}

struct Player { name: Str, pts: Int, gp: Int }

fn bump(board: Kv, name: Str, pts: Int) -> Result<(), Str> {
  board.add("pts:" + name, pts).map_err(|e| "kv error")?;
  board.add("gp:" + name, 1).map_err(|e| "kv error")?;
  Ok(())
}

fn less(a: Player, b: Player) -> Bool {
  if a.pts != b.pts { return a.pts > b.pts; }
  if a.gp != b.gp { return a.gp < b.gp; }
  a.name < b.name
}

fn main(input: Dir, board: Kv) -> Result<Str, Str> {
  let text = input.read("games.txt").map_err(|e| "read error")?.to_str();
  for raw in text.lines() {
    let parts = raw.trim().split(" ");
    if parts.len() == 2 {
      bump(board, parts[0], 3)?;
      bump(board, parts[1], 0)?;
    } else if parts.len() == 3 && parts[2] == "draw" {
      bump(board, parts[0], 1)?;
      bump(board, parts[1], 1)?;
    }
  }
  let keys = board.keys("pts:").map_err(|e| "kv error")?;
  let mut players: List<Player> = [];
  for k in keys {
    let name = k.strip_prefix("pts:").unwrap_or(k);
    let pts = board.add("pts:" + name, 0).map_err(|e| "kv error")?;
    let gp = board.add("gp:" + name, 0).map_err(|e| "kv error")?;
    players.push(Player { name: name, pts: pts, gp: gp });
  }
  players.sort_by(less);
  let n = players.len().min(3);
  let mut lines: List<Str> = [];
  for i in 0..n {
    let p = players[i];
    lines.push((i + 1).to_str() + ". " + p.name + " " + p.pts.to_str() + " " + p.gp.to_str());
  }
  Ok(lines.join("\n"))
}

