fn insert_row(shop: Db, line: Str) -> Result<Int, Str> {
  let parts = line.split(",");
  if parts.len() != 5 { return Ok(-1); }
  let Some(id) = parts[0].trim().parse_int() else { return Ok(-1); };
  let Some(qty) = parts[3].trim().parse_int() else { return Ok(-1); };
  let Some(cents) = parts[4].trim().parse_int() else { return Ok(-1); };
  let n = shop.exec(
    "INSERT OR IGNORE INTO orders (order_id, customer, product, qty, unit_cents) VALUES (?, ?, ?, ?, ?)",
    [SqlValue::Int(id), SqlValue::Text(parts[1]), SqlValue::Text(parts[2]), SqlValue::Int(qty), SqlValue::Int(cents)]
  ).map_err(|e| "db error")?;
  if n > 0 { Ok(1) } else { Ok(0) }
}

fn main(input: Dir, shop: Db) -> Result<Str, Str> {
  let bytes = match input.read("orders.csv") {
    Ok(b) => b,
    Err(_) => return Err("cannot read orders.csv"),
  };
  let text = bytes.to_str();
  shop.exec(
    "CREATE TABLE IF NOT EXISTS orders (order_id INTEGER PRIMARY KEY, customer TEXT NOT NULL, product TEXT NOT NULL, qty INTEGER NOT NULL, unit_cents INTEGER NOT NULL)",
    []
  ).map_err(|e| "db error")?;
  let mut imported = 0;
  let mut skipped = 0;
  let mut rejected = 0;
  let mut first = true;
  for raw in text.lines() {
    if first { first = false; continue; }
    let line = raw.trim();
    if line.len() == 0 { continue; }
    let r = insert_row(shop, line)?;
    if r == 1 { imported += 1; } else if r == 0 { skipped += 1; } else { rejected += 1; }
  }
  let mut out = "imported " + imported.to_str() + " skipped " + skipped.to_str() + " rejected " + rejected.to_str();
  let rows = shop.query(
    "SELECT product, SUM(qty * unit_cents) AS rev, COUNT(*) FROM orders GROUP BY product ORDER BY rev DESC, product ASC LIMIT 3",
    []
  ).map_err(|e| "db error")?;
  for r in rows {
    out = out + "\n" + cell(r[0]) + " " + cell(r[1]) + " " + cell(r[2]);
  }
  Ok(out)
}

