struct Agg { country: Str, customers: Int, orders: Int, revenue: Int, top: Str, top_rev: Int }

fn int_of(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(i) => i,
    _ => 0,
  }
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    _ => "",
  }
}

fn main(shop: Db) -> Result<Str, DbErr> {
  let sql = "SELECT c.country, c.id, c.name, COUNT(*), SUM(o.total_cents) FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.status = 'paid' AND o.placed >= '2026-01-01' AND o.placed < '2027-01-01' GROUP BY c.id ORDER BY c.country, c.id";
  let rows = shop.query(sql, [])?;
  let mut aggs: List<Agg> = [];
  for r in rows {
    let country = text_of(r[0]);
    let name = text_of(r[2]);
    let n = int_of(r[3]);
    let rev = int_of(r[4]);
    let last = aggs.len() - 1;
    if aggs.len() > 0 && aggs[last].country == country {
      let mut a = aggs[last];
      a.customers = a.customers + 1;
      a.orders = a.orders + n;
      a.revenue = a.revenue + rev;
      if rev > a.top_rev {
        a.top = name;
        a.top_rev = rev;
      }
      aggs[last] = a;
    } else {
      aggs.push(Agg { country: country, customers: 1, orders: n, revenue: rev, top: name, top_rev: rev });
    }
  }
  aggs.sort_by(|a, b| a.revenue > b.revenue || (a.revenue == b.revenue && a.country < b.country));
  let mut lines: List<Str> = [];
  let mut total_orders = 0;
  let mut total_rev = 0;
  for a in aggs {
    lines.push(a.country + " customers=" + a.customers.to_str() + " orders=" + a.orders.to_str() + " revenue=" + a.revenue.to_str() + " top=" + a.top);
    total_orders = total_orders + a.orders;
    total_rev = total_rev + a.revenue;
  }
  lines.push("total orders=" + total_orders.to_str() + " revenue=" + total_rev.to_str());
  Ok(lines.join("\n"))
}

struct Move { sku: Str, delta: Int }
struct Batch { name: Str, moves: List<Move>, bad: Bool }

fn parse_move(line: Str) -> Option<Move> {
  let parts = line.split(" ");
  if parts.len() != 2 { return None; }
  let sku = parts[0];
  let t = parts[1];
  if sku.len() == 0 { return None; }
  let mut sign = 1;
  let mut rest = "";
  if let Some(r) = t.strip_prefix("+") {
    rest = r;
  } else if let Some(r) = t.strip_prefix("-") {
    sign = -1;
    rest = r;
  } else {
    return None;
  }
  if rest.len() == 0 { return None; }
  if rest.starts_with("+") || rest.starts_with("-") { return None; }
  let n = rest.parse_int()?;
  if n <= 0 { return None; }
  Some(Move { sku: sku, delta: sign * n })
}

fn parse_batches(text: Str) -> List<Batch> {
  let mut batches: List<Batch> = [];
  for raw in text.lines() {
    let line = raw.trim();
    if line == "" { continue; }
    if let Some(name) = line.strip_prefix("batch ") {
      batches.push(Batch { name: name.trim(), moves: [], bad: false });
    } else {
      if batches.len() == 0 { continue; }
      let i = batches.len() - 1;
      match parse_move(line) {
        Some(m) => batches[i].moves.push(m),
        None => batches[i].bad = true,
      }
    }
  }
  batches
}

fn qty(stock: Db, sku: Str) -> Result<Int, DbErr> {
  let rows = stock.query("SELECT qty FROM stock WHERE sku = ?", [SqlValue::Text(sku)])?;
  if rows.len() == 0 { return Ok(0); }
  match rows[0][0] {
    SqlValue::Int(n) => Ok(n),
    _ => Ok(0),
  }
}

fn apply(stock: Db, b: Batch) -> Result<Str, DbErr> {
  let rows = stock.query("SELECT 1 FROM applied WHERE name = ?", [SqlValue::Text(b.name)])?;
  if rows.len() > 0 { return Ok("skipped"); }
  if b.bad { return Ok("rejected"); }
  let mut cur: Map<Str, Int> = Map::new();
  for m in b.moves {
    let base = match cur.get(m.sku) {
      Some(v) => v,
      None => qty(stock, m.sku)?,
    };
    let nv = base + m.delta;
    if nv < 0 { return Ok("rejected"); }
    cur.insert(m.sku, nv);
  }
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  for k in cur.keys() {
    let v = cur.get(k).unwrap_or(0);
    stmts.push("INSERT INTO stock(sku, qty) VALUES(?, ?) ON CONFLICT(sku) DO UPDATE SET qty = excluded.qty");
    params.push([SqlValue::Text(k), SqlValue::Int(v)]);
  }
  stmts.push("INSERT INTO applied(name) VALUES(?)");
  params.push([SqlValue::Text(b.name)]);
  stock.transaction(stmts, params)?;
  Ok("applied")
}

fn run(input: Dir, stock: Db) -> Result<Str, Str> {
  let bytes = match input.read("moves.txt") {
    Ok(b) => b,
    Err(_) => return Err("cannot read moves.txt"),
  };
  let text = bytes.to_str();
  let batches = parse_batches(text);
  match stock.exec("CREATE TABLE IF NOT EXISTS applied (name TEXT PRIMARY KEY)", []) {
    Ok(_) => {},
    Err(_) => return Err("db error"),
  }
  match stock.exec("CREATE TABLE IF NOT EXISTS stock (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL)", []) {
    Ok(_) => {},
    Err(_) => return Err("db error"),
  }
  let mut out = "";
  for b in batches {
    let name = b.name;
    match apply(stock, b) {
      Ok(s) => { out = out + name + " " + s + "\n"; },
      Err(_) => return Err("db error"),
    }
  }
  let rows = match stock.query("SELECT sku, qty FROM stock WHERE qty <> 0 ORDER BY sku", []) {
    Ok(r) => r,
    Err(_) => return Err("db error"),
  };
  for row in rows {
    let sku = match row[0] {
      SqlValue::Text(s) => s,
      _ => "",
    };
    let q = match row[1] {
      SqlValue::Int(n) => n,
      _ => 0,
    };
    out = out + sku + " " + q.to_str() + "\n";
  }
  Ok(out)
}

fn main(input: Dir, stock: Db) -> Result<Str, Str> {
  run(input, stock)
}

