fn main(input: Dir, crm: Db) -> Result<Str, Str> {
  crm.exec("CREATE TABLE IF NOT EXISTS contacts (email TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL)", []).map_err(|e| "db error")?;
  let raw = input.read("contacts.csv").map_err(|e| "read error")?;
  let content = raw.to_str();
  let mut inserted = 0;
  let mut updated = 0;
  let mut unchanged = 0;
  let mut rejected = 0;
  let mut idx = 0;
  for line in content.lines() {
    idx += 1;
    if idx == 1 { continue; }
    if line.trim() == "" { continue; }
    let parts = line.split(",");
    if parts.len() != 3 {
      rejected += 1;
      continue;
    }
    let email = parts[0].trim().to_lowercase();
    if !email.contains("@") {
      rejected += 1;
      continue;
    }
    let name = parts[1].trim();
    let phone = parts[2].trim();
    let rows = crm.query("SELECT name, phone FROM contacts WHERE email = ?", [SqlValue::Text(email)]).map_err(|e| "db error")?;
    if rows.len() == 0 {
      crm.exec("INSERT INTO contacts (email, name, phone) VALUES (?, ?, ?)", [SqlValue::Text(email), SqlValue::Text(name), SqlValue::Text(phone)]).map_err(|e| "db error")?;
      inserted += 1;
    } else {
      let old_name = text(rows[0][0]);
      let old_phone = text(rows[0][1]);
      if old_name != name || old_phone != phone {
        crm.exec("UPDATE contacts SET name = ?, phone = ? WHERE email = ?", [SqlValue::Text(name), SqlValue::Text(phone), SqlValue::Text(email)]).map_err(|e| "db error")?;
        updated += 1;
      } else {
        unchanged += 1;
      }
    }
  }
  let cnt = crm.query("SELECT COUNT(*) FROM contacts", []).map_err(|e| "db error")?;
  let total = match cnt[0][0] {
    SqlValue::Int(n) => n,
    _ => 0,
  };
  let mut out = "inserted " + inserted.to_str() + " updated " + updated.to_str() + " unchanged " + unchanged.to_str() + " rejected " + rejected.to_str() + "\n";
  out = out + "contacts " + total.to_str();
  let missing = crm.query("SELECT email FROM contacts WHERE phone = '' ORDER BY email", []).map_err(|e| "db error")?;
  for r in missing {
    out = out + "\nmissing phone: " + text(r[0]);
  }
  Ok(out)
}

struct Item { name: Str, count: Int }

fn respond(res: Outgoing, status: Int, body: Str) -> Result<Str, WebErr> {
  res.send(status, ["content-type"], ["application/json"], body.to_bytes())?;
  Ok("")
}

fn valid(name: Str) -> Bool {
  let n = name.len();
  if n < 1 || n > 32 { return false; }
  for c in name.chars() {
    let ok = (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "-";
    if !ok { return false; }
  }
  true
}

fn entry(name: Str, count: Int) -> Str {
  "{\"name\": \"" + name + "\", \"count\": " + count.to_str() + "}"
}

fn all_items(counts: Kv) -> Result<List<Item>, KvErr> {
  let mut items: List<Item> = [];
  let mut after: Option<Str> = None;
  loop {
    let page = counts.scan("c/", after, 1000)?;
    for e in page {
      items.push(Item {
        name: e.key.slice(2, e.key.len()),
        count: e.value.to_str().parse_int().unwrap_or(0),
      });
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  Ok(items)
}

fn main(req: Incoming, res: Outgoing, counts: Kv) -> Result<Str, WebErr> {
  let m = req.method();
  let t = req.target();
  let fail = "{\"error\": \"internal error\"}";
  if m == "POST" {
    if let Some(name) = t.strip_prefix("/hit/") {
      if !valid(name) { return respond(res, 400, "{\"error\": \"bad name\"}"); }
      return match counts.add("c/" + name, 1) {
        Ok(n) => respond(res, 200, entry(name, n)),
        Err(_) => respond(res, 500, fail),
      };
    }
  }
  if m == "GET" {
    if let Some(name) = t.strip_prefix("/count/") {
      if !valid(name) { return respond(res, 400, "{\"error\": \"bad name\"}"); }
      return match counts.get("c/" + name) {
        Ok(v) => {
          let n = match v {
            Some(b) => b.to_str().parse_int().unwrap_or(0),
            None => 0,
          };
          respond(res, 200, entry(name, n))
        }
        Err(_) => respond(res, 500, fail),
      };
    }
    if t == "/top" {
      return match all_items(counts) {
        Ok(items) => {
          let mut xs = items;
          xs.sort_by(|a, b| a.count > b.count || (a.count == b.count && a.name < b.name));
          let mut parts: List<Str> = [];
          let mut i = 0;
          while i < xs.len() && i < 3 {
            parts.push(entry(xs[i].name, xs[i].count));
            i += 1;
          }
          respond(res, 200, "[" + parts.join(", ") + "]")
        }
        Err(_) => respond(res, 500, fail),
      };
    }
  }
  respond(res, 404, "{\"error\": \"not found\"}")
}

fn pad(id: Int) -> Str {
  let mut s = id.to_str();
  while s.len() < 12 { s = "0" + s; }
  s
}

fn key(id: Int) -> Str { "todo/" + pad(id) }

fn respond(res: Outgoing, status: Int, body: Str) -> Result<(), WebErr> {
  res.send(status, ["content-type"], ["application/json"], body.to_bytes())
}

fn respond_empty(res: Outgoing) -> Result<(), WebErr> {
  res.send(204, [], [], "".to_bytes())
}

fn err_json(msg: Str) -> Str {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Json::Obj(m).to_json()
}

fn fail(res: Outgoing, status: Int, msg: Str) -> Result<(), WebErr> {
  respond(res, status, err_json(msg))
}

fn todo_json(id: Int, title: Str, done: Bool) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("title", Json::Str(title));
  m.insert("done", Json::Bool(done));
  Json::Obj(m)
}

fn create(res: Outgoing, store: Kv, body: Bytes) -> Result<(), WebErr> {
  let title_opt = match body.to_str().parse_json() {
    Ok(j) => j.get("title").and_then(|t| t.as_str()),
    Err(_) => None,
  };
  let Some(raw) = title_opt else { return fail(res, 400, "title required"); };
  let title = raw.trim();
  if title.len() == 0 { return fail(res, 400, "title required"); }
  let Ok(id) = store.add("next", 1) else { return fail(res, 500, "store error"); };
  let todo = todo_json(id, title, false);
  match store.set(key(id), todo.to_json().to_bytes()) {
    Ok(_) => {}
    Err(_) => return fail(res, 500, "store error"),
  }
  respond(res, 201, todo.to_json())
}

fn list(res: Outgoing, store: Kv, query: Str) -> Result<(), WebErr> {
  let mut filter: Option<Bool> = None;
  for q in query.split("&") {
    if q == "done=true" { filter = Some(true); }
    else if q == "done=false" { filter = Some(false); }
  }
  let mut items: List<Json> = [];
  let mut after: Option<Str> = None;
  loop {
    let Ok(page) = store.scan("todo/", after, 1000) else { return fail(res, 500, "store error"); };
    for e in page {
      match e.value.to_str().parse_json() {
        Ok(j) => {
          let include = match filter {
            None => true,
            Some(f) => j.get("done").and_then(|d| d.as_bool()).unwrap_or(false) == f,
          };
          if include { items.push(j); }
        }
        Err(_) => {}
      }
    }
    if page.len() < 1000 { break; }
    after = Some(page[page.len() - 1].key);
  }
  respond(res, 200, Json::Arr(items).to_json())
}

fn patch(res: Outgoing, store: Kv, id: Int, body: Bytes) -> Result<(), WebErr> {
  let bad = "bad update";
  let Ok(b) = body.to_str().parse_json() else { return fail(res, 400, bad); };
  let Json::Obj(_) = b else { return fail(res, 400, bad); };
  let mut new_title: Option<Str> = None;
  let mut new_done: Option<Bool> = None;
  if let Some(t) = b.get("title") {
    let Some(s) = t.as_str() else { return fail(res, 400, bad); };
    let s2 = s.trim();
    if s2.len() == 0 { return fail(res, 400, bad); }
    new_title = Some(s2);
  }
  if let Some(d) = b.get("done") {
    let Some(v) = d.as_bool() else { return fail(res, 400, bad); };
    new_done = Some(v);
  }
  let k = key(id);
  loop {
    let Ok(Some(old)) = store.get(k) else { return fail(res, 404, "not found"); };
    let Ok(cur) = old.to_str().parse_json() else { return fail(res, 500, "store error"); };
    let title = match new_title {
      Some(t) => t,
      None => cur.get("title").and_then(|x| x.as_str()).unwrap_or(""),
    };
    let done = match new_done {
      Some(d) => d,
      None => cur.get("done").and_then(|x| x.as_bool()).unwrap_or(false),
    };
    let todo = todo_json(id, title, done);
    match store.swap(k, Some(old), Some(todo.to_json().to_bytes())) {
      Ok(true) => return respond(res, 200, todo.to_json()),
      Ok(false) => {}
      Err(_) => return fail(res, 500, "store error"),
    }
  }
}

fn item(res: Outgoing, store: Kv, method: Str, id: Int, body: Bytes) -> Result<(), WebErr> {
  let k = key(id);
  let existing = match store.get(k) {
    Ok(Some(b)) => b.to_str().parse_json().ok(),
    _ => None,
  };
  let Some(todo) = existing else { return fail(res, 404, "not found"); };
  if method == "GET" {
    respond(res, 200, todo.to_json())
  } else if method == "PATCH" {
    patch(res, store, id, body)
  } else if method == "DELETE" {
    match store.delete(k) {
      Ok(_) => respond_empty(res),
      Err(_) => fail(res, 500, "store error"),
    }
  } else {
    fail(res, 404, "not found")
  }
}

fn route(req: Incoming, res: Outgoing, store: Kv) -> Result<(), WebErr> {
  let method = req.method();
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  if path == "/todos" {
    if method == "POST" {
      create(res, store, req.body())
    } else if method == "GET" {
      list(res, store, query)
    } else {
      fail(res, 404, "not found")
    }
  } else if let Some(rest) = path.strip_prefix("/todos/") {
    let Some(id) = rest.parse_int() else { return fail(res, 404, "not found"); };
    if id < 1 || id.to_str() != rest { return fail(res, 404, "not found"); }
    if method == "GET" || method == "DELETE" {
      item(res, store, method, id, "".to_bytes())
    } else if method == "PATCH" {
      item(res, store, method, id, req.body())
    } else {
      fail(res, 404, "not found")
    }
  } else {
    fail(res, 404, "not found")
  }
}

fn main(req: Incoming, res: Outgoing, store: Kv) -> Result<Str, WebErr> {
  route(req, res, store)?;
  Ok("")
}

struct Reply { status: Int, body: Json }
struct NewNote { title: Str, body: Str, tags: List<Str> }

fn err_reply(status: Int, msg: Str) -> Reply {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Reply { status: status, body: Json::Obj(m) }
}

fn not_found() -> Reply { err_reply(404, "not found") }
fn internal() -> Reply { err_reply(500, "internal error") }

fn sql_int(v: SqlValue) -> Option<Int> {
  match v { SqlValue::Int(n) => Some(n), _ => None }
}

fn sql_text(v: SqlValue) -> Option<Str> {
  match v { SqlValue::Text(s) => Some(s), _ => None }
}

fn tags_of(text: Str) -> List<Str> {
  let items = text.parse_json().ok().and_then(|j| j.as_list()).unwrap_or([]);
  let mut out: List<Str> = [];
  for it in items {
    match it.as_str() {
      Some(s) => out.push(s),
      None => {}
    }
  }
  out
}

fn parse_note(text: Str) -> Option<NewNote> {
  let j = text.parse_json().ok()?;
  let m = j.as_map()?;
  let title = m.get("title")?.as_str()?;
  if title.len() == 0 { return None; }
  let body = m.get("body")?.as_str()?;
  let mut tags: List<Str> = [];
  match m.get("tags") {
    None => {},
    Some(tj) => {
      let items = tj.as_list()?;
      for it in items {
        let s = it.as_str()?.to_lowercase();
        if !tags.contains(s) { tags.push(s); }
      }
    }
  }
  Some(NewNote { title: title, body: body, tags: tags })
}

fn row_json(row: List<SqlValue>) -> Option<Json> {
  if row.len() != 4 { return None; }
  let id = sql_int(row[0])?;
  let title = sql_text(row[1])?;
  let body = sql_text(row[2])?;
  let tx = sql_text(row[3])?;
  let tl = tags_of(tx);
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Num(id));
  m.insert("title", Json::Str(title));
  m.insert("body", Json::Str(body));
  m.insert("tags", Json::Arr(tl.map(|t| Json::Str(t))));
  Some(Json::Obj(m))
}

fn create(db: Db, body: Bytes) -> Reply {
  let Some(n) = parse_note(body.to_str()) else { return err_reply(400, "invalid note"); };
  let mut tj: List<Json> = [];
  for t in n.tags { tj.push(Json::Str(t)); }
  let params = [SqlValue::Text(n.title), SqlValue::Text(n.body), SqlValue::Text(Json::Arr(tj).to_json())];
  match db.query("INSERT INTO notes (title, body, tags) VALUES (?, ?, ?) RETURNING id", params) {
    Ok(rows) => {
      if rows.len() == 1 && rows[0].len() == 1 {
        match sql_int(rows[0][0]) {
          Some(id) => {
            let mut m: Map<Str, Json> = Map::new();
            m.insert("id", Json::Num(id));
            Reply { status: 201, body: Json::Obj(m) }
          },
          None => internal()
        }
      } else { internal() }
    },
    Err(_) => internal()
  }
}

fn get_note(db: Db, id: Int) -> Reply {
  match db.query("SELECT id, title, body, tags FROM notes WHERE id = ?", [SqlValue::Int(id)]) {
    Ok(rows) => {
      if rows.len() == 0 { return not_found(); }
      match row_json(rows[0]) {
        Some(j) => Reply { status: 200, body: j },
        None => internal()
      }
    },
    Err(_) => internal()
  }
}

fn delete_note(db: Db, id: Int) -> Reply {
  match db.exec("DELETE FROM notes WHERE id = ?", [SqlValue::Int(id)]) {
    Ok(n) => {
      if n == 0 { return not_found(); }
      let mut m: Map<Str, Json> = Map::new();
      m.insert("deleted", Json::Num(id));
      Reply { status: 200, body: Json::Obj(m) }
    },
    Err(_) => internal()
  }
}

fn list_notes(db: Db, query: Str) -> Reply {
  let mut tag: Option<Str> = None;
  let mut word: Option<Str> = None;
  for part in query.split("&") {
    match part.find("=") {
      Some(i) => {
        let k = part.slice(0, i);
        let v = part.slice(i + 1, part.len());
        if k == "tag" { tag = Some(v.to_lowercase()); }
        if k == "q" { word = Some(v); }
      },
      None => {}
    }
  }
  match db.query("SELECT id, title, body, tags FROM notes ORDER BY id DESC", []) {
    Ok(rows) => {
      let mut out: List<Json> = [];
      for row in rows {
        if row.len() != 4 { continue; }
        let Some(id) = sql_int(row[0]) else { continue; };
        let Some(title) = sql_text(row[1]) else { continue; };
        let Some(body) = sql_text(row[2]) else { continue; };
        let Some(tx) = sql_text(row[3]) else { continue; };
        match tag {
          Some(t) => { if !tags_of(tx).contains(t) { continue; } },
          None => {}
        }
        match word {
          Some(w) => { if !(title.contains(w) || body.contains(w)) { continue; } },
          None => {}
        }
        let mut m: Map<Str, Json> = Map::new();
        m.insert("id", Json::Num(id));
        m.insert("title", Json::Str(title));
        out.push(Json::Obj(m));
      }
      Reply { status: 200, body: Json::Arr(out) }
    },
    Err(_) => internal()
  }
}

fn parse_id(s: Str) -> Option<Int> {
  if s.len() == 0 { return None; }
  for c in s.chars() {
    if c < "0" || c > "9" { return None; }
  }
  s.parse_int()
}

fn route(db: Db, method: Str, path: Str, query: Str, body: Bytes) -> Reply {
  let parts = path.split("/");
  if parts.len() < 2 || parts[0] != "" || parts[1] != "notes" { return not_found(); }
  if parts.len() == 2 {
    if method == "POST" { return create(db, body); }
    if method == "GET" { return list_notes(db, query); }
    return not_found();
  }
  if parts.len() == 3 {
    let Some(id) = parse_id(parts[2]) else { return not_found(); };
    if method == "GET" { return get_note(db, id); }
    if method == "DELETE" { return delete_note(db, id); }
  }
  not_found()
}

fn respond(res: Outgoing, r: Reply) -> Str {
  match res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes()) {
    Ok(_) => "",
    Err(_) => ""
  }
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Str {
  match db.exec("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)", []) {
    Err(_) => { return respond(res, internal()); },
    Ok(_) => {}
  }
  let target = req.target();
  let mut path = target;
  let mut query = "";
  match target.find("?") {
    Some(i) => {
      path = target.slice(0, i);
      query = target.slice(i + 1, target.len());
    },
    None => {}
  }
  let r = route(db, req.method(), path, query, req.body());
  respond(res, r)
}

struct Line { name: Str, text: Str }

fn fmt(t: Int) -> Str {
  let neg = t < 0;
  let a = if neg { -t } else { t };
  let s = (a / 10).to_str() + "." + (a % 10).to_str();
  if neg { "-" + s } else { s }
}

fn station_text(api: Http, id: Str, name: Str) -> Str {
  let body = match api.get("/stations/" + id + "/readings") {
    Ok(b) => b,
    Err(_) => return name + " unavailable",
  };
  let doc = match body.to_str().parse_json() {
    Ok(j) => j,
    Err(_) => return name + " unavailable",
  };
  let readings = doc.get("readings").and_then(|j| j.as_list()).unwrap_or([]);
  let mut n = 0;
  let mut sum = 0;
  let mut mn = 0;
  let mut mx = 0;
  for r in readings {
    let Some(t) = r.get("temp").and_then(|j| j.as_int()) else { continue; };
    if n == 0 {
      mn = t;
      mx = t;
    } else {
      if t < mn { mn = t; }
      if t > mx { mx = t; }
    }
    sum = sum + t;
    n = n + 1;
  }
  if n == 0 {
    return name + " no data";
  }
  name + " min=" + fmt(mn) + " max=" + fmt(mx) + " avg=" + fmt(sum / n) + " n=" + n.to_str()
}

fn main(api: Http) -> Result<Str, Str> {
  let body = match api.get("/stations") {
    Ok(b) => b,
    Err(_) => return Err("stations request failed"),
  };
  let doc = match body.to_str().parse_json() {
    Ok(j) => j,
    Err(e) => return Err(e),
  };
  let stations = doc.get("stations").and_then(|j| j.as_list()).unwrap_or([]);
  let mut lines: List<Line> = [];
  for s in stations {
    let Some(id) = s.get("id").and_then(|j| j.as_str()) else { continue; };
    let Some(name) = s.get("name").and_then(|j| j.as_str()) else { continue; };
    lines.push(Line { name: name, text: station_text(api, id, name) });
  }
  lines.sort_by_key(|l| l.name);
  let texts = lines.map(|l| l.text);
  Ok(texts.join("\n"))
}

struct Entry { name: Str, line: Str }

fn fmt(t: Int) -> Str {
  let sign = if t < 0 { "-" } else { "" };
  let a = if t < 0 { -t } else { t };
  sign + (a / 10).to_str() + "." + (a % 10).to_str()
}

fn readings(api: Http, id: Str) -> Option<List<Int>> {
  let Ok(b) = api.get("/stations/" + id + "/readings") else { return None; };
  let Ok(doc) = b.to_str().parse_json() else { return None; };
  let items = doc.get("readings").and_then(|j| j.as_list()).unwrap_or([]);
  let mut out: List<Int> = [];
  for it in items {
    if let Some(t) = it.get("temp").and_then(|j| j.as_int()) {
      out.push(t);
    }
  }
  Some(out)
}

fn summarize(name: Str, temps: Option<List<Int>>) -> Str {
  let Some(ts) = temps else { return name + " unavailable"; };
  let n = ts.len();
  if n == 0 { return name + " no data"; }
  let mut lo = ts[0];
  let mut hi = ts[0];
  let mut sum = 0;
  for t in ts {
    if t < lo { lo = t; }
    if t > hi { hi = t; }
    sum += t;
  }
  name + " min=" + fmt(lo) + " max=" + fmt(hi) + " avg=" + fmt(sum / n) + " n=" + n.to_str()
}

fn main(api: Http) -> Result<Str, Str> {
  let b = api.get("/stations").map_err(|e| "stations request failed")?;
  let doc = b.to_str().parse_json()?;
  let stations = doc.get("stations").and_then(|j| j.as_list()).unwrap_or([]);
  let mut entries: List<Entry> = [];
  for st in stations {
    let Some(id) = st.get("id").and_then(|j| j.as_str()) else { continue; };
    let Some(name) = st.get("name").and_then(|j| j.as_str()) else { continue; };
    entries.push(Entry { name: name, line: summarize(name, readings(api, id)) });
  }
  entries.sort_by_key(|e| e.name);
  let lines = entries.map(|e| e.line);
  Ok(lines.join("\n"))
}

struct Line { name: Str, text: Str }

fn fmt(t: Int) -> Str {
  let a = if t < 0 { -t } else { t };
  let sign = if t < 0 { "-" } else { "" };
  sign + (a / 10).to_str() + "." + (a % 10).to_str()
}

fn station_text(api: Http, id: Str, name: Str) -> Str {
  let bytes = match api.get("/stations/" + id + "/readings") {
    Ok(b) => b,
    Err(_) => return name + " unavailable",
  };
  let doc = match bytes.to_str().parse_json() {
    Ok(j) => j,
    Err(_) => return name + " unavailable",
  };
  let readings = doc.get("readings").and_then(|j| j.as_list()).unwrap_or([]);
  let mut mn = 0;
  let mut mx = 0;
  let mut sum = 0;
  let mut n = 0;
  for r in readings {
    if let Some(t) = r.get("temp").and_then(|j| j.as_int()) {
      if n == 0 {
        mn = t;
        mx = t;
      } else {
        mn = mn.min(t);
        mx = mx.max(t);
      }
      sum = sum + t;
      n = n + 1;
    }
  }
  if n == 0 {
    return name + " no data";
  }
  name + " min=" + fmt(mn) + " max=" + fmt(mx) + " avg=" + fmt(sum / n) + " n=" + n.to_str()
}

