fn fmt(t: Int) -> Str {
  let a = if t < 0 { 0 - t } else { t };
  let sign = if t < 0 { "-" } else { "" };
  sign + (a / 10).to_str() + "." + (a % 10).to_str()
}

fn summarize(api: Http, id: Str) -> Str {
