  let list = doc.get("readings").and_then(|j| j.as_list()).unwrap_or([]);
  let mut n = 0;
  let mut sum = 0;
  let mut mn = 0;
  let mut mx = 0;
  for r in list {
    if let Some(t) = r.get("temp").and_then(|j| j.as_int()) {
      if n == 0 {
        mn = t;
        mx = t;
      } else {
        mn = mn.min(t);
        mx = mx.max(t);
      }
      n += 1;
      sum += t;
    }
  }
  if n == 0 {
    return "no data";
  }
  "min=" + fmt(mn) + " max=" + fmt(mx) + " avg=" + fmt(sum / n) + " n=" + n.to_str()
}

