struct Station { id: Str, name: Str }

fn fmt(t: Int) -> Str {
  let neg = t < 0;
  let a = if neg { -t } else { t };
  let sign = if neg { "-" } else { "" };
  sign + (a / 10).to_str() + "." + (a % 10).to_str()
}

fn summarize(api: Http, s: Station) -> Str {
  let bytes = match api.get("/stations/" + s.id + "/readings") {
    Err(_) => return s.name + " unavailable",
    Ok(b) => b,
  };
  let Ok(doc) = bytes.to_str().parse_json() else { return s.name + " unavailable"; };
  let readings = doc.get("readings").and_then(|j| j.as_list()).unwrap_or([]);
  let mut count = 0;
  let mut sum = 0;
  let mut lo = 0;
  let mut hi = 0;
  for r in readings {
    if let Some(t) = r.get("temp").and_then(|j| j.as_int()) {
      if count == 0 {
        lo = t;
        hi = t;
      } else {
        lo = lo.min(t);
        hi = hi.max(t);
      }
      count += 1;
      sum += t;
    }
  }
  if count == 0 {
    return s.name + " no data";
  }
  let avg = sum / count;
  s.name + " min=" + fmt(lo) + " max=" + fmt(hi) + " avg=" + fmt(avg) + " n=" + count.to_str()
}

