fn main(api: Http) -> Result<Str, Str> {
  let mut count = 0;
  let mut refunded = 0;
  let mut paid: Map<Str, Int> = Map::new();
  let mut best_id = -1;
  let mut best_cents = -1;
  let mut page = 1;
  loop {
    let doc = fetch(api, page)?;
    let orders = doc.get("orders").and_then(|j| j.as_list()).unwrap_or([]);
    for o in orders {
      count += 1;
      let status = o.get("status").and_then(|j| j.as_str()).unwrap_or("");
      let cents = o.get("cents").and_then(|j| j.as_int()).unwrap_or(0);
      let id = o.get("id").and_then(|j| j.as_int()).unwrap_or(0);
      let cur = o.get("currency").and_then(|j| j.as_str()).unwrap_or("");
      if status == "paid" {
        let prev = paid.get(cur).unwrap_or(0);
        paid.insert(cur, prev + cents);
        if best_id < 0 || cents > best_cents || (cents == best_cents && id < best_id) {
          best_id = id;
          best_cents = cents;
        }
      } else if status == "refunded" {
        refunded += 1;
      }
    }
    let next = doc.get("next").and_then(|j| j.as_int());
    match next {
      Some(n) => page = n,
      None => break,
    }
  }
  let mut pj: Map<Str, Json> = Map::new();
  for k in paid.keys() {
    pj.insert(k, Json::Num(paid.get(k).unwrap_or(0)));
  }
  let mut obj: Map<Str, Json> = Map::new();
  obj.insert("orders", Json::Num(count));
  obj.insert("paid_cents", Json::Obj(pj));
  obj.insert("refunded", Json::Num(refunded));
  obj.insert("largest", if best_id < 0 { Json::Null } else { Json::Num(best_id) });
  let r = post(api, Json::Obj(obj).to_json().to_bytes())?;
  if r.status != 201 {
    return Err("status " + r.status.to_str());
  }
  let resp = r.body.to_str().parse_json()?;
  let id = resp.get("id").and_then(|j| j.as_str()).unwrap_or("?");
  Ok(id)
}

