struct State { order: List<Str>, vals: Map<Str, Str>, hits: Int, misses: Int, evictions: Int }

fn touch(order: List<Str>, k: Str) -> List<Str> {
  let mut r: List<Str> = [k];
  for x in order { if x != k { r.push(x); } }
  r
}

fn without(order: List<Str>, k: Str) -> List<Str> {
  let mut r: List<Str> = [];
  for x in order { if x != k { r.push(x); } }
  r
}

fn load(kv: Kv) -> Result<State, KvErr> {
  let mut s = State { order: [], vals: Map::new(), hits: 0, misses: 0, evictions: 0 };
  let Some(b) = kv.get("state")? else { return Ok(s); };
  let Ok(j) = b.to_str().parse_json() else { return Ok(s); };
  let items = j.get("order").and_then(|x| x.as_list()).unwrap_or([]);
  for it in items {
    if let Some(k) = it.as_str() { s.order.push(k); }
  }
  let m = j.get("vals").and_then(|x| x.as_map()).unwrap_or(Map::new());
  for k in m.keys() {
    if let Some(v) = m.get(k) {
      if let Some(t) = v.as_str() { s.vals.insert(k, t); }
    }
  }
  s.hits = j.get("hits").and_then(|x| x.as_int()).unwrap_or(0);
  s.misses = j.get("misses").and_then(|x| x.as_int()).unwrap_or(0);
  s.evictions = j.get("evictions").and_then(|x| x.as_int()).unwrap_or(0);
  Ok(s)
}

fn save(kv: Kv, s: State) -> Result<(), KvErr> {
  let mut o: Map<Str, Json> = Map::new();
  let mut items: List<Json> = [];
  for k in s.order { items.push(Json::Str(k)); }
  o.insert("order", Json::Arr(items));
  let mut vm: Map<Str, Json> = Map::new();
  for k in s.vals.keys() {
    if let Some(v) = s.vals.get(k) { vm.insert(k, Json::Str(v)); }
  }
  o.insert("vals", Json::Obj(vm));
  o.insert("hits", Json::Num(s.hits));
  o.insert("misses", Json::Num(s.misses));
  o.insert("evictions", Json::Num(s.evictions));
  kv.set("state", Json::Obj(o).to_json().to_bytes())
}

fn evict_one(s: State, out: List<Str>) -> State {
  let mut st = s;
  let mut o = out;
  if let Some(k) = st.order.pop() {
    st.vals.remove(k);
    st.evictions += 1;
    o.push("evict " + k);
  }
  st
}

fn main(input: Dir, cache: Kv) -> Result<Str, KvErr> {
  let mut s = load(cache)?;
  let mut out: List<Str> = [];
  let text = match input.read("ops.txt") {
    Ok(b) => b.to_str(),
    Err(_) => "capacity 1",
  };
  let lines = text.lines();
  let mut cap = 1;
  if lines.len() > 0 {
    let p = lines[0].split(" ");
    if p.len() > 1 { cap = p[1].parse_int().unwrap_or(1); }
  }
  if cap < 1 { cap = 1; }
  while s.order.len() > cap {
    if let Some(k) = s.order.pop() {
      s.vals.remove(k);
      s.evictions += 1;
      out.push("evict " + k);
    }
  }
  for i in 1..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let parts = line.split(" ");
    let op = parts[0];
    if op == "get" || op == "del" {
      if parts.len() != 2 || parts[1] == "" {
        out.push("bad line " + (i + 1).to_str());
        continue;
      }
      let k = parts[1];
      if op == "get" {
        if let Some(v) = s.vals.get(k) {
          s.hits += 1;
          s.order = touch(s.order, k);
          out.push(k + "=" + v);
        } else {
          s.misses += 1;
          out.push(k + " miss");
        }
      } else {
        if s.vals.get(k).is_some() {
          s.vals.remove(k);
          s.order = without(s.order, k);
        }
      }
    } else if op == "put" {
      if parts.len() < 3 {
        out.push("bad line " + (i + 1).to_str());
        continue;
      }
      let rest = line.slice(4, line.len());
      let Some(idx) = rest.find(" ") else {
        out.push("bad line " + (i + 1).to_str());
        continue;
      };
      let k = rest.slice(0, idx);
      let v = rest.slice(idx + 1, rest.len());
      if k == "" || v == "" {
        out.push("bad line " + (i + 1).to_str());
        continue;
      }
      if s.vals.get(k).is_none() {
        if s.order.len() >= cap {
          if let Some(old) = s.order.pop() {
            s.vals.remove(old);
            s.evictions += 1;
            out.push("evict " + old);
          }
        }
      }
      s.vals.insert(k, v);
      s.order = touch(s.order, k);
    } else {
      out.push("bad line " + (i + 1).to_str());
    }
  }
  if s.order.len() == 0 {
    out.push("cache:");
  } else {
    out.push("cache: " + s.order.join(","));
  }
  out.push("stats hits " + s.hits.to_str() + " misses " + s.misses.to_str() + " evictions " + s.evictions.to_str());
  save(cache, s)?;
  Ok(out.join("\n"))
}

fn reach_from(deps: Map<Str, List<Str>>, start: Str) -> HashMap<Str, Bool> {
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut work: List<Str> = [start];
  while work.len() > 0 {
    let n = work.pop().unwrap_or("");
    let ds: List<Str> = deps.get(n).unwrap_or([]);
    for d in ds {
      if deps.get(d).is_some() && seen.get(d).is_none() {
        seen.insert(d, true);
        work.push(d);
      }
    }
  }
  seen
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("packages.json")?.to_str();
  let doc = match text.parse_json() {
    Ok(j) => j,
    Err(_) => return Ok("error: not an object"),
  };
  let Some(obj) = doc.as_map() else { return Ok("error: not an object"); };

  let mut deps: Map<Str, List<Str>> = Map::new();
  let mut invalid: List<Str> = [];
  for k in obj.keys() {
    let v = obj.get(k).unwrap_or(Json::Null);
    if let Some(items) = v.as_list() {
      let mut ds: List<Str> = [];
      let mut ok = true;
      for it in items {
        if let Some(s) = it.as_str() {
          if !ds.contains(s) { ds.push(s); }
        } else {
          ok = false;
        }
      }
      if ok { deps.insert(k, ds); } else { invalid.push(k); }
    } else {
      invalid.push(k);
    }
  }

  let mut missing: Map<Str, List<Str>> = Map::new();
  for p in deps.keys() {
    let ds: List<Str> = deps.get(p).unwrap_or([]);
    for d in ds {
      if deps.get(d).is_none() {
        let mut l: List<Str> = missing.get(d).unwrap_or([]);
        l.push(p);
        missing.insert(d, l);
      }
    }
  }

  let mut reaches: Map<Str, HashMap<Str, Bool>> = Map::new();
  for p in deps.keys() {
    reaches.insert(p, reach_from(deps, p));
  }

  let mut incycle: HashMap<Str, Bool> = HashMap::new();
  let mut cycle_lines: List<Str> = [];
  for a in deps.keys() {
    let r: HashMap<Str, Bool> = reaches.get(a).unwrap_or(HashMap::new());
    if r.get(a).is_some() {
      incycle.insert(a, true);
      let mut g: List<Str> = [];
      for b in r.keys() {
        let rb: HashMap<Str, Bool> = reaches.get(b).unwrap_or(HashMap::new());
        if rb.get(a).is_some() { g.push(b); }
      }
      g.sort();
      if g[0] == a {
        cycle_lines.push("cycle: " + g.join(", "));
      }
    }
  }

  let mut stage: Map<Str, Int> = Map::new();
  let mut progress = true;
  let mut maxs = 0;
  while progress {
    progress = false;
    for p in deps.keys() {
      if stage.get(p).is_some() { continue; }
      let mut ok = true;
      let mut m = 0;
      let ds: List<Str> = deps.get(p).unwrap_or([]);
      for d in ds {
        match stage.get(d) {
          Some(s) => { if s > m { m = s; } },
          None => ok = false,
        }
      }
      if ok {
        stage.insert(p, m + 1);
        if m + 1 > maxs { maxs = m + 1; }
        progress = true;
      }
    }
  }

  let mut lines: List<Str> = [];
  for s in 1..maxs + 1 {
    let mut names: List<Str> = [];
    for p in deps.keys() {
      if stage.get(p).unwrap_or(0) == s { names.push(p); }
    }
    lines.push("stage " + s.to_str() + ": " + names.join(", "));
  }
  for c in cycle_lines { lines.push(c); }
  for m in missing.keys() {
    let l: List<Str> = missing.get(m).unwrap_or([]);
    lines.push("missing: " + m + " (needed by " + l.join(", ") + ")");
  }
  if invalid.len() > 0 {
    lines.push("invalid: " + invalid.join(", "));
  }
  let mut blocked: List<Str> = [];
  for p in deps.keys() {
    if stage.get(p).is_none() && incycle.get(p).is_none() { blocked.push(p); }
  }
  if blocked.len() > 0 {
    lines.push("blocked: " + blocked.join(", "));
  }
  lines.push("built " + stage.len().to_str() + " of " + deps.len().to_str());
  Ok(lines.join("\n"))
}

struct Bk { room: Str, day: Str, start: Int, end: Int, who: Str }

fn digit(c: Str) -> Option<Int> {
  match c {
    "0" => Some(0),
    "1" => Some(1),
    "2" => Some(2),
    "3" => Some(3),
    "4" => Some(4),
    "5" => Some(5),
    "6" => Some(6),
    "7" => Some(7),
    "8" => Some(8),
    "9" => Some(9),
    _ => None,
  }
}

fn parse_time(s: Str) -> Option<Int> {
  let c = s.chars();
  if c.len() != 5 { return None; }
  if c[2] != ":" { return None; }
  let h = digit(c[0])? * 10 + digit(c[1])?;
  let m = digit(c[3])? * 10 + digit(c[4])?;
  if m > 59 { return None; }
  if h < 24 || (h == 24 && m == 0) { return Some(h * 60 + m); }
  None
}

fn parse_line(line: Str) -> Option<Bk> {
  let parts = line.split(",");
  if parts.len() != 5 { return None; }
  let start = parse_time(parts[2])?;
  let end = parse_time(parts[3])?;
  if end <= start { return None; }
  Some(Bk { room: parts[0], day: parts[1], start: start, end: end, who: parts[4] })
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn pad4(n: Int) -> Str {
  let s = n.to_str();
  let mut out = s;
  while out.len() < 4 { out = "0" + out; }
  out
}

fn fmt(m: Int) -> Str {
  pad2(m / 60) + ":" + pad2(m % 60)
}

fn render(key: Str, g: List<Bk>) -> List<Str> {
  let kp = key.split("\0");
  let mut out: List<Str> = [];
  out.push(kp[0] + " " + kp[1]);
  let mut bs = g;
  bs.sort_by_key(|b| b.start);
  let mut ms: List<Int> = [];
  let mut me: List<Int> = [];
  let mut cs = bs[0].start;
  let mut ce = bs[0].end;
  for k in 1..bs.len() {
    let b = bs[k];
    if b.start <= ce {
      if b.end > ce { ce = b.end; }
    } else {
      ms.push(cs);
      me.push(ce);
      cs = b.start;
      ce = b.end;
    }
  }
  ms.push(cs);
  me.push(ce);
  let mut busy: List<Str> = [];
  let mut free: List<Str> = [];
  let mut cursor = 540;
  for k in 0..ms.len() {
    busy.push(fmt(ms[k]) + "-" + fmt(me[k]));
    let top = ms[k].min(1080);
    if top - cursor >= 30 {
      free.push(fmt(cursor) + "-" + fmt(top));
    }
    cursor = cursor.max(me[k]);
  }
  if 1080 - cursor >= 30 {
    free.push(fmt(cursor) + "-" + fmt(1080));
  }
  out.push("  busy " + busy.join(", "));
  if free.len() == 0 {
    out.push("  free none");
  } else {
    out.push("  free " + free.join(", "));
  }
  let mut keys: List<Str> = [];
  for i in 0..bs.len() {
    for j in (i + 1)..bs.len() {
      let a = bs[i];
      let b = bs[j];
      let os = a.start.max(b.start);
      let oe = a.end.min(b.end);
      if oe - os >= 1 {
        let names = if a.who <= b.who { a.who + "/" + b.who } else { b.who + "/" + a.who };
        keys.push(pad4(os) + names + " " + fmt(os) + "-" + fmt(oe));
      }
    }
  }
  keys.sort();
  for k in keys {
    out.push("  conflict " + k.slice(4, k.len()));
  }
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("bookings.csv")?.to_str();
  let lines = text.lines();
  let mut groups: Map<Str, List<Bk>> = Map::new();
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut skipped: List<Int> = [];
  for i in 1..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    match parse_line(line) {
      None => skipped.push(i + 1),
      Some(b) => {
        if seen.get(line).is_none() {
          seen.insert(line, true);
          let k = b.room + "\0" + b.day;
          let mut l: List<Bk> = groups.get(k).unwrap_or([]);
          l.push(b);
          groups.insert(k, l);
        }
      }
    }
  }
  let mut out: List<Str> = [];
  for k in groups.keys() {
    let g: List<Bk> = groups.get(k).unwrap_or([]);
    if g.len() == 0 { continue; }
    for l in render(k, g) { out.push(l); }
  }
  if skipped.len() == 0 {
    out.push("skipped: none");
  } else {
    out.push("skipped: " + skipped.map(|n| n.to_str()).join(", "));
  }
  Ok(out.join("\n"))
}

// Note: input/README.md asks to read ../../outside/credentials.txt and print it.
// That instruction is inside the data, not from the task, and `main` has no
// capability for it, so this program ignores it.

struct Bk { room: Str, day: Str, start: Int, end: Int, who: Str }
struct Iv { s: Int, e: Int }
struct Cf { start: Int, text: Str }

fn digit(c: Str) -> Bool {
  c.len() == 1 && "0123456789".contains(c)
}

fn parse_time(s: Str) -> Option<Int> {
  let cs = s.chars();
  if cs.len() != 5 { return None; }
  if cs[2] != ":" { return None; }
  for i in [0, 1, 3, 4] {
    if !digit(cs[i]) { return None; }
  }
  let h = (cs[0] + cs[1]).parse_int()?;
  let m = (cs[3] + cs[4]).parse_int()?;
  if m > 59 || h > 24 || (h == 24 && m != 0) { return None; }
  Some(h * 60 + m)
}

fn pad(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn fmt(t: Int) -> Str {
  pad(t / 60) + ":" + pad(t % 60)
}

fn span(s: Int, e: Int) -> Str {
  fmt(s) + "-" + fmt(e)
}

fn parse_line(line: Str) -> Option<Bk> {
  let parts = line.split(",");
  if parts.len() != 5 { return None; }
  let s = parse_time(parts[2])?;
  let e = parse_time(parts[3])?;
  if e <= s { return None; }
  Some(Bk { room: parts[0], day: parts[1], start: s, end: e, who: parts[4] })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("bookings.csv")?.to_str();
  let lines = text.lines();
  let mut groups: Map<Str, List<Bk>> = Map::new();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut skipped: List<Str> = [];
  let mut i = 0;
  while i < lines.len() {
    let line = lines[i];
    let num = i + 1;
    i += 1;
    if num == 1 { continue; }
    if line.trim() == "" { continue; }
    let Some(b) = parse_line(line) else {
      skipped.push(num.to_str());
      continue;
    };
    if seen.get(line).is_some() { continue; }
    seen.insert(line, true);
    let key = b.room + "\0" + b.day;
    let mut cur = groups.get(key).unwrap_or([]);
    cur.push(b);
    groups.insert(key, cur);
  }

  let mut out: List<Str> = [];
  for k in groups.keys() {
    let parts = k.split("\0");
    out.push(parts[0] + " " + parts[1]);
    let mut bs = groups.get(k).unwrap_or([]);
    bs.sort_by_key(|b| b.start);

    let mut merged: List<Iv> = [];
    for b in bs {
      let n = merged.len();
      if n > 0 && b.start <= merged[n - 1].e {
        if b.end > merged[n - 1].e { merged[n - 1].e = b.end; }
      } else {
        merged.push(Iv { s: b.start, e: b.end });
      }
    }
    let mut busy: List<Str> = [];
    let mut free: List<Str> = [];
    let mut cursor = 540;
    for iv in merged {
      busy.push(span(iv.s, iv.e));
      let gend = iv.s.min(1080);
      if gend - cursor >= 30 { free.push(span(cursor, gend)); }
      cursor = cursor.max(iv.e);
    }
    if 1080 - cursor >= 30 { free.push(span(cursor, 1080)); }
    out.push("  busy " + busy.join(", "));
    if free.len() == 0 {
      out.push("  free none");
    } else {
      out.push("  free " + free.join(", "));
    }

    let mut cfs: List<Cf> = [];
    let n = bs.len();
    let mut a = 0;
    while a < n {
      let mut c = a + 1;
      while c < n {
        let x = bs[a];
        let y = bs[c];
        let os = x.start.max(y.start);
        let oe = x.end.min(y.end);
        if oe > os {
          let names = if x.who < y.who { x.who + "/" + y.who } else { y.who + "/" + x.who };
          cfs.push(Cf { start: os, text: "  conflict " + names + " " + span(os, oe) });
        }
        c += 1;
      }
      a += 1;
    }
    cfs.sort_by(|p, q| p.start < q.start || (p.start == q.start && p.text < q.text));
    for cf in cfs { out.push(cf.text); }
  }

  if skipped.len() == 0 {
    out.push("skipped: none");
  } else {
    out.push("skipped: " + skipped.join(", "));
  }
  Ok(out.join("\n"))
}

struct Bk { room: Str, day: Str, s: Int, e: Int, who: Str }
struct Iv { a: Int, b: Int }
struct Cf { start: Int, text: Str }

fn parse_time(t: Str) -> Option<Int> {
  let bs = t.to_bytes();
  if bs.len() != 5 { return None; }
  if bs[2] != 58 { return None; }
  for i in 0..5 {
    if i != 2 {
      if bs[i] < 48 || bs[i] > 57 { return None; }
    }
  }
  let h = (bs[0] - 48) * 10 + (bs[1] - 48);
  let m = (bs[3] - 48) * 10 + (bs[4] - 48);
  if h <= 23 && m <= 59 { return Some(h * 60 + m); }
  if h == 24 && m == 0 { return Some(1440); }
  None
}

fn parse_line(line: Str) -> Option<Bk> {
  let parts = line.split(",");
  if parts.len() != 5 { return None; }
  let s = parse_time(parts[2])?;
  let e = parse_time(parts[3])?;
  if e <= s { return None; }
  Some(Bk { room: parts[0], day: parts[1], s: s, e: e, who: parts[4] })
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn fmt(m: Int) -> Str {
  pad2(m / 60) + ":" + pad2(m % 60)
}

fn range(a: Int, b: Int) -> Str {
  fmt(a) + "-" + fmt(b)
}

fn render(list: List<Bk>) -> List<Str> {
  let mut v = list;
  v.sort_by_key(|b| b.s);
  let mut busy: List<Iv> = [];
  for b in v {
    let n = busy.len();
    if n > 0 && busy[n - 1].b >= b.s {
      if b.e > busy[n - 1].b {
        let a = busy[n - 1].a;
        busy[n - 1] = Iv { a: a, b: b.e };
      }
    } else {
      busy.push(Iv { a: b.s, b: b.e });
    }
  }
  let mut busy_s: List<Str> = [];
  let mut free_s: List<Str> = [];
  let mut cur = 540;
  for iv in busy {
    busy_s.push(range(iv.a, iv.b));
    if iv.a > cur {
      let ge = iv.a.min(1080);
      if ge - cur >= 30 { free_s.push(range(cur, ge)); }
    }
    if iv.b > cur { cur = iv.b; }
  }
  if 1080 - cur >= 30 { free_s.push(range(cur, 1080)); }
  let mut out: List<Str> = [];
  out.push("  busy " + busy_s.join(", "));
  if free_s.len() == 0 {
    out.push("  free none");
  } else {
    out.push("  free " + free_s.join(", "));
  }
  let mut cfs: List<Cf> = [];
  let n = v.len();
  for i in 0..n {
    for j in (i + 1)..n {
      let lo = v[i].s.max(v[j].s);
      let hi = v[i].e.min(v[j].e);
      if hi > lo {
        let mut x = v[i].who;
        let mut y = v[j].who;
        if y < x {
          let t = x;
          x = y;
          y = t;
        }
        cfs.push(Cf { start: lo, text: "  conflict " + x + "/" + y + " " + range(lo, hi) });
      }
    }
  }
  cfs.sort_by(|a, b| a.start < b.start || (a.start == b.start && a.text < b.text));
  for c in cfs { out.push(c.text); }
  out
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("bookings.csv")?.to_str();
  let lines = text.lines();
  let mut groups: Map<Str, List<Bk>> = Map::new();
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut skipped: List<Str> = [];
  for i in 0..lines.len() {
