struct E { path: Str, msg: Str }

fn type_ok(t: Str, v: Json) -> Bool {
  match v {
    Json::Obj(_) => t == "object",
    Json::Arr(_) => t == "array",
    Json::Str(_) => t == "string",
    Json::Num(_) => t == "integer" || t == "number",
    Json::Float(_) => t == "number",
    Json::Bool(_) => t == "boolean",
    Json::Null => t == "null",
  }
}

fn check(schema: Json, v: Json, path: Str) -> List<E> {
  let mut errs: List<E> = [];
  let t = schema.get("type").and_then(|j| j.as_str()).unwrap_or("");
  if !type_ok(t, v) {
    errs.push(E { path: path, msg: "expected " + t });
    return errs;
  }
  match v {
    Json::Obj(m) => {
      let props: Map<Str, Json> = match schema.get("properties").and_then(|j| j.as_map()) {
        Some(p) => p,
        None => Map::new(),
      };
      let req = schema.get("required").and_then(|j| j.as_list()).unwrap_or([]);
      for r in req {
        if let Some(name) = r.as_str() {
          if m.get(name).is_none() {
            errs.push(E { path: path + "." + name, msg: "missing required field" });
          }
        }
      }
      let additional = schema.get("additional").and_then(|j| j.as_bool()).unwrap_or(true);
      for k in m.keys() {
        let child = path + "." + k;
        match props.get(k) {
          Some(s) => {
            for e in check(s, m.get(k).unwrap_or(Json::Null), child) { errs.push(e); }
          }
          None => {
            if !additional {
              errs.push(E { path: child, msg: "unexpected field" });
            }
          }
        }
      }
    }
    Json::Arr(xs) => {
      if let Some(n) = schema.get("min_items").and_then(|j| j.as_int()) {
        if xs.len() < n {
          errs.push(E { path: path, msg: "fewer than " + n.to_str() + " items" });
        }
      }
      if let Some(items) = schema.get("items") {
        for i in 0..xs.len() {
          for e in check(items, xs[i], path + "[" + i.to_str() + "]") { errs.push(e); }
        }
      }
    }
    Json::Str(s) => {
      let len = s.chars().len();
      let mut bad: Option<Str> = None;
      if let Some(n) = schema.get("min_length").and_then(|j| j.as_int()) {
        if len < n { bad = Some("shorter than " + n.to_str()); }
      }
      if bad.is_none() {
        if let Some(n) = schema.get("max_length").and_then(|j| j.as_int()) {
          if len > n { bad = Some("longer than " + n.to_str()); }
        }
      }
      if bad.is_none() {
        if let Some(a) = schema.get("enum").and_then(|j| j.as_list()) {
          if !a.any(|j| j.as_str() == Some(s)) { bad = Some("not in enum"); }
        }
      }
      if let Some(m) = bad {
        errs.push(E { path: path, msg: m });
      }
    }
    Json::Num(n) => {
      let mut bad: Option<Str> = None;
      if let Some(lo) = schema.get("minimum").and_then(|j| j.as_int()) {
        if n < lo { bad = Some("less than " + lo.to_str()); }
      }
      if bad.is_none() {
        if let Some(hi) = schema.get("maximum").and_then(|j| j.as_int()) {
          if n > hi { bad = Some("greater than " + hi.to_str()); }
        }
      }
      if let Some(m) = bad {
        errs.push(E { path: path, msg: m });
      }
    }
    Json::Float(f) => {
      let mut bad: Option<Str> = None;
      if let Some(lo) = schema.get("minimum").and_then(|j| j.as_int()) {
        if f < lo.to_float() { bad = Some("less than " + lo.to_str()); }
      }
      if bad.is_none() {
        if let Some(hi) = schema.get("maximum").and_then(|j| j.as_int()) {
          if f > hi.to_float() { bad = Some("greater than " + hi.to_str()); }
        }
      }
      if let Some(m) = bad {
        errs.push(E { path: path, msg: m });
      }
    }
    _ => {}
  }
  errs
}

fn main(input: Dir) -> Result<Str, Str> {
  let schema_text = input.read("schema.json").map_err(|e| "cannot read schema")?.to_str();
  let schema = schema_text.parse_json()?;
  let text = input.read("records.jsonl").map_err(|e| "cannot read records")?.to_str();
  let lines = text.lines();
  let mut out = "";
  let mut valid = 0;
  let mut total = 0;
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    total += 1;
    let prefix = "line " + (i + 1).to_str() + ": ";
    match line.parse_json() {
      Err(_) => { out = out + prefix + "invalid JSON\n"; }
      Ok(v) => {
        let mut errs = check(schema, v, "$");
        if errs.len() == 0 {
          valid += 1;
          out = out + prefix + "ok\n";
        } else {
          errs.sort_by(|a, b| a.path < b.path || (a.path == b.path && a.msg < b.msg));
          for e in errs {
            out = out + prefix + e.path + ": " + e.msg + "\n";
          }
        }
      }
    }
  }
  out = out + "valid " + valid.to_str() + " of " + total.to_str();
  Ok(out)
}

struct Err { path: Str, msg: Str }

fn er(path: Str, msg: Str) -> Err { Err { path: path, msg: msg } }

fn bad(path: Str, ty: Str) -> List<Err> { [er(path, "expected " + ty)] }

fn check_obj(schema: Json, m: Map<Str, Json>, path: Str) -> List<Err> {
  let mut out: List<Err> = [];
  let props: Map<Str, Json> = schema.get("properties").and_then(|j| j.as_map()).unwrap_or(Map::new());
  let req: List<Json> = schema.get("required").and_then(|j| j.as_list()).unwrap_or([]);
  let additional = schema.get("additional").and_then(|j| j.as_bool()).unwrap_or(true);
  for r in req {
    if let Some(name) = r.as_str() {
      if m.get(name).is_none() {
        out.push(er(path + "." + name, "missing required field"));
      }
    }
  }
  if !additional {
    for k in m.keys() {
      if props.get(k).is_none() {
        out.push(er(path + "." + k, "unexpected field"));
      }
    }
  }
  for k in props.keys() {
    if let Some(val) = m.get(k) {
      if let Some(ps) = props.get(k) {
        for e in check(ps, val, path + "." + k) { out.push(e); }
      }
    }
  }
  out
}

fn check_arr(schema: Json, xs: List<Json>, path: Str) -> List<Err> {
  let mut out: List<Err> = [];
  if let Some(n) = schema.get("min_items").and_then(|j| j.as_int()) {
    if xs.len() < n {
      out.push(er(path, "fewer than " + n.to_str() + " items"));
    }
  }
  if let Some(is) = schema.get("items") {
    for i in 0..xs.len() {
      for e in check(is, xs[i], path + "[" + i.to_str() + "]") { out.push(e); }
    }
  }
  out
}

fn check_str(schema: Json, s: Str, path: Str) -> List<Err> {
  let n = s.chars().len();
  if let Some(lo) = schema.get("min_length").and_then(|j| j.as_int()) {
    if n < lo { return [er(path, "shorter than " + lo.to_str())]; }
  }
  if let Some(hi) = schema.get("max_length").and_then(|j| j.as_int()) {
    if n > hi { return [er(path, "longer than " + hi.to_str())]; }
  }
  if let Some(en) = schema.get("enum").and_then(|j| j.as_list()) {
    let mut found = false;
    for e in en {
      if let Some(x) = e.as_str() {
        if x == s { found = true; }
      }
    }
    if !found { return [er(path, "not in enum")]; }
  }
  []
}

fn check_int_range(schema: Json, n: Int, path: Str) -> List<Err> {
  if let Some(lo) = schema.get("minimum").and_then(|j| j.as_int()) {
    if n < lo { return [er(path, "less than " + lo.to_str())]; }
  }
  if let Some(hi) = schema.get("maximum").and_then(|j| j.as_int()) {
    if n > hi { return [er(path, "greater than " + hi.to_str())]; }
  }
  []
}

fn check_float_range(schema: Json, f: Float, path: Str) -> List<Err> {
  if let Some(lo) = schema.get("minimum").and_then(|j| j.as_int()) {
    if f < lo.to_float() { return [er(path, "less than " + lo.to_str())]; }
  }
  if let Some(hi) = schema.get("maximum").and_then(|j| j.as_int()) {
    if f > hi.to_float() { return [er(path, "greater than " + hi.to_str())]; }
  }
  []
}

fn check(schema: Json, v: Json, path: Str) -> List<Err> {
  let ty = schema.get("type").and_then(|j| j.as_str()).unwrap_or("");
  match ty {
    "object" => match v {
      Json::Obj(m) => check_obj(schema, m, path),
      _ => bad(path, ty),
    },
    "array" => match v {
      Json::Arr(xs) => check_arr(schema, xs, path),
      _ => bad(path, ty),
    },
    "string" => match v {
      Json::Str(s) => check_str(schema, s, path),
      _ => bad(path, ty),
    },
    "integer" => match v {
      Json::Num(n) => check_int_range(schema, n, path),
      _ => bad(path, ty),
    },
    "number" => match v {
      Json::Num(n) => check_int_range(schema, n, path),
      Json::Float(f) => check_float_range(schema, f, path),
      _ => bad(path, ty),
    },
    "boolean" => match v {
      Json::Bool(_) => [],
      _ => bad(path, ty),
    },
    "null" => match v {
      Json::Null => [],
      _ => bad(path, ty),
    },
    _ => [],
  }
}

