struct E { path: Str, msg: Str }

fn bound_int(schema: Json, n: Int) -> Option<Str> {
  if let Some(lo) = schema.get("minimum").and_then(|j| j.as_int()) {
    if n < lo { return Some("less than " + lo.to_str()); }
  }
  if let Some(hi) = schema.get("maximum").and_then(|j| j.as_int()) {
    if n > hi { return Some("greater than " + hi.to_str()); }
  }
  None
}

fn bound_float(schema: Json, x: Float) -> Option<Str> {
  if let Some(lo) = schema.get("minimum").and_then(|j| j.as_int()) {
    if x < lo.to_float() { return Some("less than " + lo.to_str()); }
  }
  if let Some(hi) = schema.get("maximum").and_then(|j| j.as_int()) {
    if x > hi.to_float() { return Some("greater than " + hi.to_str()); }
  }
  None
}

fn check(schema: Json, v: Json, path: Str) -> List<E> {
  let mut errs: List<E> = [];
  let t = schema.get("type").and_then(|j| j.as_str()).unwrap_or("");
  let ok = match v {
    Json::Obj(_) => t == "object",
    Json::Arr(_) => t == "array",
    Json::Str(_) => t == "string",
    Json::Num(_) => t == "integer" || t == "number",
    Json::Float(_) => t == "number",
    Json::Bool(_) => t == "boolean",
    Json::Null => t == "null",
  };
  if !ok {
    errs.push(E { path: path, msg: "expected " + t });
    return errs;
  }
  if let Some(m) = v.as_map() {
    let req = schema.get("required").and_then(|j| j.as_list()).unwrap_or([]);
    for r in req {
      if let Some(name) = r.as_str() {
        if m.get(name).is_none() {
          errs.push(E { path: path + "." + name, msg: "missing required field" });
        }
      }
    }
    let additional = schema.get("additional").and_then(|j| j.as_bool()).unwrap_or(true);
    for k in m.keys() {
      let sub = schema.get("properties").and_then(|p| p.get(k));
      let child = path + "." + k;
      match sub {
        Some(s) => {
          if let Some(cv) = m.get(k) {
            for e in check(s, cv, child) { errs.push(e); }
          }
        }
        None => {
          if !additional {
            errs.push(E { path: child, msg: "unexpected field" });
          }
        }
      }
    }
  }
  if let Some(a) = v.as_list() {
    if let Some(n) = schema.get("min_items").and_then(|j| j.as_int()) {
      if a.len() < n {
        errs.push(E { path: path, msg: "fewer than " + n.to_str() + " items" });
      }
    }
    if let Some(s) = schema.get("items") {
      for i in 0..a.len() {
        for e in check(s, a[i], path + "[" + i.to_str() + "]") { errs.push(e); }
      }
    }
  }
  if let Some(s) = v.as_str() {
    let n = s.chars().len();
    let mut done = false;
    if let Some(lo) = schema.get("min_length").and_then(|j| j.as_int()) {
      if n < lo {
        errs.push(E { path: path, msg: "shorter than " + lo.to_str() });
        done = true;
      }
    }
    if !done {
      if let Some(hi) = schema.get("max_length").and_then(|j| j.as_int()) {
        if n > hi {
          errs.push(E { path: path, msg: "longer than " + hi.to_str() });
          done = true;
        }
      }
    }
    if !done {
      if let Some(l) = schema.get("enum").and_then(|j| j.as_list()) {
        let mut found = false;
        for x in l {
          if let Some(xs) = x.as_str() {
            if xs == s { found = true; }
          }
        }
        if !found {
          errs.push(E { path: path, msg: "not in enum" });
        }
      }
    }
  }
  match v {
    Json::Num(n) => {
      if let Some(msg) = bound_int(schema, n) {
        errs.push(E { path: path, msg: msg });
      }
    }
    Json::Float(f) => {
      if let Some(msg) = bound_float(schema, f) {
        errs.push(E { path: path, msg: msg });
      }
    }
    _ => {}
  }
  errs
}

