struct Rec { version: Int, body: Str }

struct Entry { id: Str, version: Int, body: Str }

fn parse_line(line: Str) -> Option<Entry> {
  let doc = line.parse_json().ok()?;
  let id = doc.get("id").and_then(|j| j.as_str())?;
  let version = doc.get("version").and_then(|j| j.as_int())?;
  Some(Entry { id: id, version: version, body: doc.to_json() })
}

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, KvErr> {
  let text = input.read("records.jsonl").unwrap_or("".to_bytes()).to_str();
  let mut out: List<Str> = [];
  let mut recs: Map<Str, Rec> = Map::new();
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim().len() == 0 { continue; }
    match parse_line(line) {
      Some(e) => recs.insert(e.id, Rec { version: e.version, body: e.body }),
      None => out.push("line " + n.to_str() + " invalid"),
    }
  }
  let mut status: Map<Str, Str> = Map::new();
  let mut pending: List<Str> = [];
  for id in recs.keys() {
    let rec = recs.get(id).unwrap_or(Rec { version: 0, body: "" });
    let last: Option<Int> = match state.get("v/" + id)? {
      Some(b) => b.to_str().parse_int(),
      None => None,
    };
    let push = match last {
      Some(v) => rec.version > v,
      None => true,
    };
    if push { pending.push(id); } else { status.insert(id, "unchanged"); }
  }
  for round in 0..3 {
    if pending.len() == 0 { break; }
    let mut next: List<Str> = [];
    let mut i = 0;
    while i < pending.len() {
      let end = (i + 64).min(pending.len());
      let mut reqs: List<HttpRequest> = [];
      for k in i..end {
        let id = pending[k];
        let rec = recs.get(id).unwrap_or(Rec { version: 0, body: "" });
        reqs.push(HttpRequest {
          method: "PUT",
          path: "/records/" + id,
          headers: ["content-type: application/json"],
          body: rec.body.to_bytes(),
          timeout_ms: 0,
        });
      }
      let res = api.send_all(reqs);
      for k in 0..res.len() {
        let id = pending[i + k];
        match res[k] {
          Ok(r) => {
            if r.status >= 200 && r.status < 300 {
              let rec = recs.get(id).unwrap_or(Rec { version: 0, body: "" });
              state.set("v/" + id, rec.version.to_str().to_bytes())?;
              status.insert(id, "synced");
            } else if r.status >= 400 && r.status < 500 {
              status.insert(id, "rejected " + r.status.to_str());
            } else {
              next.push(id);
            }
          }
          Err(_) => next.push(id),
        }
      }
      i = end;
    }
    pending = next;
  }
  for id in pending { status.insert(id, "failed"); }
  let mut s = 0;
  let mut u = 0;
  let mut r = 0;
  let mut f = 0;
  for id in recs.keys() {
    let st = status.get(id).unwrap_or("failed");
    out.push(id + " " + st);
    if st == "synced" { s += 1; }
    else if st == "unchanged" { u += 1; }
    else if st == "failed" { f += 1; }
    else { r += 1; }
  }
  out.push("synced " + s.to_str() + " unchanged " + u.to_str() + " rejected " + r.to_str() + " failed " + f.to_str());
  Ok(out.join("\n"))
}

struct Rec { id: Str, version: Int, body: Str }

fn parse_line(t: Str) -> Option<Rec> {
  let j = t.parse_json().ok()?;
  let id = j.get("id")?.as_str()?;
  let version = j.get("version")?.as_int()?;
  Some(Rec { id: id, version: version, body: t })
}

fn last_version(state: Kv, id: Str) -> Option<Int> {
  match state.get("v/" + id) {
    Ok(Some(b)) => b.to_str().parse_int(),
    _ => None,
  }
}

fn push(api: Http, id: Str, body: Str) -> Str {
  let mut attempt = 0;
  while attempt < 3 {
    attempt += 1;
    match api.send("PUT", "/records/" + id, ["content-type: application/json"], body.to_bytes(), 0) {
      Ok(r) => {
        if r.status >= 200 && r.status < 300 { return "synced"; }
        if r.status >= 400 && r.status < 500 { return "rejected " + r.status.to_str(); }
      }
      Err(_) => {}
    }
  }
  "failed"
}

fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Str> {
  let text = match input.read("records.jsonl") {
    Ok(b) => b.to_str(),
    Err(_) => return Err("cannot read records.jsonl"),
  };
  let mut out: List<Str> = [];
  let mut recs: Map<Str, Rec> = Map::new();
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    let t = line.trim();
    if t == "" { continue; }
    match parse_line(t) {
      Some(r) => recs.insert(r.id, r),
      None => out.push("line " + n.to_str() + " invalid"),
    }
  }
  let mut s = 0;
  let mut u = 0;
  let mut rj = 0;
  let mut f = 0;
  for id in recs.keys() {
    let Some(rec) = recs.get(id) else { continue; };
    let mut skip = false;
    if let Some(v) = last_version(state, id) {
      if rec.version <= v { skip = true; }
    }
    if skip {
      u += 1;
      out.push(id + " unchanged");
      continue;
    }
    let res = push(api, id, rec.body);
    if res == "synced" {
      s += 1;
      let _ = state.set("v/" + id, rec.version.to_str().to_bytes());
    } else if res == "failed" {
      f += 1;
    } else {
      rj += 1;
    }
    out.push(id + " " + res);
  }
  out.push("synced " + s.to_str() + " unchanged " + u.to_str() + " rejected " + rj.to_str() + " failed " + f.to_str());
  Ok(out.join("\n"))
}

