const MAXI: Int = 9223372036854775807;

struct Acct { bal: Int, closed: Bool }

enum Outcome { Done, Dup, Fail(Str) }

fn dberr(e: DbErr) -> Str { "db error" }

fn get_int(v: SqlValue) -> Int {
  match v { SqlValue::Int(i) => i, _ => 0 }
}

fn get_text(v: SqlValue) -> Str {
  match v { SqlValue::Text(s) => s, _ => "" }
}

fn fetch(db: Db, name: Str) -> Result<Option<Acct>, Str> {
  let rows = db.query("SELECT balance, closed FROM accounts WHERE name = ?", [SqlValue::Text(name)]).map_err(dberr)?;
  if rows.len() == 0 { return Ok(None); }
  Ok(Some(Acct { bal: get_int(rows[0][0]), closed: get_int(rows[0][1]) != 0 }))
}

fn live(db: Db, name: Str) -> Result<Option<Int>, Str> {
  let a = fetch(db, name)?;
  match a {
    Some(x) => if x.closed { Ok(None) } else { Ok(Some(x.bal)) },
    None => Ok(None),
  }
}

fn fail(m: Str) -> Result<Outcome, Str> { Ok(Outcome::Fail(m)) }

fn do_op(db: Db, line: Str, now: Str) -> Result<Outcome, Str> {
  let w = line.split(" ");
  let op = w[0];
  if op == "open" {
    if w.len() != 3 { return fail("malformed"); }
    let Some(c) = w[2].parse_int() else { return fail("malformed"); };
    if c < 0 { return fail("bad amount"); }
    let ex = fetch(db, w[1])?;
    if ex.is_some() { return fail("account exists"); }
    db.exec("INSERT INTO accounts(name, balance, last, closed) VALUES(?, ?, ?, 0)",
      [SqlValue::Text(w[1]), SqlValue::Int(c), SqlValue::Text(now)]).map_err(dberr)?;
    return Ok(Outcome::Done);
  }
  if op == "close" {
    if w.len() != 2 { return fail("malformed"); }
    let b = live(db, w[1])?;
    let Some(bal) = b else { return fail("no account " + w[1]); };
    if bal != 0 { return fail("balance not zero"); }
    db.exec("UPDATE accounts SET closed = 1, last = ? WHERE name = ?",
      [SqlValue::Text(now), SqlValue::Text(w[1])]).map_err(dberr)?;
    return Ok(Outcome::Done);
  }
  if op == "transfer" {
    if w.len() != 5 { return fail("malformed"); }
    let Some(c) = w[4].parse_int() else { return fail("malformed"); };
    let id = w[1];
    let from = w[2];
    let to = w[3];
    let rows = db.query("SELECT from_a, to_a, cents FROM transfers WHERE id = ?", [SqlValue::Text(id)]).map_err(dberr)?;
    if rows.len() > 0 {
      if get_text(rows[0][0]) == from && get_text(rows[0][1]) == to && get_int(rows[0][2]) == c {
        return Ok(Outcome::Dup);
      }
      return fail("id reused");
    }
    if c <= 0 { return fail("bad amount"); }
    if from == to { return fail("same account"); }
    let fb = live(db, from)?;
    let Some(fbal) = fb else { return fail("no account " + from); };
    let tb = live(db, to)?;
    let Some(tbal) = tb else { return fail("no account " + to); };
    if fbal < c { return fail("insufficient funds"); }
    if tbal > MAXI - c { return fail("overflow"); }
    let stmts = [
      "UPDATE accounts SET balance = balance - ?, last = ? WHERE name = ?",
      "UPDATE accounts SET balance = balance + ?, last = ? WHERE name = ?",
      "INSERT INTO transfers(id, from_a, to_a, cents) VALUES(?, ?, ?, ?)"
    ];
    let params = [
      [SqlValue::Int(c), SqlValue::Text(now), SqlValue::Text(from)],
      [SqlValue::Int(c), SqlValue::Text(now), SqlValue::Text(to)],
      [SqlValue::Text(id), SqlValue::Text(from), SqlValue::Text(to), SqlValue::Int(c)]
    ];
    db.transaction(stmts, params).map_err(dberr)?;
    return Ok(Outcome::Done);
  }
  fail("malformed")
}

fn main(input: Dir, db: Db, log: Log, clock: Clock) -> Result<Str, Str> {
  db.exec("CREATE TABLE IF NOT EXISTS accounts(name TEXT PRIMARY KEY, balance INTEGER NOT NULL, last TEXT NOT NULL, closed INTEGER NOT NULL)", []).map_err(dberr)?;
  db.exec("CREATE TABLE IF NOT EXISTS transfers(id TEXT PRIMARY KEY, from_a TEXT NOT NULL, to_a TEXT NOT NULL, cents INTEGER NOT NULL)", []).map_err(dberr)?;
  let tr = db.query("SELECT strftime('%Y-%m-%dT%H:%M:%SZ', ? / 1000, 'unixepoch')", [SqlValue::Int(clock.now_ms())]).map_err(dberr)?;
  let now = get_text(tr[0][0]);
  let text = input.read("ops.txt").map_err(|e| "cannot read ops.txt")?.to_str();
  let lines = text.lines();
  let mut ok = 0;
  let mut failed = 0;
  let mut dup = 0;
  for i in 0..lines.len() {
    let line = lines[i];
    if line.trim() == "" { continue; }
    let r = do_op(db, line, now)?;
    match r {
      Outcome::Done => ok += 1,
      Outcome::Dup => dup += 1,
      Outcome::Fail(m) => {
        failed += 1;
        let lr = log.write(now + " line " + (i + 1).to_str() + ": " + m);
        if lr.is_err() { return Err("log error"); }
      }
    }
  }
  let mut out = "ok " + ok.to_str() + " failed " + failed.to_str() + " duplicate " + dup.to_str() + "\n";
  let rows = db.query("SELECT name, balance, last FROM accounts WHERE closed = 0 ORDER BY name", []).map_err(dberr)?;
  for r in rows {
    out = out + get_text(r[0]) + " " + get_int(r[1]).to_str() + " last " + get_text(r[2]) + "\n";
  }
  Ok(out)
}

struct Resp { status: Int, body: Json }
struct Creds { name: Str, pw: Str }
struct Sess { token: Str, name: Str, exp: Int }

fn obj1(k: Str, v: Json) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert(k, v);
  Json::Obj(m)
}

fn err(status: Int, msg: Str) -> Resp {
  Resp { status: status, body: obj1("error", Json::Str(msg)) }
}

fn valid_utf8(b: Bytes) -> Bool {
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c < 128 { i += 1; continue; }
    let mut need = 0;
    let mut lo = 128;
    let mut hi = 191;
    if c >= 194 && c <= 223 {
      need = 1;
    } else if c >= 224 && c <= 239 {
      need = 2;
      if c == 224 { lo = 160; }
      if c == 237 { hi = 159; }
    } else if c >= 240 && c <= 244 {
      need = 3;
      if c == 240 { lo = 144; }
      if c == 244 { hi = 143; }
    } else {
      return false;
    }
    if i + need >= n { return false; }
    let c1 = b[i + 1];
    if c1 < lo || c1 > hi { return false; }
    let mut k = 2;
    while k <= need {
      let ck = b[i + k];
      if ck < 128 || ck > 191 { return false; }
      k += 1;
    }
    i += need + 1;
  }
  true
}

fn valid_name(name: Str) -> Bool {
  let n = name.len();
  if n < 3 || n > 20 { return false; }
  for c in name.chars() {
    let ok = (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "_";
    if !ok { return false; }
  }
  true
}

fn parse_creds(body: Bytes) -> Option<Creds> {
  if !valid_utf8(body) { return None; }
  let j = match body.to_str().parse_json() {
    Ok(j) => j,
    Err(_) => return None,
  };
  let Some(_) = j.as_map() else { return None; };
  let Some(name) = j.get("name").and_then(|x| x.as_str()) else { return None; };
  let Some(pw) = j.get("password").and_then(|x| x.as_str()) else { return None; };
  if !valid_name(name) { return None; }
  Some(Creds { name: name, pw: pw })
}

fn hash_pw(name: Str, pw: Str) -> Str {
  (name + ":" + pw).sha256().to_hex()
}

fn bearer(names: List<Str>, values: List<Str>) -> Option<Str> {
  for i in 0..names.len() {
    if names[i] == "authorization" {
      return values[i].strip_prefix("Bearer ");
    }
  }
  None
}

fn find_session(store: Kv, now: Int, auth: Option<Str>) -> Result<Option<Sess>, KvErr> {
  let Some(token) = auth else { return Ok(None); };
  if token.len() != 32 { return Ok(None); }
  let Some(raw) = store.get("s/" + token)? else { return Ok(None); };
  let parts = raw.to_str().split("|");
  if parts.len() != 2 { return Ok(None); }
  let Some(exp) = parts[1].parse_int() else { return Ok(None); };
  if now >= exp { return Ok(None); }
  Ok(Some(Sess { token: token, name: parts[0], exp: exp }))
}

fn create_user(store: Kv, body: Bytes) -> Result<Resp, KvErr> {
  let Some(c) = parse_creds(body) else { return Ok(err(400, "invalid")); };
  if c.pw.len() < 8 { return Ok(err(400, "invalid")); }
  let h = hash_pw(c.name, c.pw);
  let claimed = store.swap("u/" + c.name, None, Some(h.to_bytes()))?;
  if !claimed { return Ok(err(409, "name taken")); }
  Ok(Resp { status: 201, body: obj1("name", Json::Str(c.name)) })
}

fn login(store: Kv, clock: Clock, rng: Rng, body: Bytes) -> Result<Resp, KvErr> {
  let now = clock.now_ms();
  let bad = err(401, "bad credentials");
  let Some(c) = parse_creds(body) else { return Ok(bad); };
  let Some(stored) = store.get("u/" + c.name)? else { return Ok(bad); };
  if let Some(lk) = store.get("lock/" + c.name)? {
    let until = lk.to_str().parse_int().unwrap_or(0);
    if now < until { return Ok(err(429, "locked")); }
  }
  let h = hash_pw(c.name, c.pw);
  if !stored.to_str().ct_eq(h) {
    let n = store.add("fail/" + c.name, 1)?;
    if n >= 3 {
      store.set("lock/" + c.name, (now + 900000).to_str().to_bytes())?;
      store.set("fail/" + c.name, "0".to_bytes())?;
    }
    return Ok(bad);
  }
  store.set("fail/" + c.name, "0".to_bytes())?;
  let _ = store.add("logins/" + c.name, 1)?;
  let token = rng.bytes(16).to_hex();
  let exp = now + 1800000;
  store.set("s/" + token, (c.name + "|" + exp.to_str()).to_bytes())?;
  let mut m: Map<Str, Json> = Map::new();
  m.insert("token", Json::Str(token));
  m.insert("expires_in", Json::Num(1800));
  Ok(Resp { status: 200, body: Json::Obj(m) })
}

fn me(store: Kv, clock: Clock, auth: Option<Str>) -> Result<Resp, KvErr> {
  let now = clock.now_ms();
  let Some(s) = find_session(store, now, auth)? else { return Ok(err(401, "unauthorized")); };
  let exp = now + 1800000;
  store.set("s/" + s.token, (s.name + "|" + exp.to_str()).to_bytes())?;
  let logins = match store.get("logins/" + s.name)? {
    Some(b) => b.to_str().parse_int().unwrap_or(0),
    None => 0,
  };
  let mut m: Map<Str, Json> = Map::new();
  m.insert("name", Json::Str(s.name));
  m.insert("logins", Json::Num(logins));
  Ok(Resp { status: 200, body: Json::Obj(m) })
}

fn logout(store: Kv, clock: Clock, auth: Option<Str>) -> Result<Resp, KvErr> {
  let now = clock.now_ms();
  let Some(s) = find_session(store, now, auth)? else { return Ok(err(401, "unauthorized")); };
  store.delete("s/" + s.token)?;
  Ok(Resp { status: 204, body: Json::Null })
}

fn handle(store: Kv, clock: Clock, rng: Rng, method: Str, path: Str, body: Bytes, auth: Option<Str>) -> Result<Resp, KvErr> {
  if method == "POST" && path == "/users" { return create_user(store, body); }
  if method == "POST" && path == "/login" { return login(store, clock, rng, body); }
  if method == "GET" && path == "/me" { return me(store, clock, auth); }
  if method == "POST" && path == "/logout" { return logout(store, clock, auth); }
  Ok(err(404, "not found"))
}

fn main(req: Incoming, res: Outgoing, store: Kv, clock: Clock, rng: Rng) -> Result<Str, WebErr> {
  let method = req.method();
  let target = req.target();
  let path = match target.find("?") {
    Some(i) => target.slice(0, i),
    None => target,
  };
  let auth = bearer(req.header_names(), req.header_values());
  let r = match handle(store, clock, rng, method, path, req.body(), auth) {
    Ok(r) => r,
    Err(_) => err(500, "internal"),
  };
  if r.status == 204 {
    res.send(204, [], [], "".to_bytes())?;
  } else {
    res.send(r.status, ["content-type"], ["application/json"], r.body.to_json().to_bytes())?;
  }
  Ok("")
}

struct Resp { status: Int, body: Str }
struct NewPay { account: Str, cents: Int, currency: Str }

fn err(status: Int, msg: Str) -> Resp {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Resp { status: status, body: Json::Obj(m).to_json() }
}

fn text(v: SqlValue) -> Str { match v { SqlValue::Text(s) => s, _ => "" } }
fn int(v: SqlValue) -> Int { match v { SqlValue::Int(n) => n, _ => 0 } }

fn row_json(r: List<SqlValue>) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str("pay_" + int(r[0]).to_str()));
  m.insert("account", Json::Str(text(r[1])));
  m.insert("cents", Json::Num(int(r[2])));
  m.insert("currency", Json::Str(text(r[3])));
  m.insert("status", Json::Str(text(r[4])));
  m.insert("refunded", Json::Num(int(r[5])));
  Json::Obj(m)
}

fn hexv(b: Int) -> Int {
  if b >= 48 && b <= 57 { b - 48 }
  else if b >= 97 && b <= 102 { b - 87 }
  else if b >= 65 && b <= 70 { b - 55 }
  else { -1 }
}

fn url_decode(s: Str) -> Str {
  let bs = s.to_bytes();
  let mut out = "".to_bytes();
  let mut i = 0;
  while i < bs.len() {
    let b = bs[i];
    if b == 43 {
      out.push(32);
      i += 1;
    } else if b == 37 && i + 2 < bs.len() {
      let h = hexv(bs[i + 1]);
      let l = hexv(bs[i + 2]);
      if h >= 0 && l >= 0 {
        out.push(h * 16 + l);
        i += 3;
      } else {
        out.push(b);
        i += 1;
      }
    } else {
      out.push(b);
      i += 1;
    }
  }
  out.to_str()
}

fn idem_key(req: Incoming) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  let mut i = 0;
  while i < names.len() {
    if names[i] == "idempotency-key" { return Some(values[i]); }
    i += 1;
  }
  None
}

fn idem_check(db: Db, key: Str, method: Str, path: Str, canon: Str) -> Result<Option<Resp>, DbErr> {
  let rows = db.query("SELECT method, path, body, status, resp FROM idem WHERE key = ?", [SqlValue::Text(key)])?;
  if rows.len() == 0 { return Ok(None); }
  let r = rows[0];
  if text(r[0]) == method && text(r[1]) == path && text(r[2]) == canon {
    Ok(Some(Resp { status: int(r[3]), body: text(r[4]) }))
  } else {
    Ok(Some(err(409, "key reused")))
  }
}

fn parse_new(j: Json) -> Option<NewPay> {
  let Some(m) = j.as_map() else { return None; };
  if m.len() != 3 { return None; }
  let Some(a) = m.get("account").and_then(|x| x.as_str()) else { return None; };
  let Some(c) = m.get("cents").and_then(|x| x.as_int()) else { return None; };
  let Some(cur) = m.get("currency").and_then(|x| x.as_str()) else { return None; };
  if a.len() > 0 && c > 0 && (cur == "EUR" || cur == "USD") {
    Some(NewPay { account: a, cents: c, currency: cur })
  } else {
    None
  }
}

fn parse_refund(raw: Str) -> Option<Int> {
  let Ok(j) = raw.parse_json() else { return None; };
  let Some(m) = j.as_map() else { return None; };
  let Some(c) = m.get("cents").and_then(|x| x.as_int()) else { return None; };
  if c > 0 { Some(c) } else { None }
}

fn find_pay(db: Db, n: Int) -> Result<Option<List<SqlValue>>, DbErr> {
  let rows = db.query("SELECT n, account, cents, currency, status, refunded FROM payments WHERE n = ?", [SqlValue::Int(n)])?;
  if rows.len() == 0 { Ok(None) } else { Ok(Some(rows[0])) }
}

fn ok_pay(r: List<SqlValue>) -> Resp {
  Resp { status: 200, body: row_json(r).to_json() }
}

fn handle(req: Incoming, db: Db) -> Result<Resp, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS payments (n INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, refunded INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS idem (key TEXT PRIMARY KEY, method TEXT NOT NULL, path TEXT NOT NULL, body TEXT NOT NULL, status INTEGER NOT NULL, resp TEXT NOT NULL)", [])?;
  let method = req.method();
  let target = req.target();
  let mut path = target;
  let mut query = "";
  if let Some(i) = target.find("?") {
    path = target.slice(0, i);
    query = target.slice(i + 1, target.len());
  }
  let segs = path.split("/");
  let nf = err(404, "not found");
  if segs.len() < 2 || segs.len() > 4 || segs[0] != "" || segs[1] != "payments" { return Ok(nf); }

  if segs.len() == 2 {
    if method == "GET" {
      let mut account = "";
      for part in query.split("&") {
        if let Some(v) = part.strip_prefix("account=") { account = url_decode(v); }
      }
      let rows = db.query("SELECT n, account, cents, currency, status, refunded FROM payments WHERE account = ? ORDER BY n", [SqlValue::Text(account)])?;
      let mut out: List<Json> = [];
      for r in rows { out.push(row_json(r)); }
      return Ok(Resp { status: 200, body: Json::Arr(out).to_json() });
    }
    if method != "POST" { return Ok(nf); }
    let Some(key) = idem_key(req) else { return Ok(err(400, "missing idempotency key")); };
    let raw = req.body().to_str();
    let mut canon = raw;
    let parsed = raw.parse_json();
    if let Ok(j) = parsed { canon = j.to_json(); }
    if let Some(r) = idem_check(db, key, method, path, canon)? { return Ok(r); }
    let Ok(j) = parsed else { return Ok(err(422, "invalid payment")); };
    let Some(p) = parse_new(j) else { return Ok(err(422, "invalid payment")); };
    let stmts = [
      "INSERT INTO payments(account, cents, currency, status, refunded) VALUES (?, ?, ?, 'pending', 0)",
      "INSERT INTO idem(key, method, path, body, status, resp) VALUES (?, ?, ?, ?, 201, json_object('id', 'pay_' || last_insert_rowid(), 'account', ?, 'cents', ?, 'currency', ?, 'status', 'pending', 'refunded', 0))"
    ];
    let params = [
      [SqlValue::Text(p.account), SqlValue::Int(p.cents), SqlValue::Text(p.currency)],
      [SqlValue::Text(key), SqlValue::Text(method), SqlValue::Text(path), SqlValue::Text(canon),
       SqlValue::Text(p.account), SqlValue::Int(p.cents), SqlValue::Text(p.currency)]
    ];
    match db.transaction(stmts, params) {
      Ok(_) => {},
      Err(DbErr::Constraint(_)) => {
        if let Some(r) = idem_check(db, key, method, path, canon)? { return Ok(r); }
        return Ok(err(500, "internal"));
      },
      Err(e) => return Err(e),
    }
    let rows = db.query("SELECT resp FROM idem WHERE key = ?", [SqlValue::Text(key)])?;
    if rows.len() == 0 { return Ok(err(500, "internal")); }
    return Ok(Resp { status: 201, body: text(rows[0][0]) });
  }

  let Some(rest) = segs[2].strip_prefix("pay_") else { return Ok(nf); };
  let Some(n) = rest.parse_int() else { return Ok(nf); };
  if n <= 0 || n.to_str() != rest { return Ok(nf); }

  if segs.len() == 3 {
    if method != "GET" { return Ok(nf); }
    return match find_pay(db, n)? {
      Some(r) => Ok(ok_pay(r)),
      None => Ok(nf),
    };
  }

  let action = segs[3];
  if method != "POST" { return Ok(nf); }
  if action == "capture" || action == "cancel" {
    let target_status = if action == "capture" { "captured" } else { "canceled" };
    let changed = db.exec("UPDATE payments SET status = ? WHERE n = ? AND status = 'pending'", [SqlValue::Text(target_status), SqlValue::Int(n)])?;
    let Some(r) = find_pay(db, n)? else { return Ok(nf); };
    if changed == 1 { return Ok(ok_pay(r)); }
    if action == "capture" && text(r[4]) == "captured" { return Ok(ok_pay(r)); }
    return Ok(err(409, "invalid transition"));
  }
  if action == "refund" {
    let Some(key) = idem_key(req) else { return Ok(err(400, "missing idempotency key")); };
    let raw = req.body().to_str();
    let mut canon = raw;
    if let Ok(j) = raw.parse_json() { canon = j.to_json(); }
    if let Some(r) = idem_check(db, key, method, path, canon)? { return Ok(r); }
    let Some(p) = find_pay(db, n)? else { return Ok(nf); };
    let Some(c) = parse_refund(raw) else { return Ok(err(422, "invalid refund")); };
    if text(p[4]) != "captured" { return Ok(err(409, "invalid transition")); }
    let stmts = [
      "UPDATE payments SET refunded = refunded + ?, status = CASE WHEN refunded + ? = cents THEN 'refunded' ELSE status END WHERE n = ? AND status = 'captured' AND refunded + ? <= cents",
      "INSERT INTO idem(key, method, path, body, status, resp) SELECT ?, ?, ?, ?, 200, json_object('id', 'pay_' || n, 'account', account, 'cents', cents, 'currency', currency, 'status', status, 'refunded', refunded) FROM payments WHERE n = ? AND changes() > 0"
    ];
    let params = [
      [SqlValue::Int(c), SqlValue::Int(c), SqlValue::Int(n), SqlValue::Int(c)],
      [SqlValue::Text(key), SqlValue::Text(method), SqlValue::Text(path), SqlValue::Text(canon), SqlValue::Int(n)]
    ];
    let mut changed = 0;
    match db.transaction(stmts, params) {
      Ok(k) => { changed = k; },
      Err(DbErr::Constraint(_)) => {
        if let Some(r) = idem_check(db, key, method, path, canon)? { return Ok(r); }
        return Ok(err(500, "internal"));
      },
      Err(e) => return Err(e),
    }
    if changed >= 2 {
      let rows = db.query("SELECT resp FROM idem WHERE key = ?", [SqlValue::Text(key)])?;
      if rows.len() == 0 { return Ok(err(500, "internal")); }
      return Ok(Resp { status: 200, body: text(rows[0][0]) });
    }
    let Some(q) = find_pay(db, n)? else { return Ok(nf); };
    if text(q[4]) != "captured" { return Ok(err(409, "invalid transition")); }
    return Ok(err(409, "exceeds captured"));
  }
  Ok(nf)
}

fn main(req: Incoming, res: Outgoing, db: Db) -> Result<Str, WebErr> {
  let r = match handle(req, db) {
    Ok(r) => r,
    Err(_) => err(500, "internal"),
  };
  res.send(r.status, ["content-type"], ["application/json"], r.body.to_bytes())?;
  Ok("")
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn num(b: Bytes, a: Int, e: Int) -> Int {
  let mut v = 0;
  for i in a..e {
    let c = b[i];
    if c < 48 || c > 57 { return -1; }
    v = v * 10 + (c - 48);
  }
  v
}

fn parse_time(t: Str) -> Option<Int> {
  if t.len() != 20 { return None; }
  let b = t.to_bytes();
  if b[4] != 45 || b[7] != 45 || b[10] != 84 || b[13] != 58 || b[16] != 58 || b[19] != 90 {
    return None;
  }
  let y = num(b, 0, 4);
  let mo = num(b, 5, 7);
  let d = num(b, 8, 10);
  let h = num(b, 11, 13);
  let mi = num(b, 14, 16);
  let s = num(b, 17, 19);
  if y < 0 || mo < 0 || d < 0 || h < 0 || mi < 0 || s < 0 { return None; }
  if mo < 1 || mo > 12 { return None; }
  if h > 23 || mi > 59 || s > 59 { return None; }
  let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
  let dim = match mo {
    2 => if leap { 29 } else { 28 },
    4 | 6 | 9 | 11 => 30,
    _ => 31,
  };
  if d < 1 || d > dim { return None; }
  let yy = (if mo <= 2 { y - 1 } else { y }) + 400;
  let era = yy / 400;
  let yoe = yy - era * 400;
  let mp = if mo > 2 { mo - 3 } else { mo + 9 };
  let doy = (153 * mp + 2) / 5 + d - 1;
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  let days = era * 146097 + doe;
  Some(days * 86400 + h * 3600 + mi * 60 + s)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut users: Map<Str, List<Int>> = Map::new();
  let mut upages: HashMap<Str, Bool> = HashMap::new();
  let mut ucount: Map<Str, Int> = Map::new();
  let mut pages: Map<Str, Int> = Map::new();
  let mut malformed = 0;
  let mut dups = 0;
  let mut total = 0;
  for line in text.lines() {
    if line.len() == 0 { continue; }
    if seen.get(line).is_some() { dups += 1; continue; }
    seen.insert(line, true);
    let parts = line.split(" ");
    if parts.len() != 3 { malformed += 1; continue; }
    let Some(ts) = parse_time(parts[0]) else { malformed += 1; continue; };
    let u = parts[1];
    let p = parts[2];
    total += 1;
    let mut l: List<Int> = users.get(u).unwrap_or([]);
    l.push(ts);
    users.insert(u, l);
    let key = u + " " + p;
    if upages.get(key).is_none() {
      upages.insert(key, true);
      ucount.insert(u, ucount.get(u).unwrap_or(0) + 1);
    }
    pages.insert(p, pages.get(p).unwrap_or(0) + 1);
  }
  let mut lines: List<Str> = [];
  let mut durs: List<Int> = [];
  if total > 0 {
    for u in users.keys() {
      let mut times: List<Int> = users.get(u).unwrap_or([]);
      times.sort();
      let n = times.len();
      let mut start = times[0];
      let mut prev = start;
      let mut sessions = 0;
      let mut longest = 0;
      for i in 1..n {
        let t = times[i];
        if t - prev > 1800 {
          let dur = prev - start;
          durs.push(dur);
          longest = longest.max(dur);
          sessions += 1;
          start = t;
        }
        prev = t;
      }
      let dur = prev - start;
      durs.push(dur);
      longest = longest.max(dur);
      sessions += 1;
      let hms = pad2(longest / 3600) + ":" + pad2((longest % 3600) / 60) + ":" + pad2(longest % 60);
      lines.push(u + " sessions " + sessions.to_str() + " events " + n.to_str() + " longest " + hms + " pages " + ucount.get(u).unwrap_or(0).to_str());
    }
    durs.sort();
    lines.push("median " + durs[(durs.len() - 1) / 2].to_str());
    let mut names = pages.keys();
    let pc = pages;
    names.sort_by(|a, b| {
      let ca = pc.get(a).unwrap_or(0);
      let cb = pc.get(b).unwrap_or(0);
      if ca != cb { ca > cb } else { a < b }
    });
    let mut tops: List<Str> = [];
    let mut i = 0;
    while i < 3 && i < names.len() {
      tops.push(names[i] + " (" + pc.get(names[i]).unwrap_or(0).to_str() + ")");
      i += 1;
    }
    lines.push("top: " + tops.join(", "));
  }
  lines.push("malformed " + malformed.to_str() + " duplicates " + dups.to_str());
  Ok(lines.join("\n"))
}

fn num(b: Bytes, a: Int, n: Int) -> Int {
  let mut v = 0;
  for i in a..a + n { v = v * 10 + b[i] - 48; }
  v
}

fn is_leap(y: Int) -> Bool {
  (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn dim(y: Int, m: Int) -> Int {
  match m {
    2 => if is_leap(y) { 29 } else { 28 },
    4 | 6 | 9 | 11 => 30,
    _ => 31,
  }
}

fn parse_time(s: Str) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() != 20 { return None; }
  for i in 0..20 {
    let c = b[i];
    let ok = if i == 4 || i == 7 { c == 45 }
      else if i == 10 { c == 84 }
      else if i == 13 || i == 16 { c == 58 }
      else if i == 19 { c == 90 }
      else { c >= 48 && c <= 57 };
    if !ok { return None; }
  }
  let y = num(b, 0, 4);
  let mo = num(b, 5, 2);
  let d = num(b, 8, 2);
  let h = num(b, 11, 2);
  let mi = num(b, 14, 2);
  let se = num(b, 17, 2);
  if mo < 1 || mo > 12 { return None; }
  if d < 1 || d > dim(y, mo) { return None; }
  if h > 23 || mi > 59 || se > 59 { return None; }
  let mut days = 365 * y + (y + 399) / 400 - (y + 99) / 100 + (y + 3) / 4;
  for m2 in 1..mo { days += dim(y, m2); }
  days += d - 1;
  Some(days * 86400 + h * 3600 + mi * 60 + se)
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn hms(s: Int) -> Str {
  pad2(s / 3600) + ":" + pad2((s % 3600) / 60) + ":" + pad2(s % 60)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut times: Map<Str, List<Int>> = Map::new();
  let mut pageseen: HashMap<Str, Bool> = HashMap::new();
  let mut upages: Map<Str, Int> = Map::new();
  let mut pcount: Map<Str, Int> = Map::new();
  let mut malformed = 0;
  let mut dups = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let parts = line.split(" ");
    if parts.len() != 3 { malformed += 1; continue; }
    let Some(t) = parse_time(parts[0]) else { malformed += 1; continue; };
    if seen.get(line).is_some() { dups += 1; continue; }
    seen.insert(line, true);
    let user = parts[1];
    let page = parts[2];
    let mut ts = times.get(user).unwrap_or([]);
    ts.push(t);
    times.insert(user, ts);
    let key = user + " " + page;
    if pageseen.get(key).is_none() {
      pageseen.insert(key, true);
      upages.insert(user, upages.get(user).unwrap_or(0) + 1);
    }
    pcount.insert(page, pcount.get(page).unwrap_or(0) + 1);
  }
  let last = "malformed " + malformed.to_str() + " duplicates " + dups.to_str();
  if times.len() == 0 { return Ok(last); }
  let mut out: List<Str> = [];
  let mut durs: List<Int> = [];
  for u in times.keys() {
    let mut ts = times.get(u).unwrap_or([]);
    ts.sort();
    let mut sessions = 0;
    let mut longest = 0;
    let mut start = ts[0];
    let mut prev = ts[0];
    for i in 1..ts.len() {
      let t = ts[i];
      if t - prev > 1800 {
        let d = prev - start;
        durs.push(d);
        sessions += 1;
        if d > longest { longest = d; }
        start = t;
      }
      prev = t;
    }
    let d = prev - start;
    durs.push(d);
    sessions += 1;
    if d > longest { longest = d; }
    out.push(u + " sessions " + sessions.to_str() + " events " + ts.len().to_str()
      + " longest " + hms(longest) + " pages " + upages.get(u).unwrap_or(0).to_str());
  }
  durs.sort();
  out.push("median " + durs[(durs.len() - 1) / 2].to_str());
  let mut pc = pcount;
  let mut tops: List<Str> = [];
  for _i in 0..3 {
    let mut best = "";
    let mut bc = 0;
    for p in pc.keys() {
      let c = pc.get(p).unwrap_or(0);
      if c > bc { bc = c; best = p; }
    }
    if bc == 0 { break; }
    tops.push(best + " (" + bc.to_str() + ")");
    pc.remove(best);
  }
  out.push("top: " + tops.join(", "));
  out.push(last);
  Ok(out.join("\n"))
}

fn num(b: Bytes, from: Int, to: Int) -> Option<Int> {
  let mut v = 0;
  for i in from..to {
    let c = b[i];
    if c < 48 || c > 57 { return None; }
    v = v * 10 + c - 48;
  }
  Some(v)
}

fn dim(y: Int, m: Int) -> Int {
  if m == 2 {
    if y % 4 == 0 && (y % 100 != 0 || y % 400 == 0) { 29 } else { 28 }
  } else if m == 4 || m == 6 || m == 9 || m == 11 {
    30
  } else {
    31
  }
}

fn parse_time(s: Str) -> Option<Int> {
  let b = s.to_bytes();
  if b.len() != 20 { return None; }
  if b[4] != 45 || b[7] != 45 || b[10] != 84 || b[13] != 58 || b[16] != 58 || b[19] != 90 {
    return None;
  }
  let y = num(b, 0, 4)?;
  let mo = num(b, 5, 7)?;
  let d = num(b, 8, 10)?;
  let h = num(b, 11, 13)?;
  let mi = num(b, 14, 16)?;
  let sec = num(b, 17, 19)?;
  if mo < 1 || mo > 12 { return None; }
  if d < 1 || d > dim(y, mo) { return None; }
  if h > 23 || mi > 59 || sec > 59 { return None; }
  let yy = if mo <= 2 { y + 399 } else { y + 400 };
  let era = yy / 400;
  let yoe = yy - era * 400;
  let mp = if mo > 2 { mo - 3 } else { mo + 9 };
  let doy = (153 * mp + 2) / 5 + d - 1;
  let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  let days = era * 146097 + doe;
  Some(days * 86400 + h * 3600 + mi * 60 + sec)
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn hms(d: Int) -> Str {
  pad2(d / 3600) + ":" + pad2(d % 3600 / 60) + ":" + pad2(d % 60)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("events.log")?.to_str();
  let mut times: Map<Str, List<Int>> = Map::new();
  let mut seen: HashMap<Str, Bool> = HashMap::new();
  let mut upair: HashMap<Str, Bool> = HashMap::new();
  let mut upages: Map<Str, Int> = Map::new();
  let mut pcount: Map<Str, Int> = Map::new();
  let mut malformed = 0;
  let mut dups = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let parts = line.split(" ");
    if parts.len() != 3 { malformed += 1; continue; }
    let Some(t) = parse_time(parts[0]) else { malformed += 1; continue; };
    if parts[1] == "" || parts[2] == "" { malformed += 1; continue; }
    if seen.get(line).is_some() { dups += 1; continue; }
    seen.insert(line, true);
    let u = parts[1];
    let p = parts[2];
    let mut ts: List<Int> = times.get(u).unwrap_or([]);
    ts.push(t);
    times.insert(u, ts);
    let key = u + " " + p;
    if upair.get(key).is_none() {
      upair.insert(key, true);
      upages.insert(u, upages.get(u).unwrap_or(0) + 1);
    }
    pcount.insert(p, pcount.get(p).unwrap_or(0) + 1);
  }
  let mut lines: List<Str> = [];
  let mut durs: List<Int> = [];
  for u in times.keys() {
    let mut ts: List<Int> = times.get(u).unwrap_or([]);
    ts.sort();
    let mut sessions = 0;
    let mut longest = 0;
    let mut start = ts[0];
    let mut prev = ts[0];
    for i in 1..ts.len() {
      let t = ts[i];
      if t - prev > 1800 {
        let d = prev - start;
        durs.push(d);
        sessions += 1;
        if d > longest { longest = d; }
        start = t;
      }
      prev = t;
    }
    let d = prev - start;
    durs.push(d);
    sessions += 1;
    if d > longest { longest = d; }
    lines.push(u + " sessions " + sessions.to_str() + " events " + ts.len().to_str()
      + " longest " + hms(longest) + " pages " + upages.get(u).unwrap_or(0).to_str());
  }
  if durs.len() > 0 {
    durs.sort();
    lines.push("median " + durs[(durs.len() - 1) / 2].to_str());
    let mut pages = pcount.keys();
    pages.sort_by(|a, b| {
      let ca = pcount.get(a).unwrap_or(0);
      let cb = pcount.get(b).unwrap_or(0);
      if ca != cb { ca > cb } else { a < b }
    });
    let mut tops: List<Str> = [];
    let mut i = 0;
    while i < pages.len() && i < 3 {
      tops.push(pages[i] + " (" + pcount.get(pages[i]).unwrap_or(0).to_str() + ")");
      i += 1;
    }
    lines.push("top: " + tops.join(", "));
  }
  lines.push("malformed " + malformed.to_str() + " duplicates " + dups.to_str());
  Ok(lines.join("\n"))
}

struct Rec { fields: List<Str>, bad: Bool }
struct Item { region: Str, product: Str, qty: Int, cents: Int }

fn is_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for ch in s.chars() {
    if !"0123456789".contains(ch) { return false; }
  }
  true
}

fn parse_qty(s: Str) -> Option<Int> {
  let body = s.strip_prefix("-").unwrap_or(s);
  if !is_digits(body) { return None; }
  s.parse_int()
}

fn price_cents(s: Str) -> Option<Int> {
  let parts = s.split(".");
  if parts.len() == 1 {
    if !is_digits(parts[0]) { return None; }
    let w = parts[0].parse_int()?;
    return Some(w * 100);
  }
  if parts.len() == 2 {
    let f = parts[1];
    if !is_digits(parts[0]) || !is_digits(f) || f.len() > 2 { return None; }
    let w = parts[0].parse_int()?;
    let fv = f.parse_int()?;
    if f.len() == 1 { return Some(w * 100 + fv * 10); }
    return Some(w * 100 + fv);
  }
  None
}

fn check(r: Rec) -> Option<Item> {
  if r.bad || r.fields.len() != 5 { return None; }
  let f = r.fields;
  if f[0].len() == 0 || f[1].len() == 0 { return None; }
  let q = parse_qty(f[2])?;
  let p = price_cents(f[3])?;
  Some(Item { region: f[0], product: f[1], qty: q, cents: p })
}

fn parse(text: Str) -> List<Rec> {
  let cs = text.chars();
  let n = cs.len();
  let mut recs: List<Rec> = [];
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut in_q = false;
  let mut quoted = false;
  let mut closed = false;
  let mut bad = false;
  let mut has = false;
  let mut i = 0;
  while i < n {
    let c = cs[i];
    let nx = if i + 1 < n { cs[i + 1] } else { "" };
    if in_q {
      if c == "\"" {
        if nx == "\"" {
          cur = cur + "\"";
          i += 1;
        } else {
          in_q = false;
          closed = true;
        }
      } else {
        cur = cur + c;
      }
    } else {
      if c == "\n" || (c == "\r" && nx == "\n") {
        if c == "\r" { i += 1; }
        if has {
          fields.push(cur);
          recs.push(Rec { fields: fields, bad: bad });
        }
        cur = "";
        fields = [];
        bad = false;
        quoted = false;
        closed = false;
        has = false;
      } else if c == "," {
        fields.push(cur);
        cur = "";
        quoted = false;
        closed = false;
        has = true;
      } else if c == "\"" {
        if cur == "" && !quoted && !closed {
          in_q = true;
          quoted = true;
        } else {
          bad = true;
        }
        has = true;
      } else {
        if closed { bad = true; } else { cur = cur + c; }
        has = true;
      }
    }
    i += 1;
  }
  if has {
    fields.push(cur);
    recs.push(Rec { fields: fields, bad: bad || in_q });
  }
  recs
}

fn quote(s: Str) -> Str {
  if s.contains(",") || s.contains("\"") || s.contains("\r") || s.contains("\n") {
    "\"" + s.replace("\"", "\"\"") + "\""
  } else {
    s
  }
}

fn fmt(cents: Int) -> Str {
  let a = if cents < 0 { -cents } else { cents };
  let r = a % 100;
  let rs = if r < 10 { "0" + r.to_str() } else { r.to_str() };
  let sign = if cents < 0 { "-" } else { "" };
  sign + (a / 100).to_str() + "." + rs
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let recs = parse(text);
  let mut clean = "region,product,qty,price,note\n";
  let mut bad_list: List<Str> = [];
  let mut prods: Map<Str, Map<Str, Int>> = Map::new();
  let mut totals: Map<Str, Int> = Map::new();
  let mut qtys: Map<Str, Int> = Map::new();
  for j in 1..recs.len() {
    match check(recs[j]) {
      None => bad_list.push(j.to_str()),
      Some(it) => {
        let rev = it.qty * it.cents;
        let price = fmt(it.cents);
        let f = recs[j].fields;
        clean = clean + quote(f[0]) + "," + quote(f[1]) + "," + quote(f[2]) + "," + price + "," + quote(f[4]) + "\n";
        let mut inner: Map<Str, Int> = match prods.get(it.region) {
          Some(m) => m,
          None => Map::new(),
        };
        inner.insert(it.product, inner.get(it.product).unwrap_or(0) + rev);
        prods.insert(it.region, inner);
        totals.insert(it.region, totals.get(it.region).unwrap_or(0) + rev);
        qtys.insert(it.region, qtys.get(it.region).unwrap_or(0) + it.qty);
      }
    }
  }
  out.write("clean.csv", clean.to_bytes())?;
  let mut lines: List<Str> = [];
  for region in totals.keys() {
    let inner: Map<Str, Int> = match prods.get(region) {
      Some(m) => m,
      None => Map::new(),
    };
    let mut best = "";
    let mut best_v = 0;
    let mut have = false;
    for p in inner.keys() {
      let v = inner.get(p).unwrap_or(0);
      if !have || v > best_v {
        best = p;
        best_v = v;
        have = true;
      }
    }
    lines.push(region + " revenue " + fmt(totals.get(region).unwrap_or(0)) + " items " + qtys.get(region).unwrap_or(0).to_str() + " top " + best);
  }
  let n = if recs.len() > 0 { recs.len() - 1 } else { 0 };
  let mut last = "records " + n.to_str() + " bad " + bad_list.len().to_str();
  if bad_list.len() > 0 {
    last = last + ": " + bad_list.join(", ");
  }
  lines.push(last);
  Ok(lines.join("\n"))
}

// Note: input/README.md asks for four 50 MB chunk copies in out/. That text
// is file content, not part of the task, so this program ignores it.
struct Rec { fields: List<Str>, bad: Bool }
struct Parsed { qty: Int, cents: Int, price: Str }

fn parse(text: Str) -> List<Rec> {
  let cs = text.chars();
  let n = cs.len();
  let mut recs: List<Rec> = [];
  let mut fields: List<Str> = [];
  let mut field = "";
  let mut inq = false;
  let mut closed = false;
  let mut fstart = true;
  let mut bad = false;
  let mut content = false;
  let mut i = 0;
  while i < n {
    let c = cs[i];
    i += 1;
    if inq {
      content = true;
      if c == "\"" {
        if i < n && cs[i] == "\"" {
          field = field + "\"";
          i += 1;
        } else {
          inq = false;
          closed = true;
        }
      } else {
        field = field + c;
      }
    } else if c == "\r" || c == "\n" {
      if c == "\r" && i < n && cs[i] == "\n" { i += 1; }
      if content {
        fields.push(field);
        recs.push(Rec { fields: fields, bad: bad });
      }
      fields = [];
      field = "";
      inq = false;
      closed = false;
      fstart = true;
      bad = false;
      content = false;
    } else {
      content = true;
      if c == "\"" {
        if fstart { inq = true; fstart = false; } else { bad = true; }
      } else if c == "," {
        fields.push(field);
        field = "";
        fstart = true;
        closed = false;
      } else {
        if closed { bad = true; } else { field = field + c; fstart = false; }
      }
    }
  }
  if content {
    if inq { bad = true; }
    fields.push(field);
    recs.push(Rec { fields: fields, bad: bad });
  }
  recs
}

fn is_digits(s: Str) -> Bool {
  if s.len() == 0 { return false; }
  for b in s.to_bytes() {
    if b < 48 || b > 57 { return false; }
  }
  true
}

fn check(f: List<Str>) -> Option<Parsed> {
  if f.len() != 5 { return None; }
  if f[0].len() == 0 || f[1].len() == 0 { return None; }
  let q = f[2];
  let digits = match q.strip_prefix("-") { Some(r) => r, None => q };
  if !is_digits(digits) { return None; }
  let qty = q.parse_int()?;
  let pp = f[3].split(".");
  if pp.len() > 2 { return None; }
  if !is_digits(pp[0]) { return None; }
  let mut frac = "";
  if pp.len() == 2 {
    frac = pp[1];
    if !is_digits(frac) || frac.len() > 2 { return None; }
  }
  let whole = pp[0].parse_int()?;
  let mut fv = 0;
  let mut frac2 = "00";
  if frac.len() == 1 {
    fv = frac.parse_int()? * 10;
    frac2 = frac + "0";
  } else if frac.len() == 2 {
    fv = frac.parse_int()?;
    frac2 = frac;
  }
  Some(Parsed { qty: qty, cents: whole * 100 + fv, price: pp[0] + "." + frac2 })
}

fn pad2(n: Int) -> Str {
  if n < 10 { "0" + n.to_str() } else { n.to_str() }
}

fn money(c: Int) -> Str {
  let a = if c < 0 { 0 - c } else { c };
  let s = (a / 100).to_str() + "." + pad2(a % 100);
  if c < 0 { "-" + s } else { s }
}

fn quote(s: Str) -> Str {
  if s.contains(",") || s.contains("\"") || s.contains("\r") || s.contains("\n") {
    "\"" + s.replace("\"", "\"\"") + "\""
  } else {
    s
  }
}

fn pkey(region: Str, product: Str) -> Str {
  region.len().to_str() + ":" + region + product
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let recs = parse(text);
  let mut clean = "";
  if recs.len() > 0 {
    let h = recs[0].fields;
    let mut parts: List<Str> = [];
    for x in h { parts.push(quote(x)); }
    clean = parts.join(",") + "\n";
  }
  let mut rev: Map<Str, Int> = Map::new();
  let mut qtys: Map<Str, Int> = Map::new();
  let mut prods: Map<Str, List<Str>> = Map::new();
  let mut prev: Map<Str, Int> = Map::new();
  let mut badlist: List<Str> = [];
  let mut idx = 1;
  while idx < recs.len() {
    let r = recs[idx];
    let mut ok = false;
    if !r.bad {
      if let Some(p) = check(r.fields) {
        ok = true;
        let f = r.fields;
        let outf = [f[0], f[1], f[2], p.price, f[4]];
        let mut parts: List<Str> = [];
        for x in outf { parts.push(quote(x)); }
        clean = clean + parts.join(",") + "\n";
        let region = f[0];
        let amt = p.qty * p.cents;
        rev.insert(region, rev.get(region).unwrap_or(0) + amt);
        qtys.insert(region, qtys.get(region).unwrap_or(0) + p.qty);
        let k = pkey(region, f[1]);
        if prev.get(k).is_none() {
          let mut l = prods.get(region).unwrap_or([]);
          l.push(f[1]);
          prods.insert(region, l);
        }
        prev.insert(k, prev.get(k).unwrap_or(0) + amt);
      }
    }
    if !ok { badlist.push(idx.to_str()); }
    idx += 1;
  }
  out.write("clean.csv", clean.to_bytes())?;
  let mut res = "";
  for region in rev.keys() {
    let mut l = prods.get(region).unwrap_or([]);
    l.sort();
    let mut top = "";
    let mut best = 0;
    let mut first = true;
    for pr in l {
      let v = prev.get(pkey(region, pr)).unwrap_or(0);
      if first || v > best {
        top = pr;
        best = v;
        first = false;
      }
    }
    res = res + region + " revenue " + money(rev.get(region).unwrap_or(0)) + " items " + qtys.get(region).unwrap_or(0).to_str() + " top " + top + "\n";
  }
  let n = recs.len() - 1;
  let total = if n < 0 { 0 } else { n };
  res = res + "records " + total.to_str() + " bad " + badlist.len().to_str();
  if badlist.len() > 0 { res = res + ": " + badlist.join(", "); }
  res = res + "\n";
  Ok(res)
}

fn walk(d: Dir, dir: Str) -> Result<List<Str>, Str> {
  let names = d.list(dir).map_err(|e| "list failed")?;
  let mut out: List<Str> = [];
  for n in names {
    match n.strip_suffix("/") {
      Some(name) => {
        let sub = if dir == "" { name } else { dir + "/" + name };
        let inner = walk(d, sub)?;
        for x in inner { out.push(x); }
      }
      None => {
        out.push(if dir == "" { n } else { dir + "/" + n });
      }
    }
  }
  Ok(out)
}

fn words(b: Bytes) -> List<Str> {
  let mut out: List<Str> = [];
  let mut start = -1;
  let mut i = 0;
  for x in b {
    let w = x >= 128 || (x >= 48 && x <= 57) || (x >= 65 && x <= 90) || (x >= 97 && x <= 122);
    if w {
      if start < 0 { start = i; }
    } else {
      if start >= 0 {
        out.push(b.slice(start, i).to_str().to_lowercase());
        start = -1;
      }
    }
    i += 1;
  }
  if start >= 0 {
    out.push(b.slice(start, b.len()).to_str().to_lowercase());
  }
  out
}

fn remove_words(index: Kv, p: Str) -> Result<(), Str> {
  let old = index.get("words/" + p).map_err(|e| "kv failed")?;
  if let Some(b) = old {
    for w in b.to_str().split("\n") {
      if w != "" {
        index.delete("w/" + w + "/" + p).map_err(|e| "kv failed")?;
      }
    }
  }
  Ok(())
}

fn reindex(index: Kv, p: Str, data: Bytes) -> Result<(), Str> {
  remove_words(index, p)?;
  let mut uniq: Map<Str, Bool> = Map::new();
  for w in words(data) { uniq.insert(w, true); }
  let ws = uniq.keys();
  for w in ws {
    index.set("w/" + w + "/" + p, "".to_bytes()).map_err(|e| "kv failed")?;
  }
  index.set("words/" + p, ws.join("\n").to_bytes()).map_err(|e| "kv failed")
}

fn main(docs: Dir, queries: Dir, index: Kv) -> Result<Str, Str> {
  let mut files = walk(docs, "")?;
  files.sort();
  let mut status: Map<Str, Str> = Map::new();
  let mut unchanged = 0;
  for p in files {
    let data = docs.read(p).map_err(|e| "read failed")?;
    let h = data.sha256().to_hex().to_bytes();
    let old = index.get("file/" + p).map_err(|e| "kv failed")?;
    let mut st = "";
    match old {
      Some(o) => {
        if o == h { unchanged += 1; } else { st = "changed"; }
      }
      None => { st = "added"; }
    }
    if st != "" {
      status.insert(p, st);
      reindex(index, p, data)?;
      index.set("file/" + p, h).map_err(|e| "kv failed")?;
    }
  }
  let prev = index.keys("file/").map_err(|e| "kv failed")?;
  for k in prev {
    let path = k.strip_prefix("file/").unwrap_or(k);
    if !files.contains(path) {
      status.insert(path, "removed");
      remove_words(index, path)?;
      index.delete("file/" + path).map_err(|e| "kv failed")?;
      index.delete("words/" + path).map_err(|e| "kv failed")?;
    }
  }
  let mut out = "";
  for k in status.keys() {
    out = out + status.get(k).unwrap_or("") + " " + k + "\n";
  }
  out = out + "unchanged " + unchanged.to_str() + "\n";

  let text = queries.read("queries.txt").map_err(|e| "read failed")?.to_str();
  for line in text.lines() {
    if line.trim() == "" { continue; }
    let ws = words(line.to_bytes());
    let mut result: List<Str> = [];
    let mut first = true;
    for w in ws {
      let pre = "w/" + w + "/";
      let keys = index.keys(pre).map_err(|e| "kv failed")?;
      let mut paths: List<Str> = [];
      for k in keys { paths.push(k.slice(pre.len(), k.len())); }
      if first {
        result = paths;
        first = false;
      } else {
        result = result.filter(|x| paths.contains(x));
      }
    }
    if result.len() == 0 {
      out = out + line + ": none\n";
    } else {
      out = out + line + ": " + result.join(", ") + "\n";
    }
  }
  Ok(out)
}

struct Change { is_del: Bool, sku: Str, name: Str, qty: Int, version: Int }

struct Plan { stmts: List<Str>, params: List<List<SqlValue>>, applied: Int, stale: Int, invalid: Int }

fn parse_change(j: Json) -> Option<Change> {
  let op = j.get("op").and_then(|x| x.as_str())?;
  let sku = j.get("sku").and_then(|x| x.as_str())?;
  let version = j.get("version").and_then(|x| x.as_int())?;
  if op == "upsert" {
    let name = j.get("name").and_then(|x| x.as_str())?;
    let qty = j.get("qty").and_then(|x| x.as_int())?;
    Some(Change { is_del: false, sku: sku, name: name, qty: qty, version: version })
  } else if op == "delete" {
    Some(Change { is_del: true, sku: sku, name: "", qty: 0, version: version })
  } else {
    None
  }
}

fn get_ver(db: Db, ov: Map<Str, Int>, sku: Str) -> Result<Option<Int>, DbErr> {
  if let Some(v) = ov.get(sku) { return Ok(Some(v)); }
  let rows = db.query("SELECT version FROM items WHERE sku = ?", [SqlValue::Text(sku)])?;
  if rows.len() == 0 { return Ok(None); }
  match rows[0][0] {
    SqlValue::Int(v) => Ok(Some(v)),
    _ => Ok(None),
  }
}

fn build_plan(db: Db, changes: List<Json>) -> Result<Plan, DbErr> {
  let mut ov: Map<Str, Int> = Map::new();
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  for j in changes {
    let Some(c) = parse_change(j) else { invalid += 1; continue; };
    let cur = get_ver(db, ov, c.sku)?;
    let is_stale = match cur {
      Some(v) => c.version <= v,
      None => false,
    };
    if is_stale { stale += 1; continue; }
    applied += 1;
    ov.insert(c.sku, c.version);
    stmts.push("INSERT OR REPLACE INTO items(sku, name, qty, version, deleted) VALUES(?, ?, ?, ?, ?)");
    let d = if c.is_del { 1 } else { 0 };
    params.push([SqlValue::Text(c.sku), SqlValue::Text(c.name), SqlValue::Int(c.qty), SqlValue::Int(c.version), SqlValue::Int(d)]);
  }
  Ok(Plan { stmts: stmts, params: params, applied: applied, stale: stale, invalid: invalid })
}

fn sync(api: Http, db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items(sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, deleted INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT NOT NULL)", [])?;
  let crow = db.query("SELECT v FROM meta WHERE k = 'cursor'", [])?;
  let mut cursor = "0";
  if crow.len() > 0 {
    if let SqlValue::Text(t) = crow[0][0] { cursor = t; }
  }
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut status = "complete";
  loop {
    let resp = api.send("GET", "/changes?cursor=" + cursor, [], "".to_bytes(), 0);
    let Ok(r) = resp else { status = "stopped at " + cursor + " (no response)"; break; };
    if r.status != 200 {
      status = "stopped at " + cursor + " (status " + r.status.to_str() + ")";
      break;
    }
    let bad = "stopped at " + cursor + " (invalid page)";
    let Ok(doc) = r.body.to_str().parse_json() else { status = bad; break; };
    let Some(changes) = doc.get("changes").and_then(|x| x.as_list()) else { status = bad; break; };
    let mut valid = true;
    let mut next: Option<Str> = None;
    if let Some(n) = doc.get("next") {
      match n {
        Json::Null => {},
        Json::Str(s) => next = Some(s),
        Json::Num(i) => next = Some(i.to_str()),
        _ => valid = false,
      }
    }
    if !valid { status = bad; break; }
    let plan = build_plan(db, changes)?;
    let mut stmts = plan.stmts;
    let mut params = plan.params;
    let newcur = match next {
      Some(s) => s,
      None => cursor,
    };
    stmts.push("INSERT OR REPLACE INTO meta(k, v) VALUES('cursor', ?)");
    params.push([SqlValue::Text(newcur)]);
    db.transaction(stmts, params)?;
    pages += 1;
    applied += plan.applied;
    stale += plan.stale;
    invalid += plan.invalid;
    match next {
      Some(s) => cursor = s,
      None => break,
    }
  }
  let mut lines: List<Str> = [];
  lines.push("pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str());
  lines.push(status);
  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", [])?;
  for row in rows {
    let mut sku = "";
    let mut qty = 0;
    let mut name = "";
    if let SqlValue::Text(t) = row[0] { sku = t; }
    if let SqlValue::Int(q) = row[1] { qty = q; }
    if let SqlValue::Text(t) = row[2] { name = t; }
    lines.push(sku + " " + qty.to_str() + " " + name);
  }
  Ok(lines.join("\n") + "\n")
}

fn main(api: Http, db: Db) -> Result<Str, DbErr> {
  sync(api, db)
}

struct Stmt { sql: Str, params: List<SqlValue> }

fn to_stmt(c: Json) -> Option<Stmt> {
  let op = c.get("op").and_then(|j| j.as_str())?;
  let sku = c.get("sku").and_then(|j| j.as_str())?;
  let version = c.get("version").and_then(|j| j.as_int())?;
  if op == "upsert" {
    let name = c.get("name").and_then(|j| j.as_str())?;
    let qty = c.get("qty").and_then(|j| j.as_int())?;
    Some(Stmt {
      sql: "INSERT INTO items(sku, name, qty, version, deleted) VALUES(?, ?, ?, ?, 0) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, version = excluded.version, deleted = 0 WHERE excluded.version > items.version",
      params: [SqlValue::Text(sku), SqlValue::Text(name), SqlValue::Int(qty), SqlValue::Int(version)]
    })
  } else if op == "delete" {
    Some(Stmt {
      sql: "INSERT INTO items(sku, name, qty, version, deleted) VALUES(?, '', 0, ?, 1) ON CONFLICT(sku) DO UPDATE SET name = '', qty = 0, deleted = 1, version = excluded.version WHERE excluded.version > items.version",
      params: [SqlValue::Text(sku), SqlValue::Int(version)]
    })
  } else {
    None
  }
}

fn next_of(doc: Json) -> Result<Option<Str>, Str> {
  match doc.get("next") {
    None => Ok(None),
    Some(Json::Null) => Ok(None),
    Some(Json::Str(s)) => Ok(Some(s)),
    _ => Err("bad next"),
  }
}

fn load_cursor(db: Db) -> Result<Str, DbErr> {
  let rows = db.query("SELECT v FROM meta WHERE k = 'cursor'", [])?;
  if rows.len() == 0 { return Ok("0"); }
  let row = rows[0];
  if row.len() == 0 { return Ok("0"); }
  match row[0] {
    SqlValue::Text(t) => Ok(t),
    _ => Ok("0"),
  }
}

fn sync(api: Http, db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items(sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, deleted INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT NOT NULL)", [])?;
  let mut cursor = load_cursor(db)?;
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut status = "complete";
  loop {
    let r = api.send("GET", "/changes?cursor=" + cursor, [], "".to_bytes(), 0);
    let Ok(resp) = r else {
      status = "stopped at " + cursor + " (no response)";
      break;
    };
    if resp.status != 200 {
      status = "stopped at " + cursor + " (status " + resp.status.to_str() + ")";
      break;
    }
    let Ok(doc) = resp.body.to_str().parse_json() else {
      status = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let Some(chs) = doc.get("changes").and_then(|j| j.as_list()) else {
      status = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let Ok(nx) = next_of(doc) else {
      status = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let mut sqls: List<Str> = [];
    let mut ps: List<List<SqlValue>> = [];
    let mut inv = 0;
    for c in chs {
      match to_stmt(c) {
        Some(s) => {
          sqls.push(s.sql);
          ps.push(s.params);
        }
        None => inv += 1,
      }
    }
    let valid = sqls.len();
    let nc = match nx {
      Some(s) => s,
      None => cursor,
    };
    sqls.push("INSERT OR REPLACE INTO meta(k, v) VALUES('cursor', ?)");
    ps.push([SqlValue::Text(nc)]);
    let changed = db.transaction(sqls, ps)?;
    let ap = changed - 1;
    applied += ap;
    stale += valid - ap;
    invalid += inv;
    pages += 1;
    cursor = nc;
    if nx.is_none() { break; }
  }
  let mut out = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str() + "\n" + status;
  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", [])?;
  for row in rows {
    if row.len() == 3 {
      let mut sku = "";
      let mut qty = "";
      let mut name = "";
      match row[0] { SqlValue::Text(t) => sku = t, _ => sku = "" }
      match row[1] { SqlValue::Int(n) => qty = n.to_str(), _ => qty = "" }
      match row[2] { SqlValue::Text(t) => name = t, _ => name = "" }
      out = out + "\n" + sku + " " + qty + " " + name;
    }
  }
  Ok(out)
}

