}

fn plan_page(db: Db, changes: List<Json>, newc: Str) -> Result<Plan, DbErr> {
  let mut plan = Plan { stmts: [], params: [], applied: 0, stale: 0, invalid: 0 };
  let mut seen: Map<Str, Int> = Map::new();
  for c in changes {
    let Some(ch) = parse_change(c) else { plan.invalid += 1; continue; };
    let last = version_of(db, seen, ch.sku)?;
    let mut is_stale = false;
    if let Some(l) = last {
      if ch.version <= l { is_stale = true; }
    }
    if is_stale {
      plan.stale += 1;
      continue;
    }
    plan.applied += 1;
    seen.insert(ch.sku, ch.version);
    if ch.op == "upsert" {
      plan.stmts.push("INSERT INTO items(sku, name, qty, version, deleted) VALUES(?, ?, ?, ?, 0) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, version = excluded.version, deleted = 0");
      plan.params.push([SqlValue::Text(ch.sku), SqlValue::Text(ch.name), SqlValue::Int(ch.qty), SqlValue::Int(ch.version)]);
    } else {
      plan.stmts.push("INSERT INTO items(sku, name, qty, version, deleted) VALUES(?, '', 0, ?, 1) ON CONFLICT(sku) DO UPDATE SET name = '', qty = 0, version = excluded.version, deleted = 1");
      plan.params.push([SqlValue::Text(ch.sku), SqlValue::Int(ch.version)]);
    }
  }
  plan.stmts.push("INSERT INTO meta(k, v) VALUES('cursor', ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v");
  plan.params.push([SqlValue::Text(newc)]);
  Ok(plan)
}

