fn main(api: Http, db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items(sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, deleted INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT NOT NULL)", [])?;
  let crow = db.query("SELECT v FROM meta WHERE k = 'cursor'", [])?;
  let mut cursor = "0";
  if crow.len() > 0 { cursor = text_of(crow[0][0]); }

  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut status = "complete";
  loop {
    let f = fetch(api, cursor);
    if !f.ok {
      status = "stopped at " + cursor + " (" + f.err + ")";
      break;
    }
    let Some(page) = parse_page(f.body.to_str()) else {
      status = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let mut newc = cursor;
    let mut done = true;
    if let Some(n) = page.next {
      newc = n;
      done = false;
    }
    let plan = plan_page(db, page.changes, newc)?;
    db.transaction(plan.stmts, plan.params)?;
    pages += 1;
    applied += plan.applied;
    stale += plan.stale;
    invalid += plan.invalid;
    if done {
      status = "complete";
      break;
    }
    cursor = newc;
  }

  let mut out = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str() + "\n";
  out = out + status + "\n";
  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", [])?;
