fn apply_page(db: Db, changes: List<Json>, next_cursor: Str) -> Result<List<Int>, DbErr> {
  let mut seen: Map<Str, Int> = Map::new();
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  for ch in changes {
    let Some(op) = ch.get("op").and_then(|j| j.as_str()) else { invalid += 1; continue; };
    let Some(sku) = ch.get("sku").and_then(|j| j.as_str()) else { invalid += 1; continue; };
    let Some(ver) = ch.get("version").and_then(|j| j.as_int()) else { invalid += 1; continue; };
    let mut name = "";
    let mut qty = 0;
    if op == "upsert" {
      let Some(n) = ch.get("name").and_then(|j| j.as_str()) else { invalid += 1; continue; };
      let Some(q) = ch.get("qty").and_then(|j| j.as_int()) else { invalid += 1; continue; };
      name = n;
      qty = q;
    } else if op != "delete" {
      invalid += 1;
      continue;
    }
    let last = match seen.get(sku) {
      Some(v) => Some(v),
      None => last_version(db, sku)?,
    };
    if let Some(l) = last {
      if ver <= l {
        stale += 1;
        continue;
      }
    }
    seen.insert(sku, ver);
    applied += 1;
    if op == "upsert" {
      stmts.push("INSERT OR REPLACE INTO items(sku, name, qty, version, deleted) VALUES(?, ?, ?, ?, 0)");
      params.push([SqlValue::Text(sku), SqlValue::Text(name), SqlValue::Int(qty), SqlValue::Int(ver)]);
    } else {
      stmts.push("INSERT OR REPLACE INTO items(sku, name, qty, version, deleted) VALUES(?, '', 0, ?, 1)");
      params.push([SqlValue::Text(sku), SqlValue::Int(ver)]);
    }
  }
  stmts.push("INSERT OR REPLACE INTO meta(k, v) VALUES('cursor', ?)");
  params.push([SqlValue::Text(next_cursor)]);
  db.transaction(stmts, params)?;
  Ok([applied, stale, invalid])
}

