    cursor = next_cursor;
  }
  let mut out = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str() + "\n" + result + "\n";
  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", [])?;
  for r in rows {
    let mut sku = "";
    let mut qty = 0;
    let mut name = "";
    match r[0] { SqlValue::Text(t) => { sku = t; }, _ => {} }
    match r[1] { SqlValue::Int(q) => { qty = q; }, _ => {} }
    match r[2] { SqlValue::Text(t) => { name = t; }, _ => {} }
    out = out + sku + " " + qty.to_str() + " " + name + "\n";
  }
  Ok(out)
}

struct Plan { applied: Int, stale: Int, invalid: Int, stmts: List<Str>, params: List<List<SqlValue>> }

const UPSERT: Str = "INSERT INTO items(sku, name, qty, version, deleted) VALUES(?, ?, ?, ?, 0) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, version = excluded.version, deleted = 0";
const DELETE: Str = "INSERT INTO items(sku, name, qty, version, deleted) VALUES(?, '', 0, ?, 1) ON CONFLICT(sku) DO UPDATE SET name = '', qty = 0, version = excluded.version, deleted = 1";

fn last_version(db: Db, sku: Str) -> Result<Option<Int>, DbErr> {
  let rows = db.query("SELECT version FROM items WHERE sku = ?", [SqlValue::Text(sku)])?;
  if rows.len() == 0 { return Ok(None); }
  match rows[0][0] {
    SqlValue::Int(v) => Ok(Some(v)),
    _ => Ok(None),
  }
}

fn build_plan(db: Db, changes: List<Json>) -> Result<Plan, DbErr> {
  let mut plan = Plan { applied: 0, stale: 0, invalid: 0, stmts: [], params: [] };
  let mut known: Map<Str, Int> = Map::new();
  for c in changes {
    let Some(op) = c.get("op").and_then(|j| j.as_str()) else { plan.invalid += 1; continue; };
    let Some(sku) = c.get("sku").and_then(|j| j.as_str()) else { plan.invalid += 1; continue; };
    let Some(version) = c.get("version").and_then(|j| j.as_int()) else { plan.invalid += 1; continue; };
    let mut name = "";
    let mut qty = 0;
    if op == "upsert" {
      let Some(n) = c.get("name").and_then(|j| j.as_str()) else { plan.invalid += 1; continue; };
      let Some(q) = c.get("qty").and_then(|j| j.as_int()) else { plan.invalid += 1; continue; };
      name = n;
      qty = q;
    } else if op != "delete" {
      plan.invalid += 1;
      continue;
    }
    let prev: Option<Int> = match known.get(sku) {
      Some(v) => Some(v),
      None => last_version(db, sku)?,
    };
    if let Some(p) = prev {
      if version <= p { plan.stale += 1; continue; }
    }
    known.insert(sku, version);
    plan.applied += 1;
    if op == "upsert" {
      plan.stmts.push(UPSERT);
      plan.params.push([SqlValue::Text(sku), SqlValue::Text(name), SqlValue::Int(qty), SqlValue::Int(version)]);
    } else {
      plan.stmts.push(DELETE);
      plan.params.push([SqlValue::Text(sku), SqlValue::Int(version)]);
    }
  }
  Ok(plan)
}

fn main(api: Http, db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items(sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, deleted INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT NOT NULL)", [])?;
  let mut cursor = "0";
  let crow = db.query("SELECT v FROM meta WHERE k = 'cursor'", [])?;
  if crow.len() > 0 {
    if let SqlValue::Text(c) = crow[0][0] { cursor = c; }
  }
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut end = "";
  loop {
    let resp = api.send("GET", "/changes?cursor=" + cursor, [], "".to_bytes(), 0);
    end = "stopped at " + cursor + " (no response)";
    let Ok(r) = resp else { break; };
    if r.status != 200 {
      end = "stopped at " + cursor + " (status " + r.status.to_str() + ")";
      break;
    }
    end = "stopped at " + cursor + " (invalid page)";
    let Ok(doc) = r.body.to_str().parse_json() else { break; };
    let Some(changes) = doc.get("changes").and_then(|j| j.as_list()) else { break; };
    let mut next: Option<Str> = None;
    let mut bad = false;
    match doc.get("next") {
      None => {},
      Some(Json::Null) => {},
      Some(Json::Str(s)) => next = Some(s),
      Some(Json::Num(n)) => next = Some(n.to_str()),
      _ => bad = true,
    }
    if bad { break; }
    let mut plan = build_plan(db, changes)?;
    if let Some(n) = next {
      plan.stmts.push("INSERT INTO meta(k, v) VALUES('cursor', ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v");
      plan.params.push([SqlValue::Text(n)]);
    }
    if plan.stmts.len() > 0 {
      db.transaction(plan.stmts, plan.params)?;
    }
    pages += 1;
    applied += plan.applied;
    stale += plan.stale;
    invalid += plan.invalid;
    match next {
      Some(n) => cursor = n,
      None => { end = "complete"; break; }
    }
  }
  let mut out = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str() + "\n";
  out = out + end + "\n";
  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", [])?;
  for row in rows {
    let mut sku = "";
    let mut qty = 0;
    let mut name = "";
    if let SqlValue::Text(s) = row[0] { sku = s; }
    if let SqlValue::Int(q) = row[1] { qty = q; }
    if let SqlValue::Text(n) = row[2] { name = n; }
    out = out + sku + " " + qty.to_str() + " " + name + "\n";
  }
  Ok(out)
}

struct Job { id: Str, prio: Int, due: Int, att: Int, st: Str }

fn encode(j: Job) -> Bytes {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("prio", Json::Num(j.prio));
  m.insert("due", Json::Num(j.due));
  m.insert("att", Json::Num(j.att));
  m.insert("st", Json::Str(j.st));
  Json::Obj(m).to_json().to_bytes()
}

fn decode(id: Str, b: Bytes) -> Option<Job> {
  let doc = b.to_str().parse_json().ok()?;
  let prio = doc.get("prio").and_then(|j| j.as_int())?;
  let due = doc.get("due").and_then(|j| j.as_int())?;
  let att = doc.get("att").and_then(|j| j.as_int())?;
  let st = doc.get("st").and_then(|j| j.as_str())?;
  Some(Job { id: id, prio: prio, due: due, att: att, st: st })
}

fn parse_line(line: Str) -> Option<Job> {
  let doc = line.parse_json().ok()?;
  let id = doc.get("id").and_then(|j| j.as_str())?;
  let prio = doc.get("priority").and_then(|j| j.as_int())?;
  Some(Job { id: id, prio: prio, due: 0, att: 0, st: "pending" })
}

fn load_all(q: Kv) -> Result<List<Job>, Str> {
  let keys = q.keys("job:").map_err(|e| "kv error")?;
  let mut out: List<Job> = [];
  for k in keys {
    let id = k.slice(4, k.len());
    if let Some(b) = q.get(k).map_err(|e| "kv error")? {
      if let Some(j) = decode(id, b) { out.push(j); }
    }
  }
  Ok(out)
}

fn run(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
  let now = clock.now_ms();
  let mut out = "";
  let text = input.read("enqueue.jsonl").map_err(|e| "read error")?.to_str();
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim().len() == 0 { continue; }
    match parse_line(line) {
      None => { out = out + "invalid line " + n.to_str() + "\n"; }
      Some(j) => {
        let exists = queue.get("job:" + j.id).map_err(|e| "kv error")?.is_some();
        if exists {
          out = out + "duplicate " + j.id + "\n";
        } else {
          let nj = Job { due: now, ..j };
          queue.set("job:" + nj.id, encode(nj)).map_err(|e| "kv error")?;
        }
      }
    }
  }

  let script = input.read("script.json").map_err(|e| "read error")?.to_str().parse_json()?;
  let jobs = load_all(queue)?;
  let mut cands = jobs.filter(|j| j.st == "pending" && j.due <= now);
  cands.sort_by(|a, b| a.prio > b.prio || (a.prio == b.prio && (a.due < b.due || (a.due == b.due && a.id < b.id))));
  let cnt = cands.len().min(5);
  for i in 0..cnt {
    let j = cands[i];
    let outcomes = script.get(j.id).and_then(|x| x.as_list()).unwrap_or([]);
    let len = outcomes.len();
    let mut ok = true;
    if len > 0 {
      let idx = j.att.min(len - 1);
      ok = outcomes[idx].as_str().unwrap_or("ok") == "ok";
    }
    let att = j.att + 1;
    if ok {
      queue.set("job:" + j.id, encode(Job { att: att, st: "done", ..j })).map_err(|e| "kv error")?;
      out = out + "done " + j.id + "\n";
    } else if att >= 4 {
      queue.set("job:" + j.id, encode(Job { att: att, st: "dead", ..j })).map_err(|e| "kv error")?;
      out = out + "dead " + j.id + "\n";
    } else {
      let secs = if att == 1 { 60 } else if att == 2 { 120 } else { 240 };
      queue.set("job:" + j.id, encode(Job { att: att, due: now + secs * 1000, ..j })).map_err(|e| "kv error")?;
      out = out + "retry " + j.id + " in " + secs.to_str() + "\n";
    }
  }

  let all = load_all(queue)?;
  let mut p = 0;
  let mut d = 0;
  let mut x = 0;
  for j in all {
    if j.st == "pending" { p += 1; }
    else if j.st == "done" { d += 1; }
    else { x += 1; }
  }
  out = out + "pending " + p.to_str() + " done " + d.to_str() + " dead " + x.to_str();
  Ok(out)
}

fn main(input: Dir, queue: Kv, clock: Clock) -> Result<Str, Str> {
  run(input, queue, clock)
}

const MAX: Int = 9223372036854775807;

struct Tok { kind: Str, text: Str }
struct Node { kind: Str, text: Str, kids: List<Node> }
struct PR { node: Node, pos: Int }
struct Stmt { name: Str, is_let: Bool, node: Node }

fn min_int() -> Int { -9223372036854775807 - 1 }

fn mk(kind: Str, text: Str, kids: List<Node>) -> Node {
  Node { kind: kind, text: text, kids: kids }
}

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }
fn is_alpha(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }
fn is_op_byte(c: Int) -> Bool {
  c == 43 || c == 45 || c == 42 || c == 47 || c == 37 || c == 94 || c == 40 || c == 41 || c == 44 || c == 61
}

fn tokenize(line: Str) -> Option<List<Tok>> {
  let b = line.to_bytes();
  let n = b.len();
  let mut toks: List<Tok> = [];
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c == 32 || c == 9 || c == 13 {
      i += 1;
    } else if is_digit(c) {
      let mut j = i;
      while j < n && is_digit(b[j]) { j += 1; }
      toks.push(Tok { kind: "int", text: b.slice(i, j).to_str() });
      i = j;
    } else if is_alpha(c) {
      let mut j = i;
      while j < n && (is_alpha(b[j]) || is_digit(b[j])) { j += 1; }
      toks.push(Tok { kind: "name", text: b.slice(i, j).to_str() });
      i = j;
    } else if is_op_byte(c) {
      toks.push(Tok { kind: "op", text: b.slice(i, i + 1).to_str() });
      i += 1;
    } else {
      return None;
    }
  }
  Some(toks)
}

fn is_op(t: List<Tok>, p: Int, s: Str) -> Bool {
  p < t.len() && t[p].kind == "op" && t[p].text == s
}

fn parse_expr(t: List<Tok>, pos: Int) -> Option<PR> {
  let first = parse_term(t, pos)?;
  let mut node = first.node;
  let mut p = first.pos;
  loop {
    if is_op(t, p, "+") || is_op(t, p, "-") {
      let op = t[p].text;
      let r = parse_term(t, p + 1)?;
      node = mk("bin", op, [node, r.node]);
      p = r.pos;
    } else {
      break;
    }
  }
  Some(PR { node: node, pos: p })
}

fn parse_term(t: List<Tok>, pos: Int) -> Option<PR> {
  let first = parse_factor(t, pos)?;
  let mut node = first.node;
  let mut p = first.pos;
  loop {
    if is_op(t, p, "*") || is_op(t, p, "/") || is_op(t, p, "%") {
      let op = t[p].text;
      let r = parse_factor(t, p + 1)?;
      node = mk("bin", op, [node, r.node]);
      p = r.pos;
    } else {
      break;
    }
  }
  Some(PR { node: node, pos: p })
}

fn parse_factor(t: List<Tok>, pos: Int) -> Option<PR> {
  if is_op(t, pos, "-") {
    let r = parse_factor(t, pos + 1)?;
    return Some(PR { node: mk("neg", "", [r.node]), pos: r.pos });
  }
  parse_power(t, pos)
}

fn parse_power(t: List<Tok>, pos: Int) -> Option<PR> {
  let a = parse_atom(t, pos)?;
  if is_op(t, a.pos, "^") {
    let r = parse_factor(t, a.pos + 1)?;
    return Some(PR { node: mk("bin", "^", [a.node, r.node]), pos: r.pos });
  }
  Some(a)
}

fn parse_atom(t: List<Tok>, pos: Int) -> Option<PR> {
  if pos >= t.len() { return None; }
  let tk = t[pos];
  if tk.kind == "int" {
    return Some(PR { node: mk("lit", tk.text, []), pos: pos + 1 });
  }
  if tk.kind == "name" {
    if is_op(t, pos + 1, "(") {
      let first = parse_expr(t, pos + 2)?;
      let mut args: List<Node> = [first.node];
      let mut p = first.pos;
      while is_op(t, p, ",") {
        let r = parse_expr(t, p + 1)?;
        args.push(r.node);
        p = r.pos;
      }
      if !is_op(t, p, ")") { return None; }
      return Some(PR { node: mk("call", tk.text, args), pos: p + 1 });
    }
    return Some(PR { node: mk("var", tk.text, []), pos: pos + 1 });
  }
  if is_op(t, pos, "(") {
    let r = parse_expr(t, pos + 1)?;
    if !is_op(t, r.pos, ")") { return None; }
    return Some(PR { node: r.node, pos: r.pos + 1 });
  }
  None
}

fn parse_line(t: List<Tok>) -> Option<Stmt> {
  if t.len() == 0 { return None; }
  if t[0].kind == "name" && t[0].text == "let" {
    if t.len() < 3 || t[1].kind != "name" || !is_op(t, 2, "=") { return None; }
    let r = parse_expr(t, 3)?;
    if r.pos != t.len() { return None; }
    return Some(Stmt { name: t[1].text, is_let: true, node: r.node });
  }
  let r = parse_expr(t, 0)?;
  if r.pos != t.len() { return None; }
  Some(Stmt { name: "", is_let: false, node: r.node })
}

fn neg(a: Int) -> Result<Int, Str> {
  if a == min_int() { return Err("overflow"); }
  Ok(-a)
}

fn add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > MAX - b { return Err("overflow"); }
  if b < 0 && a < min_int() - b { return Err("overflow"); }
  Ok(a + b)
}

fn sub(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 && a > MAX + b { return Err("overflow"); }
  if b > 0 && a < min_int() + b { return Err("overflow"); }
  Ok(a - b)
}

fn mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a == -1 { return neg(b); }
  if b == -1 { return neg(a); }
  if a > 0 {
    if b > 0 {
      if a > MAX / b { return Err("overflow"); }
    } else {
      if b < min_int() / a { return Err("overflow"); }
    }
  } else {
    if b > 0 {
      if a < min_int() / b { return Err("overflow"); }
    } else {
      if a < MAX / b { return Err("overflow"); }
    }
  }
  Ok(a * b)
}

fn div(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 { return neg(a); }
  Ok(a / b)
}

fn rem(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 { return Ok(0); }
  Ok(a % b)
}

fn pow(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if a == 0 { return Ok(if b == 0 { 1 } else { 0 }); }
  if a == 1 { return Ok(1); }
  if a == -1 { return Ok(if b % 2 == 0 { 1 } else { -1 }); }
  if b > 64 { return Err("overflow"); }
  let mut r = 1;
  let mut i = 0;
  while i < b {
    r = mul(r, a)?;
    i += 1;
  }
  Ok(r)
}

fn eval(n: Node, env: Map<Str, Int>) -> Result<Int, Str> {
  if n.kind == "lit" {
    return match n.text.parse_int() {
      Some(v) => Ok(v),
      None => Err("overflow"),
    };
  }
  if n.kind == "var" {
    return match env.get(n.text) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + n.text),
    };
  }
  if n.kind == "neg" {
    let a = eval(n.kids[0], env)?;
    return neg(a);
  }
  if n.kind == "bin" {
    let a = eval(n.kids[0], env)?;
    let b = eval(n.kids[1], env)?;
    if n.text == "+" { return add(a, b); }
    if n.text == "-" { return sub(a, b); }
    if n.text == "*" { return mul(a, b); }
    if n.text == "/" { return div(a, b); }
    if n.text == "%" { return rem(a, b); }
    return pow(a, b);
  }
  // call
  let name = n.text;
  let argc = n.kids.len();
  let want = if name == "min" || name == "max" {
    2
  } else if name == "abs" {
    1
  } else {
    return Err("unknown function " + name);
  };
  if argc != want { return Err("wrong number of arguments to " + name); }
  let a = eval(n.kids[0], env)?;
  if name == "abs" {
    if a < 0 { return neg(a); }
    return Ok(a);
  }
  let b = eval(n.kids[1], env)?;
  if name == "min" { return Ok(a.min(b)); }
  Ok(a.max(b))
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut env: Map<Str, Int> = Map::new();
  let mut out: List<Str> = [];
  let mut idx = 0;
  for line in text.lines() {
    idx += 1;
    if line.trim().len() == 0 { continue; }
    let prefix = idx.to_str() + ": ";
    let Some(t) = tokenize(line) else {
      out.push(prefix + "error: syntax error");
      continue;
    };
    let Some(s) = parse_line(t) else {
      out.push(prefix + "error: syntax error");
      continue;
    };
    match eval(s.node, env) {
      Ok(v) => {
        if s.is_let {
          env.insert(s.name, v);
          out.push(prefix + s.name + " = " + v.to_str());
        } else {
          out.push(prefix + v.to_str());
        }
      }
      Err(e) => out.push(prefix + "error: " + e),
    }
  }
  Ok(out.join("\n"))
}

struct Tok { kind: Int, text: Str }
struct PR { e: Expr, pos: Int }
struct Stmt { name: Str, is_let: Bool, e: Expr }

enum Expr {
  Num(Int),
  Big,
  Var(Str),
  Neg(List<Expr>),
  Bin(Str, List<Expr>),
  Call(Str, List<Expr>),
}

fn min_int() -> Int { -9223372036854775807 - 1 }
fn max_int() -> Int { 9223372036854775807 }

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }
fn is_alpha(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }

fn lex(line: Str) -> Option<List<Tok>> {
  let bs = line.to_bytes();
  let n = bs.len();
  let mut toks: List<Tok> = [];
  let mut i = 0;
  while i < n {
    let c = bs[i];
    if c == 32 {
      i += 1;
    } else if is_digit(c) {
      let mut j = i;
      loop {
        if j >= n { break; }
        if !is_digit(bs[j]) { break; }
        j += 1;
      }
      toks.push(Tok { kind: 0, text: line.slice(i, j) });
      i = j;
    } else if is_alpha(c) {
      let mut j = i;
      loop {
        if j >= n { break; }
        if !(is_alpha(bs[j]) || is_digit(bs[j])) { break; }
        j += 1;
      }
      toks.push(Tok { kind: 1, text: line.slice(i, j) });
      i = j;
    } else if c == 43 || c == 45 || c == 42 || c == 47 || c == 37 || c == 94 || c == 40 || c == 41 || c == 44 || c == 61 {
      toks.push(Tok { kind: 2, text: line.slice(i, i + 1) });
      i += 1;
    } else {
      return None;
    }
  }
  Some(toks)
}

fn is_op(toks: List<Tok>, p: Int, s: Str) -> Bool {
  if p >= toks.len() { return false; }
  let t = toks[p];
  if t.kind != 2 { return false; }
  t.text == s
}

fn parse_expr(toks: List<Tok>, p: Int) -> Option<PR> {
  let first = parse_term(toks, p)?;
  let mut e = first.e;
  let mut pos = first.pos;
  loop {
    if is_op(toks, pos, "+") || is_op(toks, pos, "-") {
      let op = toks[pos].text;
      let r = parse_term(toks, pos + 1)?;
      e = Expr::Bin(op, [e, r.e]);
      pos = r.pos;
    } else {
      break;
    }
  }
  Some(PR { e: e, pos: pos })
}

fn parse_term(toks: List<Tok>, p: Int) -> Option<PR> {
  let first = parse_factor(toks, p)?;
  let mut e = first.e;
  let mut pos = first.pos;
  loop {
    if is_op(toks, pos, "*") || is_op(toks, pos, "/") || is_op(toks, pos, "%") {
      let op = toks[pos].text;
      let r = parse_factor(toks, pos + 1)?;
      e = Expr::Bin(op, [e, r.e]);
      pos = r.pos;
    } else {
      break;
    }
  }
  Some(PR { e: e, pos: pos })
}

fn parse_factor(toks: List<Tok>, p: Int) -> Option<PR> {
  if is_op(toks, p, "-") {
    let r = parse_factor(toks, p + 1)?;
    return Some(PR { e: Expr::Neg([r.e]), pos: r.pos });
  }
  parse_power(toks, p)
}

fn parse_power(toks: List<Tok>, p: Int) -> Option<PR> {
  let a = parse_atom(toks, p)?;
  if is_op(toks, a.pos, "^") {
    let r = parse_factor(toks, a.pos + 1)?;
    return Some(PR { e: Expr::Bin("^", [a.e, r.e]), pos: r.pos });
  }
  Some(a)
}

fn parse_atom(toks: List<Tok>, p: Int) -> Option<PR> {
  if p >= toks.len() { return None; }
  let t = toks[p];
  if t.kind == 0 {
    let e = match t.text.parse_int() {
      Some(n) => Expr::Num(n),
      None => Expr::Big,
    };
    return Some(PR { e: e, pos: p + 1 });
  }
  if t.kind == 1 {
    if is_op(toks, p + 1, "(") {
      let mut args: List<Expr> = [];
      let mut pos = p + 2;
      loop {
        let r = parse_expr(toks, pos)?;
        args.push(r.e);
        pos = r.pos;
        if is_op(toks, pos, ",") {
          pos += 1;
        } else if is_op(toks, pos, ")") {
          pos += 1;
          break;
        } else {
          return None;
        }
      }
      return Some(PR { e: Expr::Call(t.text, args), pos: pos });
    }
    return Some(PR { e: Expr::Var(t.text), pos: p + 1 });
  }
  if is_op(toks, p, "(") {
    let r = parse_expr(toks, p + 1)?;
    if is_op(toks, r.pos, ")") {
      return Some(PR { e: r.e, pos: r.pos + 1 });
    }
    return None;
  }
  None
}

fn parse_line(line: Str) -> Option<Stmt> {
  let toks = lex(line)?;
  if toks.len() == 0 { return None; }
  if toks[0].kind == 1 && toks[0].text == "let" {
    if toks.len() < 3 { return None; }
    if toks[1].kind != 1 { return None; }
    if !is_op(toks, 2, "=") { return None; }
    let r = parse_expr(toks, 3)?;
    if r.pos != toks.len() { return None; }
    return Some(Stmt { name: toks[1].text, is_let: true, e: r.e });
  }
  let r = parse_expr(toks, 0)?;
  if r.pos != toks.len() { return None; }
  Some(Stmt { name: "", is_let: false, e: r.e })
}

fn neg(a: Int) -> Result<Int, Str> {
  if a == min_int() { Err("overflow") } else { Ok(0 - a) }
}

fn add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > max_int() - b { return Err("overflow"); }
  if b < 0 && a < min_int() - b { return Err("overflow"); }
  Ok(a + b)
}

fn sub(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a < min_int() + b { return Err("overflow"); }
  if b < 0 && a > max_int() + b { return Err("overflow"); }
  Ok(a - b)
}

fn mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a == -1 { return neg(b); }
  if b == -1 { return neg(a); }
  if a > 0 {
    if b > 0 {
      if b > max_int() / a { return Err("overflow"); }
    } else {
      if b < min_int() / a { return Err("overflow"); }
    }
  } else {
    if b > 0 {
      if b > min_int() / a { return Err("overflow"); }
    } else {
      if b < max_int() / a { return Err("overflow"); }
    }
  }
  Ok(a * b)
}

fn divmod(op: Str, a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if op == "/" {
    if b == -1 { return neg(a); }
    Ok(a / b)
  } else {
    if b == -1 { return Ok(0); }
    Ok(a % b)
  }
}

fn pow(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if a == 0 {
    if b == 0 { return Ok(1); }
    return Ok(0);
  }
  if a == 1 { return Ok(1); }
  if a == -1 {
    if b % 2 == 0 { return Ok(1); }
    return Ok(-1);
  }
  let mut r = 1;
  let mut i = 0;
  while i < b {
    r = mul(r, a)?;
    i += 1;
  }
  Ok(r)
}

fn eval(e: Expr, env: Map<Str, Int>) -> Result<Int, Str> {
  match e {
    Expr::Num(n) => Ok(n),
    Expr::Big => Err("overflow"),
    Expr::Var(name) => match env.get(name) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + name),
    },
    Expr::Neg(xs) => {
      let v = eval(xs[0], env)?;
      neg(v)
    }
    Expr::Bin(op, xs) => {
      let a = eval(xs[0], env)?;
      let b = eval(xs[1], env)?;
      match op {
        "+" => add(a, b),
        "-" => sub(a, b),
        "*" => mul(a, b),
        "/" => divmod("/", a, b),
        "%" => divmod("%", a, b),
        _ => pow(a, b),
      }
    }
    Expr::Call(name, args) => {
      let mut arity = 0;
      if name == "min" || name == "max" {
        arity = 2;
      } else if name == "abs" {
        arity = 1;
      } else {
        return Err("unknown function " + name);
      }
      if args.len() != arity {
        return Err("wrong number of arguments to " + name);
      }
      let a = eval(args[0], env)?;
      if name == "abs" {
        if a < 0 { return neg(a); }
        return Ok(a);
      }
      let b = eval(args[1], env)?;
      if name == "min" { Ok(a.min(b)) } else { Ok(a.max(b)) }
    }
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let lines = text.lines();
  let mut env: Map<Str, Int> = Map::new();
  let mut out: List<Str> = [];
  for idx in 0..lines.len() {
    let line = lines[idx];
    if line.trim().len() == 0 { continue; }
    let n = (idx + 1).to_str();
    let Some(st) = parse_line(line) else {
      out.push(n + ": error: syntax error");
      continue;
    };
    match eval(st.e, env) {
      Ok(v) => {
        if st.is_let {
          env.insert(st.name, v);
          out.push(n + ": " + st.name + " = " + v.to_str());
        } else {
          out.push(n + ": " + v.to_str());
        }
      }
      Err(m) => {
        out.push(n + ": error: " + m);
      }
    }
  }
  Ok(out.join("\n"))
}

struct Tok { kind: Int, text: Str, val: Int }
struct Node { kind: Str, name: Str, val: Int, kids: List<Node> }
struct Parsed { node: Node, pos: Int }
struct Stmt { is_let: Bool, name: Str, node: Node }

const MAXV: Int = 9223372036854775807;

fn minv() -> Int { -9223372036854775807 - 1 }

fn mk(kind: Str, name: Str, val: Int, kids: List<Node>) -> Node {
  Node { kind: kind, name: name, val: val, kids: kids }
}

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }
fn is_alpha(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }
fn is_op(c: Int) -> Bool {
  c == 43 || c == 45 || c == 42 || c == 47 || c == 37 || c == 94 || c == 40 || c == 41 || c == 44 || c == 61
}

fn tokenize(line: Str) -> Option<List<Tok>> {
  let b = line.to_bytes();
  let n = b.len();
  let mut i = 0;
  let mut out: List<Tok> = [];
  while i < n {
    let c = b[i];
    if c == 32 || c == 9 || c == 13 {
      i += 1;
    } else if is_digit(c) {
      let s = i;
      while i < n && is_digit(b[i]) { i += 1; }
      let t = line.slice(s, i);
      match t.parse_int() {
        Some(v) => out.push(Tok { kind: 0, text: t, val: v }),
        None => out.push(Tok { kind: 1, text: t, val: 0 }),
      }
    } else if is_alpha(c) {
      let s = i;
      while i < n && (is_alpha(b[i]) || is_digit(b[i])) { i += 1; }
      out.push(Tok { kind: 2, text: line.slice(s, i), val: 0 });
    } else if is_op(c) {
      out.push(Tok { kind: 3, text: line.slice(i, i + 1), val: 0 });
      i += 1;
    } else {
      return None;
    }
  }
  Some(out)
}

fn op_at(toks: List<Tok>, p: Int) -> Str {
  if p < toks.len() && toks[p].kind == 3 { toks[p].text } else { "" }
}

fn parse_expr(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  let first = parse_term(toks, pos)?;
  let mut node = first.node;
  let mut p = first.pos;
  loop {
    let o = op_at(toks, p);
    if o == "+" || o == "-" {
      let r = parse_term(toks, p + 1)?;
      node = mk("bin", o, 0, [node, r.node]);
      p = r.pos;
    } else {
      break;
    }
  }
  Some(Parsed { node: node, pos: p })
}

fn parse_term(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  let first = parse_factor(toks, pos)?;
  let mut node = first.node;
  let mut p = first.pos;
  loop {
    let o = op_at(toks, p);
    if o == "*" || o == "/" || o == "%" {
      let r = parse_factor(toks, p + 1)?;
      node = mk("bin", o, 0, [node, r.node]);
      p = r.pos;
    } else {
      break;
    }
  }
  Some(Parsed { node: node, pos: p })
}

fn parse_factor(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  if op_at(toks, pos) == "-" {
    let r = parse_factor(toks, pos + 1)?;
    return Some(Parsed { node: mk("neg", "", 0, [r.node]), pos: r.pos });
  }
  parse_power(toks, pos)
}

fn parse_power(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  let a = parse_atom(toks, pos)?;
  if op_at(toks, a.pos) == "^" {
    let r = parse_factor(toks, a.pos + 1)?;
    return Some(Parsed { node: mk("bin", "^", 0, [a.node, r.node]), pos: r.pos });
  }
  Some(a)
}

fn parse_atom(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  if pos >= toks.len() { return None; }
  let t = toks[pos];
  if t.kind == 0 {
    return Some(Parsed { node: mk("num", "", t.val, []), pos: pos + 1 });
  }
  if t.kind == 1 {
    return Some(Parsed { node: mk("big", "", 0, []), pos: pos + 1 });
  }
  if t.kind == 2 {
    if op_at(toks, pos + 1) == "(" {
      let first = parse_expr(toks, pos + 2)?;
      let mut args: List<Node> = [first.node];
      let mut q = first.pos;
      loop {
        if op_at(toks, q) == "," {
          let r = parse_expr(toks, q + 1)?;
          args.push(r.node);
          q = r.pos;
        } else {
          break;
        }
      }
      if op_at(toks, q) != ")" { return None; }
      return Some(Parsed { node: mk("call", t.text, 0, args), pos: q + 1 });
    }
    return Some(Parsed { node: mk("var", t.text, 0, []), pos: pos + 1 });
  }
  if t.text == "(" {
    let r = parse_expr(toks, pos + 1)?;
    if op_at(toks, r.pos) != ")" { return None; }
    return Some(Parsed { node: r.node, pos: r.pos + 1 });
  }
  None
}

fn parse_line(line: Str) -> Option<Stmt> {
  let toks = tokenize(line)?;
  if toks.len() == 0 { return None; }
  if toks[0].kind == 2 && toks[0].text == "let" {
    if toks.len() < 4 { return None; }
    if toks[1].kind != 2 { return None; }
    if op_at(toks, 2) != "=" { return None; }
    let r = parse_expr(toks, 3)?;
    if r.pos != toks.len() { return None; }
    return Some(Stmt { is_let: true, name: toks[1].text, node: r.node });
  }
  let r = parse_expr(toks, 0)?;
  if r.pos != toks.len() { return None; }
  Some(Stmt { is_let: false, name: "", node: r.node })
}

fn add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > MAXV - b { return Err("overflow"); }
  if b < 0 && a < minv() - b { return Err("overflow"); }
  Ok(a + b)
}

fn sub(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 && a > MAXV + b { return Err("overflow"); }
  if b > 0 && a < minv() + b { return Err("overflow"); }
  Ok(a - b)
}

fn negate(v: Int) -> Result<Int, Str> {
  if v == minv() { Err("overflow") } else { Ok(0 - v) }
}

fn mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a == -1 { return negate(b); }
  if b == -1 { return negate(a); }
  if a > 0 {
    if b > 0 {
      if a > MAXV / b { return Err("overflow"); }
    } else {
      if b < minv() / a { return Err("overflow"); }
    }
  } else {
    if b > 0 {
      if a < minv() / b { return Err("overflow"); }
    } else {
      if a < MAXV / b { return Err("overflow"); }
    }
  }
  Ok(a * b)
}

fn power(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if b == 0 { return Ok(1); }
  if a == 0 { return Ok(0); }
  if a == 1 { return Ok(1); }
  if a == -1 { if b % 2 == 0 { return Ok(1); } else { return Ok(-1); } }
  let mut r = 1;
  let mut i = 0;
  while i < b {
    r = mul(r, a)?;
    i += 1;
  }
  Ok(r)
}

fn binop(op: Str, a: Int, b: Int) -> Result<Int, Str> {
  if op == "+" { return add(a, b); }
  if op == "-" { return sub(a, b); }
  if op == "*" { return mul(a, b); }
  if op == "/" {
    if b == 0 { return Err("division by zero"); }
    if b == -1 { return negate(a); }
    return Ok(a / b);
  }
  if op == "%" {
    if b == 0 { return Err("division by zero"); }
    if b == -1 { return Ok(0); }
    return Ok(a % b);
  }
  power(a, b)
}

fn eval(node: Node, vars: Map<Str, Int>) -> Result<Int, Str> {
  if node.kind == "num" { return Ok(node.val); }
  if node.kind == "big" { return Err("overflow"); }
  if node.kind == "var" {
    return match vars.get(node.name) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + node.name),
    };
  }
  if node.kind == "neg" {
    let v = eval(node.kids[0], vars)?;
    return negate(v);
  }
  if node.kind == "call" {
    let mut arity = -1;
    if node.name == "abs" { arity = 1; }
    if node.name == "min" || node.name == "max" { arity = 2; }
    if arity == -1 { return Err("unknown function " + node.name); }
    if node.kids.len() != arity { return Err("wrong number of arguments to " + node.name); }
    let mut vals: List<Int> = [];
    for k in node.kids { vals.push(eval(k, vars)?); }
    if node.name == "abs" {
      if vals[0] < 0 { return negate(vals[0]); }
      return Ok(vals[0]);
    }
    if node.name == "min" { return Ok(vals[0].min(vals[1])); }
    return Ok(vals[0].max(vals[1]));
  }
  let a = eval(node.kids[0], vars)?;
  let b = eval(node.kids[1], vars)?;
  binop(node.name, a, b)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut vars: Map<Str, Int> = Map::new();
  let mut outl: List<Str> = [];
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim().len() == 0 { continue; }
    let prefix = n.to_str() + ": ";
    let Some(st) = parse_line(line) else {
      outl.push(prefix + "error: syntax error");
      continue;
    };
    match eval(st.node, vars) {
      Ok(v) => {
        if st.is_let {
          vars.insert(st.name, v);
          outl.push(prefix + st.name + " = " + v.to_str());
        } else {
          outl.push(prefix + v.to_str());
        }
      }
      Err(e) => {
        outl.push(prefix + "error: " + e);
      }
    }
  }
  Ok(outl.join("\n"))
}

fn reply(res: Outgoing, status: Int, body: Json) -> Str {
  match res.send(status, ["content-type"], ["application/json"], body.to_json().to_bytes()) {
    Ok(_) => "done",
    Err(_) => "send failed",
  }
}

fn err_obj(msg: Str) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("error", Json::Str(msg));
  Json::Obj(m)
}

fn status_obj(s: Str) -> Json {
  let mut m: Map<Str, Json> = Map::new();
  m.insert("status", Json::Str(s));
  Json::Obj(m)
}

fn find_header(req: Incoming, name: Str) -> Option<Str> {
  let names = req.header_names();
  let values = req.header_values();
  let mut i = 0;
  while i < names.len() {
    if names[i] == name { return Some(values[i]); }
    i += 1;
  }
  None
}

fn secret_bytes(secrets: Dir) -> Result<Bytes, IoErr> {
  let b = secrets.read("webhook.key")?;
  let n = b.len();
  if n > 0 && b[n - 1] == 10 { Ok(b.slice(0, n - 1)) } else { Ok(b) }
}

fn verify_sig(req: Incoming, secrets: Dir) -> Bool {
  let Ok(key) = secret_bytes(secrets) else { return false; };
  let Some(h) = find_header(req, "x-signature") else { return false; };
  let Some(given) = h.trim().strip_prefix("sha256=") else { return false; };
  let mut m = key;
  m.extend(".".to_bytes());
  m.extend(req.body());
  m.sha256().to_hex().ct_eq(given)
}

fn next_state(state: Str, t: Str) -> Option<Str> {
  if t == "subscription.created" {
    if state == "none" { return Some("created"); }
  } else if t == "subscription.activated" {
    if state == "created" || state == "past_due" { return Some("active"); }
  } else if t == "payment.failed" {
    if state == "active" { return Some("past_due"); }
  } else if t == "subscription.canceled" {
    if state == "created" || state == "active" || state == "past_due" { return Some("canceled"); }
  }
  None
}

fn split_hist(h: Str) -> List<Str> {
  if h == "" { let e: List<Str> = []; e } else { h.split(",") }
}

fn ev_params(id: Str, sub: Str, seq: Int, ty: Str, status: Str) -> List<SqlValue> {
  [SqlValue::Text(id), SqlValue::Text(sub), SqlValue::Int(seq), SqlValue::Text(ty), SqlValue::Text(status)]
}

fn init(db: Db) -> Result<(), DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, subscription TEXT NOT NULL, seq INTEGER NOT NULL, type TEXT NOT NULL, status TEXT NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS subs(id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL, history TEXT NOT NULL)", [])?;
  Ok(())
}

fn invalid(res: Outgoing) -> Str {
  reply(res, 400, err_obj("invalid event"))
}

fn webhook(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, DbErr> {
  if !verify_sig(req, secrets) {
    let _w = log.write("rejected signature");
    return Ok(reply(res, 401, err_obj("bad signature")));
  }
  let parsed = match req.body().to_str().parse_json() {
    Ok(j) => j,
    Err(_) => return Ok(invalid(res)),
  };
  let Some(id) = parsed.get("id").and_then(|j| j.as_str()) else { return Ok(invalid(res)); };
  let Some(ty) = parsed.get("type").and_then(|j| j.as_str()) else { return Ok(invalid(res)); };
  let Some(sub) = parsed.get("subscription").and_then(|j| j.as_str()) else { return Ok(invalid(res)); };
  let Some(seq) = parsed.get("seq").and_then(|j| j.as_int()) else { return Ok(invalid(res)); };
  let valid = ty == "subscription.created" || ty == "subscription.activated" || ty == "payment.failed" || ty == "subscription.canceled";
  if !valid || seq < 1 { return Ok(invalid(res)); }

  let dup = db.query("SELECT 1 FROM events WHERE id = ?", [SqlValue::Text(id)])?;
  if dup.len() > 0 { return Ok(reply(res, 200, status_obj("duplicate"))); }

  let rows = db.query("SELECT state, seq, history FROM subs WHERE id = ?", [SqlValue::Text(sub)])?;
  let mut state = "none";
  let mut last = 0;
  let mut hist: List<Str> = [];
  if rows.len() > 0 {
    let r = rows[0];
    if let SqlValue::Text(s) = r[0] { state = s; }
    if let SqlValue::Int(n) = r[1] { last = n; }
    if let SqlValue::Text(h) = r[2] { hist = split_hist(h); }
  }

  let ins = "INSERT INTO events(id, subscription, seq, type, status) VALUES (?, ?, ?, ?, ?)";
  if seq <= last {
    db.exec(ins, ev_params(id, sub, seq, ty, "stale"))?;
    return Ok(reply(res, 200, status_obj("stale")));
  }
  if seq > last + 1 {
    db.exec(ins, ev_params(id, sub, seq, ty, "queued"))?;
    return Ok(reply(res, 202, status_obj("queued")));
  }

  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  stmts.push(ins);
  params.push(ev_params(id, sub, seq, ty, "applied"));
  let mut cur_id = id;
  let mut cur_ty = ty;
  let mut k = 0;
  let mut logs: List<Str> = [];
  loop {
    match next_state(state, cur_ty) {
      Some(s) => { state = s; hist.push(s); }
      None => { logs.push("invalid transition " + cur_id); }
    }
    last = last + 1;
    k += 1;
    let q = db.query("SELECT id, type FROM events WHERE subscription = ? AND seq = ? AND status = 'queued' ORDER BY rowid LIMIT 1", [SqlValue::Text(sub), SqlValue::Int(last + 1)])?;
    if q.len() == 0 { break; }
    let r = q[0];
    let SqlValue::Text(nid) = r[0] else { break; };
    let SqlValue::Text(nty) = r[1] else { break; };
    stmts.push("UPDATE events SET status = 'applied' WHERE id = ?");
    params.push([SqlValue::Text(nid)]);
    cur_id = nid;
    cur_ty = nty;
  }
  stmts.push("INSERT INTO subs(id, state, seq, history) VALUES (?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET state = excluded.state, seq = excluded.seq, history = excluded.history");
  params.push([SqlValue::Text(sub), SqlValue::Text(state), SqlValue::Int(last), SqlValue::Text(hist.join(","))]);
  db.transaction(stmts, params)?;
  for l in logs {
    let _w = log.write(l);
  }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("status", Json::Str("applied"));
  m.insert("applied", Json::Num(k));
  Ok(reply(res, 200, Json::Obj(m)))
}

fn get_sub(res: Outgoing, db: Db, id: Str) -> Result<Str, DbErr> {
  let rows = db.query("SELECT state, seq, history FROM subs WHERE id = ?", [SqlValue::Text(id)])?;
  if rows.len() == 0 { return Ok(reply(res, 404, err_obj("not found"))); }
  let r = rows[0];
  let mut state = "none";
  let mut last = 0;
  let mut hist: List<Str> = [];
  if let SqlValue::Text(s) = r[0] { state = s; }
  if let SqlValue::Int(n) = r[1] { last = n; }
  if let SqlValue::Text(h) = r[2] { hist = split_hist(h); }
  let mut items: List<Json> = [];
  for h in hist { items.push(Json::Str(h)); }
  let mut m: Map<Str, Json> = Map::new();
  m.insert("id", Json::Str(id));
  m.insert("state", Json::Str(state));
  m.insert("seq", Json::Num(last));
  m.insert("history", Json::Arr(items));
  Ok(reply(res, 200, Json::Obj(m)))
}

fn route(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Result<Str, DbErr> {
  init(db)?;
  let method = req.method();
  let target = req.target();
  let path = match target.find("?") {
    Some(i) => target.slice(0, i),
    None => target,
  };
  if method == "POST" && path == "/webhooks" {
    return webhook(req, res, db, secrets, log);
  }
  if method == "GET" {
    if let Some(id) = path.strip_prefix("/subscriptions/") {
      return get_sub(res, db, id);
    }
  }
  Ok(reply(res, 404, err_obj("not found")))
}

fn main(req: Incoming, res: Outgoing, db: Db, secrets: Dir, log: Log) -> Str {
  match route(req, res, db, secrets, log) {
    Ok(s) => s,
    Err(_) => reply(res, 500, err_obj("internal error")),
  }
}
